-- ============================================================
-- Qazax3h (8/8) — DB kontentinin Qazax (kk) tərcüməsi
-- COALESCE + guarded UPDATE — mövcud/əl tərcümələri qorunur (idempotent).
-- Cəmi: 6171 UPDATE (day-notifications İSTİSNA — bax Qazax4)
-- ƏVVƏL Qazax1.sql (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, '3-триместрде бөпеңіздің миы қарқынды дамуын жалғастырғанымен, басының өсу жылдамдығы денесінің басқа бөліктерімен салыстырғанда баяуырақ болады. Бөпеңіздің миы ана құрсағындағы 3-аптада қалыптаса бастайды. Жүйке жүйесі — бөпенің ана құрсағындағы даму кезеңінде ең ерте пайда болып, дамуы босанғаннан кейін ең кеш аяқталатын жүйе. Осы аптадан бастап нейрондардың қалыптасуы аяқталады. Алдыңғы 9 апта ішінде нейрондар түрлерге бөлініп, саны бірнеше есе артқан еді. 32-аптада олар мидың ең сыртқы қабаты — қыртыстың төменгі бөліктеріне қарай жылжи бастайды. Дәл осы үдеріс кезінде ми мен жүйке жүйесінің жалпы құрылымы толық қалыптасады. Босану уақыты келгенде ми өзінің соңғы қалпына келіп үлгереді және одан кейін айтарлықтай өзгермейді.'), baby_message_kk = COALESCE(baby_message_kk, '5 сезім мүшем де жұмыс істейді! 🖐️ Мен енді толық дайынмын: көремін, естимін, дәм сеземін, иіс сеземін және жанасуды сеземін. Сенің даусыңды естігенде басымды бұрамын. Жарық түскенде көзімді жыпылықтатамын. Қағанақ суының дәмінен сенің не жегеніңді білемін. Мен әлемді танып-білуге дайынмын!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Жапырақты салат'), body_changes_kk = COALESCE(body_changes_kk, 'Ана құрсағындағы бөпенің анасы арқылы сезінетін психологиялық күйі медицинада «эмбрион психологиясы» деп аталады. Жүктілік кезінде ананың эмоциялық әлемі қалай қалыптасса, құрсағындағы бөпенің де эмоциялық әлемі сол оқиғалардың әсерімен қалыптасады. Генетикалық мінезден бөлек, баланың ана құрсағында қалыптаса бастаған алғашқы сәтінен бастап дамитын психологиялық мінезі де болады. Психологиялық мінез — ананың қуанышы, толқуы, ашуы мен мұңына байланысты генетикалық мінездің негізінде қалыптасатын екінші мінез. Ана құрсағында дами бастайтын бұл мінез 6 жасқа дейін қалыптасуын жалғастырып, адамның бүкіл өміріне әсер етеді. Бөпеңіздің Сізге физиологиялық тұрғыдан ғана емес, психологиялық жағынан да байланысты екенін ешқашан ұмытпаңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Кеудеге арналған төсемдерді пайдаланып, киіміңізді қорғай аласыз. Емізіктеріңізді сабынмен жумаңыз, өйткені сабын оларды құрғатып, жарылуына әкеледі. Жай ғана жылы сумен жуу жеткілікті.') WHERE id = 'fc626924-530b-4871-85a2-84474a5bcec0';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Қағанақ суы — бөпе жататын стерильді, түссіз әрі қорғаныш қызметін атқаратын сұйықтық. Оның бір бөлігі жатыр ішіндегі "амнион жасушалары" арқылы түзілгенімен, негізгі бөлігін ана ағзасынан алады. Бұл сұйықтық бөпеңіздің жатыр ішінде еркін қозғалуына мүмкіндік беріп қана қоймай, оны соққыдан, инфекциялардан және температураның өзгеруінен қорғайды. Жүктілік кезінде температураны 37 градуста тұрақты ұстайтын қағанақ суы бөпеңізге қыста суықтың, ал жазда ыстықтың әсер етуіне жол бермейді. 2-ші триместрде қағанақ суының мөлшері бөпенің салмағына сай артады. 32-ші аптада бұл сұйықтықтың көлемі 1 литрге жетеді — бұл қағанақ суының ең жоғары мөлшері. Бөпенің көбірек салмақ қосуына мүмкіндік беру үшін осы аптадан бастап босанғанға дейін қағанақ суы шамамен 150-250 ml азайып, орта есеппен 750-800 ml деңгейінде тұрақталады.'), baby_message_kk = COALESCE(baby_message_kk, 'Тырнақтарым қатты өсіп кетті! 💅 Тырнақтарым саусақ ұштарымнан асып тұр. Кейде байқамай бетімді тырнап аламын. Мен дүниеге келгенде қолғап немесе тырнақ қайшысын дайындап қойыңызшы. Мен әлі өзіме күтім жасай алмаймын. Маған көмектесесіз ғой, солай ма?'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Жапырақты салат'), body_changes_kk = COALESCE(body_changes_kk, 'Ентігу Сізді шаршатуы мүмкін. Жатыр ең жоғары нүктесіне — қабырға доғасына жетуге жақын. Ол көкетті қысып, өкпенің толық жазылуына кедергі келтіреді. Баспалдақпен көтерілу немесе жылдам жүру қиындайды.;;;
Емшегіңізден "уыздың" бөлінуі артуы мүмкін. Ағзаңыз босанғаннан кейінгі алғашқы қоректендіруге арналған "алтын сұйықтықты" дайындап жатыр. Омырауыңыз ауырлап, сезімтал болуы мүмкін. Ішіңіздің терісі барынша керілген.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қуыққа түсетін қысымды азайту үшін құрамында кофеин бар сусындарды барынша шектеңіз, өйткені олардың несеп айдайтын әсері бар. Белдің ауырсынуын жеңілдету үшін ұйықтағанда аяқтарыңыздың арасына және ішіңіздің астына кішкентай жастықтар қойыңыз. Кальций мен темір қабылдауды жалғастырыңыз, өйткені бөпеңіз қазір бұл элементтерді жылдам "жинап" жатыр. Бүгін өзіңізді қатты шаршатпаңыз.') WHERE id = 'b016d6e4-baac-45d0-93bb-1a801a1ac462';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, '16-шы аптадан бастап ести бастаған бөпеңіз осы аптаның соңында естігенін есте сақтап, оған жауап бере алады. Ата-анасының дауысын тани бастаған бөпе ата-анасының бірі онымен сөйлескенде толқып, жүрек соғысы жиілейді және жауап беруге тырысады. Бұл бөпеңіздің миы қаншалықты жылдам дамып келе жатқанын көрсетеді. Осы кезеңнің соңында өкпе газ алмасуды жүзеге асыра алатын жағдайға жеткенімен, әлі де жеткілікті дәрежеде жетілмеген. Өкпе толық дамығанда микроорганизмдерден қорғануды қамтамасыз ете алады. Сонымен қатар, ол сұйықтық пен электролит теңгерімін реттеуге қатысады. Қандағы сутегі мен йод теңгерімін реттейді. Сөйлеуге қажетті кейбір дыбыстардың түзілуіне көмектеседі.'), baby_message_kk = COALESCE(baby_message_kk, '32 АПТА! 🎃 Менің көлемім жапырақты салаттай! Мен енді "ауыр салмақтымын". Қазір жатыр маған тарлық етеді. Аяқтарымды толық жаза алмаймын, сондықтан "эмбрион қалпында" жатамын. Бұл — мен үшін ең ыңғайлы қалып.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Жапырақты салат'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде қаныңыздағы эстроген гормонының жоғары мөлшері ағзадағы бөлінділердің көбеюіне әкеледі. Соның салдарынан жүктілікке дейінгі кезеңмен салыстырғанда көбірек түзілетін шырыш мұрын ішіндегі қан тамырларының ісінуіне себеп болуы мүмкін. Бұл мұрынның бітелуіне әкеліп, жүкті әйелдерге жайсыздық тудырады. Массаж мұрын жолдарындағы қан айналымын жақсартып, шырыштың қоюлығын азайтады. Осылайша тыныс алуыңыз жеңілдейді. Суды жеткілікті ішу, жылы душ қабылдау, мұрын айналасына жылы компресс қою және басты биігірек ұстау да мұрын бітелуін жеңілдетуге көмектеседі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Дәрігерге жоспарланған қабылдауларды өткізіп алмаңыз. Осы апталарда қан қысымын өлшеу және несептегі ақуызды тексеру ("преэклампсия" қаупін бағалау үшін) өте маңызды. Басыңыз ауырса немесе көруіңіз бұлыңғырланса, бұл туралы дереу хабарлаңыз.') WHERE id = '33dd2de9-c534-420c-8e3d-e027683ad6e9';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің терісінде түзілген верникс қабаты қажетті оңтайлы мөлшеріне жетті. Верникс қабаты бөпеңіз әлі жатырда жатқан кезде оны қорғайтын сыртқы қабат қызметін атқарады. Оның құрамында 80% су, 10% май және 10% ақуыз қосылыстары бар.;;;
Ал босану кезінде ол теріні ауаның құрғату әсерінен және зиянды микроорганизмдерден қорғайды, терідегі ылғалды сақтап, құрғауына жол бермейді, терінің pH теңгерімін белгілі бір деңгейде ұстайды және бөпеңізді босану кезіндегі ықтимал инфекциялар мен жарақаттардан қорғайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен түс көремін! 💤 Ми толқындарым менің терең және жеңіл ұйқы кезеңдерінен өтетінімді көрсетеді. Ұйықтап жатып жымиып, қабағымды түйемін, тіпті көздерімді қозғалтамын. Менің миым ересек адамның миы сияқты жұмыс істей бастады. Мен қиялшыл бөпемін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Жапырақты салат'), body_changes_kk = COALESCE(body_changes_kk, 'Түнгі ұйқысыздық пен аяқтың құрысуы Сізді шаршатуы мүмкін. Ішіңіздің үлкеюі төсекте бір қырыңыздан екінші қырыңызға аунап жатуды қиындатады. Тепе-теңдікті сақтау қиындағандықтан, баяу қозғалыңыз. Ұйқысыздық ашушаңдық тудыруы мүмкін, сондықтан күндіз демалуға тырысыңыз.;;;
Қуыққа түсетін қысым артуы мүмкін, бірақ қыжыл мен ентігу біршама азаюы ықтимал. Бөпенің басы төмен түскен сайын жоғарғы ағзаларға түсетін қысым азаяды, алайда төменгі ағзаларға (қуыққа, жамбас сүйектеріне) қысым түседі. "Пингвин жүрісімен" жүре бастауыңыз мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Аяқтарыңыздағы ісінуді азайту үшін жеткілікті мөлшерде су ішуді жалғастырып, тұзды барынша шектеңіз. Өкпеңіз еркінірек кеңеюі үшін отырғанда арқаңызды тік ұстауға тырысыңыз. Осы апта — босану жоспарын (аурухана таңдау, дәрігермен кеңесу) нақтылауға ең қолайлы уақыт. Кешке ішіңізге жеңіл массаж жасаңыз, бөпеңіз бұл жанасуды қазір өте анық сезеді.') WHERE id = '7757d4d7-3e07-45ad-b80b-78b87e96663b';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіз ерекше қарқынмен өсуін жалғастырып жатыр! Жүктіліктің үшінші триместрінде Сіздің салмағыңыз аптасына орта есеппен шамамен 500 грамға артады. Қосылған салмақтың жартысына жуығы бөпеңіздің денесінде май тіні түрінде жиналады. Бөпеңіздің май жасушаларын осындай жоғары қарқынмен түзуінің басты себебі — туғаннан кейін дене температурасын сақтап, қажет болғанда оны энергия көзі ретінде пайдалану. Бұл кезеңде бөпеңіздің денесінде қоңыр да, ақ та май жасушалары болады. Қоңыр май жасушалары медицинада феталдық май тіні деп аталады. Оның бөпелерде ересектерге қарағанда көбірек болуы дене жылуын тиімді сақтауға көмектеседі. Қоңыр май жасушалары бұл қызметті құрамындағы көптеген митохондрия органоидтарының сыртқы мембранасында орналасқан термогенин ақуызының арқасында атқарады. Термогенин ақуызы қан тамырлары арқылы жасушаларға жеткізілетін оттегіні пайдаланып, жылудың тиімді түзілуін қамтамасыз етеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Басымды төмен қаратып жатырмын! ⬇️ Тартылыс күші мен түйсігім мені басымды төмен қаратып орналасуға жетелейді. Басым — денемнің ең ауыр бөлігі, сондықтан оның төмен түсуі ыңғайлы. Бұл — босануға ең қолайлы қалып. Егер әлі бұрылмаған болсам, уайымдамаңыз, кейбір достарым соңғы сәтке дейін күтеді.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Ананас'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің үшінші триместрінде ентігу айқын сезілуі мүмкін. Жүктілік кезінде қандағы мөлшері едәуір артатын прогестерон гормоны мидағы тыныс алу орталығын белсендіреді, соның салдарынан Сіз жиірек әрі тереңірек тыныс аласыз. Тыныс алу жүйеңіз қан арқылы плацентаға көп мөлшерде оттегі жеткізіп, көмірқышқыл газын әдеттегіден көбірек шығару үшін ауаны көбірек қажет етеді. Осы себептердің барлығына байланысты өкпеңіз әр тыныс алған сайын 30-40% көбірек ауа жұтып, шығарады. Бұл өзгерістер тыныс алудың қиындауына және ауа жетіспеу сезіміне әкелуі мүмкін. Сол жақ қырыңызбен жату, ауыр жұмыстан аулақ болу, тік отыру және дұрыс тыныс алу бұл мәселені жеңілдетіп, өзіңізді жайлы сезінуге көмектеседі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Кегель жаттығуларын жалғастырыңыз. Жамбас түбі бұлшықеттерін нығайту бөпенің басы төмендеген сайын пайда болатын қысымды жеңілдетуге және зәр ұстай алмаудың алдын алуға көмектеседі.') WHERE id = '7324ee36-63a7-4db4-bc5e-2444adb29718';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы аптада бөпеңіз босануға қажетті қалыпқа орналасқан болуы мүмкін. Әдетте бөпелер 32-аптадан кейін босануға қажетті қалыпқа келе бастайды. Бұл орташа мерзім болғанымен, мұндай өзгеріс 4 апта бұрын немесе тіпті босану кезінде де болуы мүмкін. Босану қалпында бөпеңіздің басы төменде, бөксесі диафрагмаңыздың астында орналасады, аяқтары ішіне қарай бүгіліп, қолдары кеудесіне айқастырыла қойылады. Бөпеңіздің мұндай қалыпты босану қалпы цефаликалық немесе баспен төмен жату қалпы деп аталады. >:P Босану физиологиялық жолмен өтуі үшін бас жамбас сүйектерінің ішінде белгілі бір қалыпта орналасуы керек. Босану қалпында бөпенің бірінші келетін бөлігі — басының артқы жағындағы шүйде тұсы. Соның арқасында бөпенің басы сүйекті босану жолына ең кіші диаметрімен кіреді.'), baby_message_kk = COALESCE(baby_message_kk, 'Сіздің иммундық қорғанысыңызды қабылдап жатырмын! 🛡️ Anacan, плацента арқылы Сізден маған "антиденелер" (микробтармен күресетін сарбаздар) өтеді. Бұл — менің алғашқы екпем. Туған кезде менің өз иммунитетім әлсіз болады, бірақ Сіз берген осы қорғаныс мені алғашқы айларда аурулардан қорғайды. Сіз — менің қорғаушы періштемсіз!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Ананас'), body_changes_kk = COALESCE(body_changes_kk, 'Ас қорытудың бұзылуы мен іш қату әлі де мазалауы мүмкін. Прогестерон гормонының әсерінен және жатырдың ішекке түсіретін қысымынан ас қорыту жүйесі баяу жұмыс істейді. Суды мол ішу және талшыққа бай тағамдар жеу маңызды.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қыжылды азайту үшін аз мөлшерде, бірақ жиі тамақтаныңыз. Ұйықтағанда сол жақ қырыңызбен жату тыныс алуыңызды жеңілдетіп қана қоймай, бөпеге баратын қан айналымын да жақсартады. Егер әлі бастамаған болсаңыз, перзентхана сөмкесіне не салатыныңызды жоспарлай бастаңыз. Демалуды және өзіңізді қатты шаршатпауды ұмытпаңыз!') WHERE id = '2bbb9ba5-0677-4713-8d4c-c7c237ab84f6';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бұл кезеңде бөпеңіздің бойы 40-48 см аралығында болуы мүмкін. Бойдың өсуі негізінен сүйектердің ұзаруы арқылы жүреді. Сүйектердің ұзаруы — бөпенің ана құрсағындағы эмбриондық кезеңінің соңында басталып, туғаннан кейін жасөспірімдік кезең аяқталғанға дейін жалғасатын үдеріс. Ұзару қарқыны әр кезеңде артып немесе баяулауы мүмкін. Ұл және қыз балалардың өсу кезеңдері бір-бірінен ерекшеленеді. 2 жасқа дейін ұл балалардың бойы қыздарға қарағанда жылдамырақ өседі. Ал қыздар 2 жастан бастап балалық шақ бойы және жасөспірімдік кезеңге дейінгі уақытта бұл өсу кезеңінен ұлдарға қарағанда ертерек өтеді. Бұл айырмашылық 11-13 жас аралығында айқын байқалады және әдетте қыздардың ұлдардан бойшаңырақ болатыны көрінеді. Орта есеппен 15-16 жаста бұл айырмашылық жойылып, жасөспірімдік кезең аяқталғанда ұлдардың бойы қыздарға қарағанда биігірек болады. Бойдың өсуіне әсер ететін ең маңызды фактор — генетика. Осы кезеңде бөпеңіздің ересек жастағы бойы шамамен анықталып қойған.'), baby_message_kk = COALESCE(baby_message_kk, 'Сүйектерім қатайып келеді, бірақ... 🦴 Денемдегі сүйектер қатайып жатыр, алайда бассүйегімнің сүйектері әлі бірігіп кеткен жоқ және жұмсақ. Неліктен? Өйткені туған кезде тар жолдан өтуім үшін басым аздап қысылып, пішінін өзгертуі керек. Бұл — табиғаттың ғажайып жоспары. Туғаннан кейін басымның пішіні қайта қалпына келеді.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Ананас'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік бойы бөпеңізге қоректік заттар мен оттегіні жеткізетін плацента ультрадыбыстық зерттеу кезінде ашық әрі ақ болып көрінсе, бұл оның кальцийлене бастағанын білдіреді.;;;
Плацентаның қартаюы жүктіліктің кез келген кезеңінде болуы мүмкін, бірақ соңғы триместрде жиірек кездеседі. Алкоголь мен темекі шегу сияқты зиянды әдеттер плацентаның қартаюын жеделдететін факторларға жатады. Жүктіліктің соңғы айларындағы плацентаның қартаюы әдетте қауіпті емес, бірақ оны жүйелі түрде бақылап отыру қажет. Сонымен қатар, егер Сізде қан қысымы жоғары болса, кальцийленудің бөпеге ықтимал әсерін бақылау үшін дәрігердің қадағалауында болған жөн.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Пробиотиктерге бай тағамдар (табиғи йогурт, айран) ас қорыту жүйесінің жұмысын реттеуге көмектеседі. Іш қатқанда таңертең бір қасық зәйтүн майын ішу немесе қара өрік кептірмесін жеу пайдалы болуы мүмкін.') WHERE id = 'ffcf32a2-fefd-4897-8f4a-507b427193a8';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің плацентасы мен денесінің арасында қоректік заттар мен оттегін тасымалдайтын кіндік бауы 2 артериядан және 1 венадан тұрады. Медицина тілінде умбиликалдық бау деп аталатын кіндік бауы — бөпеңіздің физиологиялық және генетикалық тұрғыдан бір бөлігі; ол таза қан мен қалдық заттары бар қанды араластырмай тасымалдауды қамтамасыз етеді. Кіндік бауының ұзындығы шамамен 50 sm, ал диаметрі 2 sm болады. Бұл құрылымдағы артериялар мен веналар әдеттегіден керісінше қызмет атқарады. Қалыпты жағдайда оттегіне бай қан артериялармен, ал оттегі аз әрі қалдық заттары бар қан веналармен тасымалданады; ал кіндік бауындағы артериялар қалдық заттары бар қанды, веналар оттегі мен қоректік заттарға бай қанды тасымалдайды. Оның құрамында жүйке талшықтары болмағандықтан, босанғаннан кейін кіндік бауын кесу бөпеңізге ешқандай ауырсыну тудырмайды. Алайда кейбір жағдайларда кіндік бауы бір артерия мен бір венадан, яғни барлығы екі тамырдан тұруы мүмкін. Мұндай кезде бөпенің дамуы тексеріліп, мұқият бақылау қажет болуы ықтимал.'), baby_message_kk = COALESCE(baby_message_kk, 'Сүйектерім тастай берік! 🦴 Қаңқам толығымен қатайды. Қолдарым мен аяқтарым енді резеңкедей емес, мықты. Мен тепкенде, оны бұрынғыдан да ауыр сезетін шығарсың. Кальций қабылдауды жалғастыр, өйткені мен әлі де сенің қорыңды пайдаланып жатырмын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Ананас'), body_changes_kk = COALESCE(body_changes_kk, 'Релаксин — жүктілік басталғаннан кейін ағзаңызда мөлшері арта бастайтын, ақуыздан тұратын гормон.;;;
Химиялық құрылымы жағынан релаксин инсулинге өте ұқсас. Ол плацента мен аналық бездерден бөлініп, жүктілік кезінде аса маңызды қызметтер атқарады.;;;
Релаксин гормоны жамбас сүйектерін ұстап тұратын байламдардың босаңсуына және жұмсаруына көмектеседі. Сонымен қатар босану жақындайтын үшінші триместрден бастап жатырды қоршап тұрған байламдардың босаңсуын қамтамасыз етеді.;;;
Жүктілікке дейінгі кезеңмен салыстырғанда оның ағзадағы мөлшері шамамен 10 есе артады. Бөпеңіз жатыр қабырғасына бекіген алғашқы күндерден-ақ қандағы деңгейі едәуір жоғарылайтын бұл гормон жаңа қан тамырларының түзілуіне көмектесіп, ұрықтанған жұмыртқа жасушасы үшін ең қолайлы ортаның қалыптасуына жағдай жасайды.;;;
Сонымен қатар релаксин гормоны жамбас, тобық, тізе және иық сияқты дененің әртүрлі бөліктеріндегі байламдардың босаңсуына әкеледі. Соның салдарынан бұл аймақтарда сезімталдықтың жоғарылауы немесе ауырсыну жиі пайда болуы мүмкін.;;;
Жүктіліктің соңғы апталарында релаксин гормоны жамбас және шат сүйектерінен құралған жамбас белдеуін босаңсытып, босану кезінде бөпеңіздің оңай өтуіне мүмкіндік береді.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қолыңыздағы ауырсынуды азайту үшін қолдарыңызды жиі сілкіңіз. Түнде ұйықтағанда білектеріңіздің бүгіліп қалмауын қадағалаңыз немесе арнайы білезік-ортездерді қолданыңыз.') WHERE id = '17265dbc-d27e-4949-9a83-25783c4be9dd';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің жіңішке ішегіндегі қозғалысты қамтамасыз ететін бірыңғай салалы бұлшықеттер дамуын жалғастыруда. Бұл даму үдерісі шамамен 37-аптаға дейін созылады. Жіңішке ішек — асқазаннан келетін, жартылай қорытылған тағамнан тұратын химус құрамындағы ақуыздар, майлар мен көмірсулардың құрылымдық бөліктерге ыдырайтын орны. Ас қорыту бауырда өндіріліп, өт қабында жиналатын өт сұйықтығының, сондай-ақ ұйқы безінде өндіріліп, тікелей осы жерге бөлінетін ұйқы безі сөлінің көмегімен жүзеге асады.;;;
Сонымен қатар құрылымдық бөліктерге ыдыраған қоректік заттардың сіңуі де жіңішке ішекте жүреді. Бұл сіңуді жіңішке ішектің ішкі қабатындағы бүрлер жүзеге асырады. Осы кезеңде жіңішке ішектің әрбір миллиметрінде шамамен 40 бүр болады. Жіңішке ішектің бастапқы бөліктерінде қорытылған қоректік заттар кейін оның ортаңғы бөліктеріндегі бүрлер арқылы сіңіп, қан мен лимфа сұйықтығына өтеді. Қоректік заттарды қорыту және сіңіру үшін алға жылжыту үдерісі ішектің ортаңғы қабатындағы бірыңғай салалы бұлшықеттердің көмегімен жүзеге асады. Ұзынша және сақина тәрізді бұл бұлшықеттер жіңішке ішектің перистальтикалық қозғалыстарын қалыптастырады. Перистальтикалық қозғалыстардың арқасында қоректік заттар төмен қарай жылжиды.'), baby_message_kk = COALESCE(baby_message_kk, 'Қағанақ суым ең жоғары деңгейге жетті! 💧 Қазір менің бассейнімдегі су ең көп кезеңде (шамамен 1 litr). Бұдан кейін су мөлшері тұрақты болып қалады немесе босануға жақындағанда аздап азаяды, өйткені мен өсіп, барлық орынды алып қоямын. Әзірге маған жайлы, бірақ қабырғалар жақындап келеді!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Ананас'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің үшінші триместрі басталғанда қыжылға қатысты шағымдарыңыз едәуір күшеюі мүмкін. Қыжыл тәуліктің кез келген уақытында пайда болуы ықтимал, бірақ көбіне кешкі уақытта, тамақтан кейін жиірек байқалады. Қыжыл деп аталатын рефлюкс — асқазандағы қышқылдың өңешке кері өтуінен туындаған тітіркенудің кеуде тұсында күйдіру сезімін тудыруы. Жүктілік кезіндегі қыжылдың негізгі себептері гормондық және физикалық өзгерістерге байланысты.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ентіккен кезде тамақты өте аз мөлшермен ішіңіз. Асқазан толғанда көкетті қаттырақ қысады. Арқаңызды тік ұстап отыру өкпеге біраз орын босатады.') WHERE id = '41437aba-e2e0-4e6a-ba9f-969bd7411f70';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің тоқ ішегінде ас қорытуға көмектесетін пайдалы бактериялар жиналған, олардың саны дене жасушаларының санына жуық.;;;
Тоқ ішек — ас қорыту жүйесінің соңғы бөлігі. Ол қорытылып, сіңірілген тағам қалдықтарын су мен дәрумендерден бөліп, нәжіске айналдырады. Тоқ ішектің ең маңызды қызметтерінің бірі — дәрумендерді сіңіру. Бұл сіңу тоқ ішекте тіршілік ететін бактериялардың көмегімен жүреді. Тоқ ішекте бактериялардың 700-ден астам түрі бар, ал олардың жалпы саны миллионнан асады.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің өлшемім ананастай! Мен енді үлкен бөпемін. Беттерім томпайып, денем жұмырланды. Сенімен кездесуге аз ғана уақыт қалды, Anacan. Мен күн сайын көбірек салмақ қосып келемін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Ананас'), body_changes_kk = COALESCE(body_changes_kk, 'Несеп жолдарының инфекциялары — жүктіліктің соңғы апталарында жиі кездесетін денсаулық мәселелерінің бірі. Несеп жолдарының инфекциясынан қорғанудың ең тиімді жолдарының бірі — күніне кемінде 2,5 litr су ішу. Әсіресе қапталған, қант қосылған сусындардан бас тартқан жөн. Мұндай өнімдер несеп жолдарындағы ықтимал бактерияларды қоректендіріп, олардың жылдам көбеюіне жағдай жасайды. Сонымен қатар несепті мүмкіндігінше ұстамай, дәретханаға жиі баруға, қуықтың толық босауына көңіл бөлуіңіз және дәретханадан кейін жыныс мүшелері аймағының тазалығын барынша сақтауыңыз керек.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Кальций тапшылығының орнын толтыру үшін сүт, айран немесе ірімшікті көбірек тұтыныңыз. Қыжылды азайту үшін тамақтан кейін бірден жатпаңыз және кешкі асты ұйықтардан кемінде 3 сағат бұрын аяқтаңыз. Аяқтың ісінуі мен варикоздың алдын алу үшін ұзақ уақыт тік тұрмаңыз және отырғанда аяғыңызды айқастырмаңыз. Бүгін босануға арналған сөмкеңізді тағы бір қарап шығыңыз, бірдеңені ұмытып кетпедіңіз бе?') WHERE id = '97daa5bb-e709-4882-8a96-d104cbbdafc3';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің барлық қажеттілігін қамтамасыз ететін байланыстырушы құрылым — кіндік бауы жүктіліктің осы кезеңінде кейбір мәселелерге себеп болуы мүмкін. Жүктілік кезінде кіндік бауының оралуы және кіндік бауында екі тамырдың болуы — солардың кейбірі. Плацента мен бөпеңіздің кіндігін байланыстыратын бұл құрылымның оның мойнына оралуы қауіп төндіруі мүмкін.;;;
Кіндік бауы бөпеңіздің мойнына оралып қана қоймай, өздігінен түйіліп те қалуы мүмкін. Кейбір түйіндер босану кезінде, ал кейбірі жүктілік барысында бөпеңіздің қозғалысынан пайда болады. Түйін бос болса, бөпеңізге еш қауіп төндірмейді. Алайда түйін қатты тартылса, плацентадан бөпеңізге баратын қан ағымы бұзылып, оттегі тапшылығына әкелуі мүмкін. Кіндік бауы оралуының ең жиі кездесетін белгісі — соңғы апталарда бөпе қимылының азаюы. Егер түйілу босану кезінде орын алса, NST құрылғысы бөпеңіздің жүрек соғуындағы ауытқуды көрсетуі мүмкін. Кіндік бауының бос оралуы амнион сұйықтығы көп болғанда жиірек кездеседі, өйткені мұндай жағдайда бөпе еркінірек қозғалады. Шамамен әрбір 2000 босанудың 1-інде кіндік бауында бөпеге қауіп төндіретіндей қатты түйін пайда болады.'), baby_message_kk = COALESCE(baby_message_kk, 'Суым азайып, өзім өсіп келемін! 💧 Бұрын менің бассейнім өте кең еді, ал қазір мен сонша көп орын алып жатырмын, сондықтан амнион сұйықтығының мөлшері салыстырмалы түрде аз көрінеді. Енді сен менің қимылдарымды анығырақ әрі қаттырақ сезесің. Шынтағымды саған қарай тірегенде, ішіңнің пішіні өзгеріп кетуі мүмкін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Ананас'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілігіңіздің соңына жақындаған осы апталарда қалай босанғыңыз келетінін ойластыра бастағаныңыз жөн. Суда босану — соңғы жылдары босану түрлерінің ішінде ең көп зерттеліп жүрген тақырыптардың бірі. Бұл әдіс босануға арнайы дайындалған бассейнде немесе ваннада, судың ішінде жүзеге асырылады. Оның мақсаты — босану кезінде толғақты жеңілірек өткізу үшін судың босаңсытатын әсерін пайдалану. Босану кезінде жылы суда болу денені босаңсытып, окситоцин гормонының бөлінуін арттырады. Бөлінген окситоцин толғақты бірқалыпты етіп, босану уақытын қысқартады. Жылы су бұлшықеттер мен тіндерді жұмсартып, ауырсыну мен ширығу сезімін де азайтады. Әсіресе іш пен шап аймағындағы бұлшықеттер босаңсыған кезде толғақты әлдеқайда жеңіл өткізуге болады. Соның арқасында босануды сабырлы әрі жағымды көңіл күймен аяқтай аласыз.;;;
Сонымен қатар жүктілік бойы амнион сұйықтығында дамыған бөпеңіз жылы суға дүниеге келгенде сыртқы ортаға біртіндеп бейімделеді, сондықтан босану кезіндегі күйзелісті барынша аз сезінеді.;;;
Егер суда босанғыңыз келсе, перзентханаңызда оған қажетті жағдай бар-жоғын алдын ала анықтаңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ішіңізге ылғалдандыратын май жағуды жалғастырыңыз. Қасудан аулақ болыңыз. Бөліндінің түсі немесе иісі өзгерсе (жасыл түсті, жағымсыз иісті болса), дәрігерге қаралыңыз. Күнделікті төсемелерді пайдалану жайлылық береді.') WHERE id = '1071fbaa-eb8a-400f-b713-0a3f36f51bd7';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Қабақтары ашыла бастағандықтан, бөпеңіз ояу кезінде көзін жиі ашатын болды. Тіпті нұрлы қабықтың көмегімен оның қарашықтары жарық түскенде тарылып, қараңғыда кеңейе бастады.;;;
Қарашық — көздің түрлі түсті бөлігі, яғни нұрлы қабықтың ортасында орналасқан саңылау. Осы құрылым арқылы жарық торлы қабыққа түседі. Қарашықтан өткен жарық сәулелері көз ішіндегі тіндерге сіңіп, кері шықпайтындықтан, ол қара түсті болып көрінеді. Қарашықты қоршап тұрған көздің түрлі түсті бөлігі — негізінен бірыңғай салалы бұлшықеттерден тұратын, жиырыла алатын құрылым. Жарық көзге қарашық арқылы енеді, ал оның көлемін басқаратын нұрлы қабық көзге түсетін жарық мөлшерін реттейді. Қарашықтың кеңеюі мен тарылуын нұрлы қабықтағы екі түрлі бірыңғай салалы бұлшықет қамтамасыз етеді. Жарық көп болғанда олардың бірі жиырылып, қарашықты тарылтады да, көзді қарқынды жарықтың кері әсерінен қорғайды. Ал қараңғыда екінші бұлшықет жиырылып, нұрлы қабықты шетке қарай тартады. Соның нәтижесінде қарашық кеңейіп, көзге көбірек жарық түседі және қараңғыда көруге мүмкіндік туады.'), baby_message_kk = COALESCE(baby_message_kk, 'Терім енді мөлдір емес! 👶 Менің терім қалыңдап, қызғылт түске енді, енді ішкі ағзаларым көрінбейді. Май қабаты мені "томпақ" етіп келеді. Мен нағыз жаңа туған бөпеге ұқсаймын. Мені 3D ультрадыбыстық зерттеуден көрсең, бетімнен шымшып алғың келеді!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Ананас'), body_changes_kk = COALESCE(body_changes_kk, 'Егер бұл екінші жүктілігіңіз болса және алғашқы босануыңыз кесарь тілігі арқылы өтсе, кесарь тілігінен кейін қынаптық жолмен босану (КТКҚБ) мүмкіндігін қарастыра аласыз. КТКҚБ — бұған дейін кесарь тілігі жасалғаннан кейін табиғи жолмен босану дегенді білдіреді. Бұрын кесарь тілігі арқылы босанған әйелдерге келесі жүктілігін табиғи босанумен аяқтау ұсынылмайтын.;;;
Алайда соңғы зерттеулер кесарь тілігі арқылы босанған әйелдің екінші рет табиғи жолмен босану ықтималдығы 75%-дан жоғары екенін көрсетті.;;;
Егер кесарь тілігі жасалғанына кемінде 1 жыл өтсе, бұрын жатырдың жыртылуы болмаған және жатырға қандай да бір операция жасалмаған болса, сондай-ақ жүктілік кезінде табиғи босануға кедергі келтіретін мәселе болмаса, КТКҚБ әдісін қарастыра аласыз. Сонымен қатар табиғи босанудың кесарь тілігімен салыстырғанда артықшылықтары көбірек. Табиғи жолмен босанған әйелдердің босанғаннан кейінгі қалпына келу кезеңі қысқарады, инфекция қаупі төмендейді және қан жоғалту барынша аз болады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Өзіңізге уақыт бөліңіз. Бұл — босануға дейін өзіңізбен оңаша қала алатын соңғы апталар. Кітап оқыңыз, фильм көріңіз, достарыңызбен кездесіңіз. Осы тыныш күндердің қадірін біліңіз.') WHERE id = '79fb5c0f-3cea-4126-92e7-e885b95bc603';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің бойы мен салмағын айқындайтын гендер жыныс жасушаларыңыздағы хромосомалар арқылы беріледі. Әсіресе бойдың өсуін анықтайтын факторлардың 80%-ы генетикалық кодтарға байланысты. Мұндай генетикалық кодтардың саны 600-700 аралығында болуы мүмкін. Қысқаша айтқанда, анасы мен әкесінің бойы аласа әрі дене бітімі арық болса, басқа факторлардың әсерінсіз бөпенің бойшаң болуы немесе салмақ қосуға бейім келуі екіталай. Тамақтану әдеттері де салмақ қосуға, сүйектердің ұзаруы мен жуандауына тікелей әсер етеді. Сүйектің осылай дамуы бойдың өсуін қамтамасыз етеді. Бой мен салмақ арақатынасына тұқым қуалайтын факторлармен қатар әртүрлі аурулар, дамуға кедергі келтіретін генетикалық бұзылыстар, қоректік заттардың тапшылығы мен дұрыс тамақтанбау, ұйқы тәртібі және дене белсенділігі де әсер етеді. Бойдың өсуі мен салмақ қосуға климат та ықпал етеді. Әсіресе тропиктік климатта тұратын адамдардың бойы көбіне аласалау әрі дене бітімі ірірек болса, Скандинавия елдері орналасқан Солтүстік Еуропа тұрғындарының бойы биігірек, дене бітімі арықтау келеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Сенің иммунитетіңді алып жатырмын! 🛡️ Anacan, менің қазір не істеп жатқанымды білесің бе? Сенің қаныңнан өзіме "иммунитет сарбаздарын" (антиденелерді) жинап жатырмын. Өмір бойы қандай ауруларға қарсы иммунитет қалыптастырсаң, сол қорғанысты маған бересің. Дүниеге келгенімде мені микробтардан қорғайтын алғашқы қалқаным — сенсің.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Ананас'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде бөпеңіздің сүйектері дамитындықтан, D дәруменіне қажеттілігіңіз шамамен 5 есе артады. Әсіресе бөпенің сүйектері қарқынды дамитын екінші триместрде ағзаңыздан бөпеге өтетін кальций мөлшері өте жоғары болады. Сондықтан ағзаңыз D дәруменіне деген жоғары қажеттілікті өтеу үшін оның ішекте сіңуін арттырады. Сонымен бірге сүйектеріңіздегі кальций қанға өтеді. Бұл жүктілік кезінде сүйектеріңіздің осалдануына себеп болуы мүмкін.;;;
Жүктілік бойы әйелдер сүйек массасының шамамен 5%-ын жоғалтады. Ағзадағы D дәруменінің азаюы гестациялық диабет, преэклампсия деп аталатын жүктілік асқынуы және инфекция жұқтыру қаупін арттыруы мүмкін. Сондықтан дәрігердің ұсынымымен D дәруменін қабылдау өте маңызды. Қоспалармен қатар күн сайын 15-20 минут күн сәулесінде болу да пайдалы.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Суды молынан ішуді жалғастырыңыз. Бұл дене қызуын реттеу және сусызданудың алдын алу үшін маңызды. Сусыздану мерзімінен бұрын толғақтың басталуына себеп болуы мүмкін.') WHERE id = 'adc2549c-64e5-4fcb-ab22-00fd00f59fac';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің қаңқа жүйесі осы кезеңде негізінен шеміршек тінінен тұрады. Бөпеңіз дүниеге келгеннен кейін өскен сайын, қаңқа жүйесінің көп бөлігін құрайтын шеміршек тіні біртіндеп сүйек тініне айналады. Сүйекке қаттылық беретін кальций тұздарының сүйек тінінде жиналуы жасөспірімдік кезеңнің соңына дейін жалғасады. Сүйектену аяқталғаннан кейін шеміршек тіні қабырғалардың ұштарында, буын беттерінде, кеңірдекте, көмейде, құлақ қалқанында және мұрын ұшында сақталады. Сондай-ақ ол сүйектердің серпімді болуына және қаңқа жүйесінің қозғалуына көмектеседі.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің басым әлі де жұмсақ! 🧠 Денемдегі сүйектер қатты болғанымен, бас сүйектерім бір-бірінің үстіне ығыса алатындай қозғалмалы. Неліктен? Өйткені дүниеге келгенде сол тар жолдан өту үшін басым сәл кішіреюі керек. Табиғат маған "серпімді дулыға" сыйлаған.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қауын'), body_changes_kk = COALESCE(body_changes_kk, 'Ұйқысыздыққа қатысты шағымыңыз бүкіл өміріңіздегі ең жоғары деңгейге жеткен болуы мүмкін. Жүрек айну, қыжыл, асқазанның ашуы, үнемі дәретханаға бару қажеттілігі және өсіп келе жатқан ішіңізге байланысты жайлы орналаса алмау — осылардың әрқайсысы ұйқы сапасын нашарлатады. Түнде ұйықтар алдында қысқа уақыт душ қабылдау және 1 стақан жылы сүт ішу, әсіресе кешкі уақытта қорытылуы қиын ауыр әрі майлы тағамдардан бас тарту, шай мен кофе сияқты құрамында кофеин бар сусындарды ішпеу ұйқысыздықпен күресуге көмектеседі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Күні бойы аяқтарыңызды жиі жоғары көтеріп отырыңыз. Ыңғайлы, бір өлшемге үлкен аяқ киім немесе тәпішке киіңіз. Тұзды тағамдардан бас тартыңыз.') WHERE id = '75724f71-0d67-40e0-ac05-b52a8a77f3b7';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің зәр шығару жүйесі құрсақішілік кезеңде ең белсенді жұмыс істейтін жүйелердің бірі. Осы кезеңде бөпеңіздің бүйрегінің үстіңгі жағында одан майлы тінмен бөлінген бүйрекүсті безі орналасады. Сонымен қатар бүйректің бүйіріндегі ойыс аймаққа көптеген қан тамырлары, лимфа тамырлары, жүйкелер және несепағарлар жалғасады. Бөпеңіздің қуық қабырғасы толығымен бірыңғай салалы бұлшықеттерден тұратын қапшық тәрізді құрылымға ие. Бүйректе түзілген зәрдің қуыққа құйылатын жерлерінде оның кері ағуына жол бермейтін қақпақшалар бар. Қуық толған кезде оның керілген қабырғаларындағы жүйке ұштары миға белгі беріп, қуықтың жиырылуын қамтамасыз етеді. Соның арқасында бөпеңіз зәр шығару қажеттілігін сезінеді. Бөпеңіз зәрді несеп шығару өзегі арқылы сыртқа шығарады. Егер бөпеңіз ұл болса, несеп шығару өзегі ер адамның жыныс жүйесімен байланысты болады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен жарықты бақылап жүрмін! 🔦 Көздерім ашық, айналама қарап жатырмын. Қарашықтарым жарыққа жауап береді – жарық түскенде тарылады, қараңғыда кеңейеді. Менің көру жүйем жұмыс істеп тұр. Дүниеге келгенде Сіздің жүзіңізді шамамен 20-30 см қашықтықтан көре аламын (бұл — емізу кезіндегі арақашықтық!).'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қауын'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде асқазан мен ішекке байланысты жайсыздықтар әдеттегіден әлдеқайда қатты сезілуі мүмкін. Сондықтан жүктілік кезіндегі іштің кебуі мен газдан болатын түйілу жиі кездесетін мәселеге айналады. Жүктілік кезінде ішекте газ жиналуының себебі жүктілік гормондарына, әсіресе прогестерон гормонына байланысты. Прогестерон ас қорыту жүйесінің бірыңғай салалы бұлшықеттерін босаңсытады.;;;
Түймедақ шайы ішектегі газ мәселесін жеңілдетуге өте пайдалы. Газға байланысты шағымдарды күшейтетін ащы және дәмдеуіштері көп тағамдардан бас тарту қажет. Сонымен қатар тамақтану кезінде сұйықтық ішпеу іштің кебуін азайтып, газдан болатын түйілудің алдын алуға көмектеседі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ентігуді азайту үшін отырғанда арқаңызды міндетті түрде тік ұстаңыз. Аяқтарыңыздағы ісінуді азайту үшін көп су ішіп, күні бойы аяқтарыңызды жоғары көтеріп демалыңыз. Бұл кезеңде ұйқысыздық қалыпты, сондықтан күндізгі 15-20 минуттық қысқа ұйқы Сізге күш береді. Бүгін кешке өзіңізге біраз уақыт бөліп, жылы душ қабылдап, денеңізді босаңсытыңыз.') WHERE id = '0d05bbb2-bf77-46f6-81b3-38696a1de3f5';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ішектерінің сыртқы қабатындағы эпителий жасушаларынан тұратын шырышты қабықтың қалыптасуы аяқталған. Соның арқасында бөпеңіздің ішектері басқа ағзалармен үйкелу салдарынан зақымданбайды. Тоқ ішекте лимфоидты тіндер бар. Осы тіндер түзетін антиденелер ішекте тіршілік ететін пайдалы бактериялардың шамадан тыс көбеюіне жол бермейді және тағам арқылы ағзаға түскен зиянды микроағзаларды бейтараптандырады. Осылайша ықтимал инфекциялардың алдын алады. Ішектегі бактериялар бөпеңіздің ағзасы өздігінен өндіре алмайтын дәрумендерді синтездейді. Олардың ішіндегі ең маңыздылары — K дәрумені мен B тобының дәрумендері. Сондай-ақ тоқ ішекте судың сіңірілуі ағзаға қажетті судың нәжіспен сыртқа шығып кетпеуін және қанға қайта оралуын қамтамасыз етеді. Тағам құрамындағы көмірсулар, майлар, ақуыздар, дәрумендер, минералдар мен су молекулалары аш және тоқ ішекте сіңірілгеннен кейін қалған қалдықтар анус арқылы сыртқа шығарылғанға дейін тоқ ішекте сақталады. Сондықтан тоқ ішек қалдық заттар жиналатын қойма қызметін де атқарады.'), baby_message_kk = COALESCE(baby_message_kk, 'Маған орын тым тар! 🏠 Anacan, мен бұрылғым келеді, бірақ қабырғалар жан-жағымнан қысып тұр. Енді менің қимылдарым көбіне "сырғу" және "итеру" түрінде сезіледі. Шынтағымды ішіңіздің бір жағынан тірегенде, Сіз оны томпайған жер ретінде көресіз. Мені сипаңызшы, сонда мен кейін шегінемін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қауын'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілігіңіздің соңына жақындаған сайын жалған толғақтарыңыз әлдеқайда қарқынды бола түсуі мүмкін. Жатырдың жалған жиырылулары соңғы апталарда кейде қатты ауыртады. Брэкстон-Хикс деп аталатын бұл жалған толғақтар көбіне шынайы босану толғақтарымен шатастырылады. Әсіресе шаршағанда, ұзақ уақыт тік тұрып қалғанда немесе іш аймағына соққы тигенде олардың қарқындылығы артуы мүмкін. Сонымен қатар бірнеше рет босанған әйелдерде бұл толғақтар ертерек басталып, ұзағырақ созылады. Ал алғаш рет жүкті болған әйелдерде толғақтар кешірек басталып, олардың аралықтары тұрақсыздау болады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Аяқтарыңыздағы ісінуді азайту үшін көп су ішуді жалғастырыңыз және отырғанда аяқтарыңызды жоғары көтеріңіз. Қызыл иегіңіздің сезімталдығына байланысты жұмсақ тіс щеткасын пайдаланыңыз. Егер әлі жасамаған болсаңыз, бөпеге қажет алғашқы киімдерді жуып, үтіктеуді бастай аласыз. Бұл тыныштандыратын іс Сізді дайындап қана қоймай, бөпеңізбен арадағы байланысты да нығайтады.') WHERE id = 'd5a88302-fe21-4399-b36c-3480a294c860';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, '33-аптаның соңында жүктілігіңіздің мерзімі 7 ай 28 күн болады. Осы аптадан бастап бөпеңіз күніне кемінде 30 грамм салмақ қоса бастайды. Салмақтың бұлай артуы май жасушаларының жылдам түзілуіне байланысты. Соның арқасында тері астындағы май қабаты едәуір қалыңдап, бөпеңіз нағыз нәрестеге ұқсай бастады. Алдағы 2 апта ішінде май мөлшері босанған кездегі деңгейіне дерлік жетеді. Соның нәтижесінде терісі айтарлықтай тегістеледі. Бөпеңіздің тері астына жиналған бұл май жасушалары дене жылуын сақтауға көмектесіп қана қоймай, энергия қорын да қамтамасыз етеді. Жүктіліктің соңына жақындаған осы апталарда бөпеңіздің иммундық жүйесі де нығаяды. Бұл Сіздің ағзаңыз түзген антиденелердің плацента мен кіндік бауы арқылы бөпеңізге өтуінің арқасында жүзеге асады. Дамып келе жатқан иммундық жүйесінің арқасында бөпеңіз дүниеге келгенде сыртқы ортаға бейімделуге әлдеқайда дайын әрі төзімді болады.'), baby_message_kk = COALESCE(baby_message_kk, '🍈 Менің көлемім бір қауындай! Бұл апта — өте маңызды кезең. Егер мен қазір дүниеге келсем, өкпем жеткілікті дамығандықтан, өз бетімше тыныс алуым әбден мүмкін. Мен енді "кеш мерзімді шала туу" санатына жатамын. Қауіп айтарлықтай азайды!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қауын'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде қарқынды дамып келе жатқан бөпеңізге, әсіресе қаңқасы мен сүйектерінің нығаюы үшін, көп мөлшерде кальций қажет. Егер жүктілік бойы кальцийді жеткілікті мөлшерде қабылдамасаңыз, бөпеңіз өз қажеттілігін Сіздің қаңқа жүйеңіздегі кальций есебінен өтеп, ағзаңыздағы кальций қорының азаюына әкелуі мүмкін. Күнделікті тағамнан кальций жеткіліксіз түскенде, әсіресе кешкі уақытта ауырсыну мен түйілу сияқты мәселелер жиі байқалуы ықтимал. Сонымен қатар қаңқа жүйесі айтарлықтай зардап шегетіндіктен, остеопороз және басқа да сүйек мәселелерінің негізі қалануы мүмкін. Сондықтан бөпеңіздің дамуы мен өз денсаулығыңыз үшін тұтынатын тағамдарыңызға мән беріп, кальцийге деген күнделікті қажеттілігіңізді өтеп жүргеніңізге көз жеткізуіңіз керек. Ақ ірімшік, йогурт, сүт, қуырылмаған жаңғақтар, бұршақ тұқымдастар, табиғи тахини мен пекмез — кальцийге деген қажеттілікті өтеуге көмектесетін тағамдар. Бір кесе йогуртта 250 мг, бір тілім ақ ірімшікте 100 мг, бір уыс қуырылмаған жаңғақта 50 мг, 50 грамм пекмезде 200 мг және 50 грамм тахиниде 220 мг кальций бар.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Жүктіліктің 34 апталық жолын сәтті өткергеніңіз үшін бүгін өзіңізді қуантып, міндетті түрде демалыңыз. Беліңіздің ауырсынуын азайту үшін отырғанда арқаңызды тірейтін жастықтарды қолданыңыз. Егер әлі дайындамаған болсаңыз, кез келген сәтке дайын болу үшін перзентхана сөмкеңізді есіктің жанына қойыңыз. Ертеңнен бастап 35-аптаға — босануға апарар соңғы үлкен кезеңге қадам басамыз!') WHERE id = '5eeb8067-0b28-436d-9bac-19e1ef1b2e15';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы аптадан бастап бөпеңіздің ағзасындағы барлық жүйелер жұмыс істеп тұр. Оның мүшелері дүниеге келген кездегі көлеміне дерлік жетті. Сол мүшелердің бірі — бауырдың көлемі бөпеңіз салмағының %5-ін құрайды және орташа есеппен 100 грамм болады. Бауыр — бөпеңіздің ішкі мүшелерінің ішіндегі ең үлкені. Ересек адамда оның салмағы шамамен 2 килограмм болады. Асқазанның оң жағында орналасқан бауыр басқа жүйелерге жақын жатады. Бауыр асқазанның дәл оң жағында орналасады және бөпеңіз үшін өмірлік маңызды қызметтер атқарады. Энергия қажет болғанда, ол жинақталған гликогенді қантқа айналдыра алады. Онда A, D, E, K, B12 дәрумендері мен темір сақталады. Бауыр ақуыздар түзеді және оларды ағзаның қажеттілігіне қарай гормондар мен антиденелерге айналдыра алады. Ол түзетін өт сұйықтығы ағзаға түскен майларды май қышқылдары мен глицеринге айналдырып, жасушалардың пайдалануына дайындайды. Сондай-ақ бауыр ағзада жиналатын зиянды заттарды сүзгілеу қызметін атқарады. Ол алкоголь мен уытты заттарды қоса алғанда, ағзаға зиянды заттардың барлығын залалсыздандырып, олардың несеп арқылы сыртқа шығарылуын қамтамасыз етеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Верникс қабатым қалыңдап келеді! 🧀 Терімді жауып тұрған ақ, ірімшік тәрізді зат (Верникс) қазір ең қалың күйіне жетті. Ол мені қорғайды. Босанар уақыт жақындаған сайын бұл қабат біртіндеп азайып, қағанақ суына араласады. Осы сұйықтықты жұтқанда, мен ақуыз қабылдаймын. Мен ештеңені ысырап етпеймін!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қауын'), body_changes_kk = COALESCE(body_changes_kk, 'Ағзаңыз бөпеңізді оттегімен және қоректік заттармен қамтамасыз ету үшін қан көлемін жылдам арттырады. Бұл қан тамырларын кеңейтіп, қан қысымының төмендеуіне әкеледі. Жалпы алғанда, төмен қан қысымы аса көп қиындық тудырмайды. Алайда қан қысымын одан әрі төмендететін шамадан тыс шаршау, инфекциялар, ұзақ уақыт қимылсыз қалу, сұйықтықты аз ішу, жеткіліксіз тамақтану, қаназдық, қан кету және аллергия сияқты жағдайлардың салдарынан бас айналу, көздің қарауытуы, көрудің бұлыңғырлануы, тыныстың жиілеуі, жүрек айну және талып қалатындай сезім пайда болуы мүмкін. Егер қан қысымыңыз төмен болса, отырған немесе жатқан қалыптан күрт тұрудан сақтаныңыз, ұзақ уақыт тік тұрмаңыз, көпке дейін аш жүрмеңіз, өте ыстық әрі ұзақ ванна қабылдамаңыз, жеткілікті сұйықтық ішіп, қажетті дәрумендерді алу үшін дұрыс тамақтану тәртібін ұстаныңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Көру мәселесі айқын болмаса, алаңдамаңыз. Бірақ көзіңіздің алдында "шыбындар" ұшып жүргендей көрінсе, бұл қан қысымына байланысты белгі болуы мүмкін, дереу дәрігерге хабарлаңыз.') WHERE id = 'ee172976-4ef5-4259-a92a-16b538ea9e64';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің көптеген сүйектері мен буындары қалыптасып болғанымен, бас сүйегі әлі де жұмсақ. Бұл босану үдерісінің қалыпты өтуі үшін бас сүйек сүйектерінің қозғалмалы болуы тұрғысынан өте маңызды. Осы кезеңде бас сүйек сүйектері дәнекер тіннің арқасында ажырамай, бірге тұрады. Бұл тін бас сүйек сүйектеріне қозғалу мүмкіндігін де беретіндіктен, бөпеңіздің басы өте тар босану жолынан оңай өте алады.;;;
Бас сүйек сүйектері қосылмаған тұстарда халық арасында "еңбек" деп аталатын жұмсақ аймақтар бар. Бұл жұмсақ аймақтар астындағы дәнекер тіндердің көмегімен бөпеңіздің басына босану жолымен жылжуға қажетті икемділік береді. Бөпеңіз дүниеге келгеннен кейін миы өсіп, дамыған сайын бұл жұмсақ аймақтар жабылады. Бөпеңіз босану жолынан өткенде, басының өлшемін жолдың диаметріне бейімдеу үшін белгілі бір қимылдар жасауы керек. Сондай-ақ босану жолымен жылжу кезінде кездесетін кедергілерді еңсеру үшін қалпын өзгертеді. Осы қимылдар кезінде дәнекер тін жиырылып, бас сүйек сүйектері бір-біріне жақындайды, тіпті бірінің үстіне бірі ығысуы мүмкін.'), baby_message_kk = COALESCE(baby_message_kk, 'Басым төмен қарап тұр! ⬇️ Бәлкім, басым жамбас сүйектерінің арасына кіріп те қойған шығар. Бұл Сізге біраз жайсыздық тудыруы мүмкін (аяқтарыңыздың арасында доп тұрғандай), бірақ мен үшін бұл шығатын есікке жақындағанымды білдіреді. Мен бастапқы сызықтамын!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қауын'), body_changes_kk = COALESCE(body_changes_kk, 'Балық Омега-3 және Омега-6 май қышқылдарына бай болғандықтан, жүктілік кезінде оны міндетті түрде тамақтану рационына қосу керек. Балық жеу бөпеңіздің бүкіл денесінің дамуы, әсіресе жүйке жүйесі мен көзінің жетілуі үшін өте маңызды. Алайда құрамында сынап көп балықты жегенде, бұл уытты зат ағзаға оңай сіңіп, қан арқылы плацентаға өтеді. Албырт, анчоус, сардина, алабалық және скумбрия сияқты балықтарды тұтыну өте пайдалы. Ал семсербалық, тунец және акула етінде сынап мөлшері жоғары болады. Тунец құрамында сынап болғанымен, бөпеңіздің дамуы үшін маңызды тағам болғандықтан, оны жиі емес, анда-санда жеуге болады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Асықпай қозғалыңыз. Отырған жеріңізден тұрғанда қолыңызбен тіреніңіз. Жамбас бұлшықеттерін босаңсыту үшін гимнастикалық допқа отырып, айналмалы қимылдар жасау өте пайдалы.') WHERE id = '75621ce6-a937-4f79-9f2e-175be59eec6b';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің өкпесі әр секунд сайын тыныс алу қимылдарын жасап, дүниеге келетін күніне дайындалып жатыр. Бөпенің ана құрсағында жасайтын тыныс алу қимылдары қалыпты тыныс алудан өзгеше: ауа орнына су (амнион сұйықтығы) қолданылады. Оның ағзасы оттегіне деген қажеттілігін тыныс алу арқылы емес, плацента арқылы өтейді. Бұл тыныс алу қимылдары дем алып, дем шығаруға жаттығу қызметін атқарады. Осы жаттығудың арқасында өкпеде тыныс алу үшін аса маңызды сурфактант заты түзіледі. Плацентадан бөпеңізге оттегінің өтуі өте қарапайым жүйеге негізделген. Тыныс алуға қатысатын екі молекула — оттегі мен көмірқышқыл газы — қысым айырмашылығының арқасында плацента арқылы бөпеге беріледі. Бөпеңіздің ағзасы пайдаланған оттегі мен Сіздің қаныңыздағы жоғары мөлшердегі оттегі плацентада түйіскен кезде, Сіздің қаныңыздан плацентаға қарай қысым пайда болып, оттегі өтеді. Оттегі қысымы төменірек болғанына қарамастан, бөпеңіздің қаны тіндерге жеткілікті мөлшерде оттегі тасымалдай алады. Мұның себебі — бөпеңіздің қанындағы гемоглобин мөлшері шамамен %50 жоғары. Сонымен қатар қанайналым жүйесіндегі гемоглобиннің оттегін тасымалдау қабілеті тыныс алу арқылы алынатын оттегімен салыстырғанда әлдеқайда жоғары.'), baby_message_kk = COALESCE(baby_message_kk, 'Темір қорын жинап жатырмын! 🔩 Anacan, қазір мен Сіздің қаныңыздан темір алып жатырмын. Бауырымда темір қорын жинаудамын. Бұл қор маған дүниеге келгеннен кейінгі алғашқы 6 айда қан түзу үшін қажет болады. Мен Сіздің энергияңызды "ұрлап" жатқандықтан, өзіңізді әлсіз сезінуіңіз мүмкін. Кешіріңіз, бірақ бұл маған қажет!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қауын'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік басталғаннан кейін ішек флораңызда кейбір өзгерістер болады. Ішек флорасының өзгеруі нәтижесінде ағзаңыздағы май мөлшері артып, қандағы қант деңгейін реттейтін инсулин гормонына сезімталдық төмендейді. Зат алмасудағы бұл өзгерістер бөпеңіздің өсуіне көбірек энергия беріп қана қоймай, емізу кезінде ағзаңызға қажет болатын май қорын жинауға да көмектеседі. Алайда жүктілік кезінде жүктілік гормондарының көбеюіне байланысты ас қорыту жүйесіндегі бірыңғай салалы бұлшықеттер босаңсып, тұтынылған тағамның ішек арқылы баяу жылжуына әкеледі. Соның салдарынан ас қорытудың қиындауы, газ жиналуы және іш қатуы мүмкін. Іш қатудың алдын алу үшін сұйықтықты мол ішіп, көбірек қимылдауыңыз керек. Көкөністер, жемістер, бұршақ тұқымдастар мен дәнді дақылдар сияқты жасұныққа бай өнімдерден тұратын тамақтану жоспарын құрыңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Жамбас ауыруын азайту үшін отырғанда аяғыңызды айқастырмаңыз және төсекте бір қырыңыздан екінші қырыңызға өте баяу бұрылыңыз. Қыжылдың алдын алу үшін ұйықтар алдында ауыр тағамдардан бас тартыңыз. Осы аптада "сөмкеңіздің тізімін" соңғы рет тексеріңіз: өзіңізге ыңғайлы халат, бөпеге арналған алғашқы киім жиынтығы мен жөргектердің дайын екеніне көз жеткізіңіз. Бүгін өзіңізге біраз уақыт бөліп, баяу музыка тыңдаңыз.') WHERE id = 'b978e435-783d-4177-aada-9e6cd05f0950';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ағзасында май түзілуі өте қарқынды жалғасып жатыр. Сонымен қатар денесін жауып тұрған лануго түктерінің басым бөлігі түсіп қалған. Лануго — жүктіліктің алғашқы триместрінен бастап бөпенің бүкіл денесінде өсе бастайтын жіңішке түктер. 20-аптаға қарай бұл түктер айтарлықтай қоюланып, көбейеді. Олар денесінде әлі май қабаты қалыптаспаған бөпеңіздің дене температурасын тұрақты ұстау үшін өседі. Соңғы триместрде май түзіле бастаған кезде біртіндеп түсе бастайды. Жүктіліктің қазіргі соңғы апталарында май қабаты өте жылдам қалыптасады. Сондықтан бұл түктердің түсуі едәуір жылдамдап, тері бетінен түскен лануго түктері амнион сұйықтығына араласады. Амнион сұйықтығындағы түктер бөпеңіздің тыныс алу қимылдары кезінде ағзасына түседі. Бөпеңіз тыныс алу қимылдарының нәтижесінде жұтқан лануго түктері ішекте шырышты қабатпен (мукозамен) қосылып, тері қалдықтары және басқа да қалдық заттармен бірге меконий түзеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Бүйректерім бар күшімен жұмыс істеп жатыр! 💧 Менің бүйректерім толық дамып болды, ал бауырым кейбір қалдықтарды өңдей алады. Егер мен бүгін дүниеге келсем, ағзамның тазарту жүйесі жұмыс істейді. Мен күн сайын бұрынғыдан да "тәуелсіз" болып келемін. Сіз менімен мақтана аласыз.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қауын'), body_changes_kk = COALESCE(body_changes_kk, 'Кейде өзіңізді өте әлсіз, қалжыраған және шаршаған күйде сезінуіңіз мүмкін. Жүктілік кезіндегі гормондық өзгерістерге, бөпеңіздің едәуір өсуіне және қосқан салмағыңызға байланысты жүктілікке дейінгі кезеңмен салыстырғанда көбірек шаршау мен әлсіздік сезінуіңіз қалыпты жағдай. Мұндай шаршау әдетте демалып, сапалы ұйықтағаннан кейін азаяды. Алайда демалғаннан кейін де басылмайтын, оянған кезде сезілетін және ұзақ уақытқа созылатын шаршау созылмалы шаршау синдромының белгісі болуы мүмкін. Созылмалы шаршау синдромы — демалғаннан кейін басылмайтын әрі ұзаққа созылатын шаршаумен қатар, есте сақтау мен зейін қоюдың қиындауы, қарқындылығы әртүрлі бас ауыруы, ұйықтай алмау және тамақтың қайталама ауыруы сияқты бірнеше белгімен қатар жүретін жағдай. Құнарсыз тамақтану — созылмалы шаршаудың негізгі себептерінің бірі. Өзіңізге және бөпеңізге қажетті дәрумендер мен минералдарды тағамнан жеткілікті мөлшерде ала алмасаңыз, міндетті түрде дәрігер ұсынған қоспаларды қабылдауыңыз керек.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ұйқысыздықпен күресу үшін күндіз қатты шаршамауға тырысыңыз және ұйықтар алдында жылы душ қабылдаңыз. Беліңіз ауырса, міндетті түрде жүктілікке арналған жастықты қолданып, сол қырыңызбен жатыңыз. Аяқтарыңыздағы ісінуді азайту үшін суды мол ішіңіз және күніне кемінде 3-4 рет аяғыңызды жүрек деңгейінен жоғары көтеріп, 15 минут демалыңыз. Бүгін өзіңізді қатты шаршатпаңыз, күшіңізді маңызды күнге сақтаңыз.') WHERE id = '35db243b-b555-441f-ace2-1f8b3ddb076b';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бұл кезеңде бөпеңіздің дене салмағының әр килограмына шаққандағы қан көлемі 80 миллилитрді құрайды, ал ағзасында орта есеппен 250 грамм қан бар. Қан жасушалары ағзадағы сүйек кемігінде түзіледі. Сүйек кемігі — кейбір сүйектердің ішінде орналасқан кеуек тәрізді құрылым. Сүйек кемігінде арнайы бағаналы жасушалар болады. Бұл жасушалар әртүрлі факторлардың әсерімен бөпеңіздің ағзасындағы қажеттілікке сәйкес эритроциттерді, лейкоциттерді және қан пластинкалары деп аталатын тромбоциттерді түзеді. Бөпеңіздің қанайналым жүйесіндегі қанның гемоглобин мөлшері қалыпты көрсеткіштен айтарлықтай ерекшеленеді. Осы аптадан босануға дейінгі кезеңде қандағы гемоглобин мөлшері  q/dl шамасында болады. Дүниеге келгеннен кейін қысқа уақыт ішінде гемоглобин мөлшері  q/dl дейін жоғарылағанымен, үшінші айға жеткенде бұл көрсеткіш  q/dl шамасына дейін төмендейді. Бөпеңіз дүниеге келген кезде сүйек кемігінде эритроциттердің түзілуі уақытша тоқтайды. Бұл оның ағзасының туғаннан кейін оттегі қысымына тап болуына байланысты. Сүйек кемігі оттегі қысымына бейімделгеннен кейін бұл үдеріс реттеледі, алайда жаңа туған бөпелерде физиологиялық анемия деп аталатын қаназдық жиі кездеседі.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен "домалап" жатырмын! 🔄 Бұрын аяқпен тепкілейтінмін, ал қазір орным соншалықты тар болғандықтан, тек домалап немесе шынтағыммен итере аламын. Сіз ішіңіздің үстінен менің өкшемнің немесе тіземнің томпайып тұрғанын көре аласыз. Мені сипап қойыңызшы, мүмкін, кері жылжитын шығармын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қауын'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік басталғаннан кейін қандағы мөлшері едәуір артатын прогестерон гормонының әсерінен көздің ең алдыңғы бөлігінде орналасқан мөлдір қабаттың — қасаң қабық тінінің суды ұстап тұру қасиеті өзгереді. Соның нәтижесінде көру бұлдырауы мүмкін, әсіресе жанаспалы линза тағатын адамдарда линзаға жоғары сезімталдық пайда болуы ықтимал. Бұл кезеңде жанаспалы линза тағудан бас тартқан жөн. Сонымен қатар жүктілік кезінде андроген гормонының азаюы көздің құрғауына әкелуі мүмкін. Дәрігердің ұсынысымен қолданылатын жасанды көз жасы тамшылары құрғақтықты жеңілдетеді. Бұл шағым көбіне босанғаннан кейін азайып, толықтай жоғалады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ісінуді азайту үшін суды мол ішуді жалғастырыңыз және аяғыңызды үнемі жоғары көтеріп демалыңыз. Беліңіз ауырса, жүктілікке арналған жеңіл гимнастика немесе йога жаттығулары өзіңізді жақсы сезінуге көмектеседі.') WHERE id = '8220cf1e-c217-46c8-aaef-257724e08389';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің салмағын тез қосуы оның денесінде май жасушаларының түзілуіне байланысты. Бұл майлар босанғаннан кейін бөпеңіздің дене температурасын реттеу үшін өте маңызды. Бүйректері толық жетіліп, тәулігіне 1 литрден астам несеп бөледі. Осы аптада жатырдағы қағанақ суының мөлшері азая бастайды. Бөпе айтарлықтай өскендіктен, бұл қалыпты жағдай және су мөлшері қауіпті деңгейге дейін азаймаса, алаңдауға негіз жоқ.;;;
Бұдан әрі бөпеңіздің салмағы арта бергенімен, бойының өсуі сәл баяулайды. Нәрестелердің туған кездегі бойы әдетте 48-52 см болады.'), baby_message_kk = COALESCE(baby_message_kk, '35 АПТА АЯҚТАЛДЫ! 👋 Сәлем, 9-ай! (Күнтізбе бойынша). Біз мәреге таяп қалдық. Мұнда маған орын өте тар, бірақ мен қимылдауымды жалғастырып жүрмін. Егер қимылым азайса, міндетті түрде дәрігерге айт. Мен ішім пысқанда емес, ұйықтап жатқанда тыныш боламын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен салат жапырағы'), body_changes_kk = COALESCE(body_changes_kk, 'Мерзімінен бұрын босану қаупі азаяды. Егер босану қазір басталса, бөпелердің 99%-ы аман қалып, ұзақ мерзімді ауыр мәселелерге тап болмайды. Дегенмен бұл әлі де «мерзімінен бұрын босану» болып саналады. Брэкстон-Хикс толғақтары біршама тұрақты болуы мүмкін, сондықтан оларды шынайы толғақтан ажыратуды үйреніңіз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Апта сайынғы дәрігер тексерулерін өткізіп алмаңыз. Соңғы апталарда жағдай тез өзгеруі мүмкін. Сұрақтарыңыз болса, барлығын жазып алып, дәрігерге қойыңыз.') WHERE id = '7800e1ad-f092-45f7-8448-b5a2384087fa';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, '36-апта аяқталғаннан кейін бөпеңіз үшін жаңа кезең басталады. Бұл — босану орын алған жағдайда бөпеңіз шала туған деп есептелетін соңғы апта.;;;
Жүктілік кезінде қан қысымының жоғары болуы, преэклампсия, әртүрлі инфекциялар, жатыр мойнының жеткіліксіздігі, қан ұюының бұзылыстары, темекі шегу мен алкоголь тұтыну, жүктілікті тиісінше бақыламау және әлеуметтік-экономикалық жағдайдың төмен болуы сияқты факторлардың салдарынан мерзімінен бұрын босану орын алуы мүмкін. Жүктіліктің 37 аптасы толмай дүниеге келген бөпелер шала туған болып саналады. Егер осы аптада босансаңыз, қысқа мерзімді тыныс алу қолдауының көмегімен бөпеңіз еш қиындықсыз өмір сүре алады. 37-аптаға кіретін жүктіліктің 36+0 және 36+6 апталары аралығында бөпеңіздің дамуының басым бөлігі аяқталып, ол кез келген сәтте дүниеге келуге дайын болады.;;;
Дегенмен өкпеде сурфактант түзілуі аяқталып, ішек толық жұмыс істей бастайтын 38-аптаға дейінгі босану кезінде кейбір қиындықтар туындауы мүмкін. Кейбір мамандар шаншуды (балалардағы іш кебуінен болатын ауырсынуды) ішек толық жетілмей тұрып дүниеге келумен байланыстырады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен томпақ болып келемін! 🧸 Anacan, менің бетім, қолдарым мен аяқтарым майға толды. Енді бұрынғыдай қатты әжімді емеспін. Салмағым күн сайын артып келеді. Бұл май қабаты дүниеге келгеннен кейін денемді жылы ұстап, күш-қуатымды сақтауға көмектеседі. Сен мені құшағыңа алғанда, мен жұп-жұмсақ боламын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен салат жапырағы'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде өзіңіз үшін де, бөпеңіз үшін де жеміс-жидек жеу керектігін ұмытпаңыз. Солардың бірі — кальцийге, калийге, C дәруменіне, фолий қышқылына және B6 дәруменіне бай банан. Банан жүктілік кезінде аса маңызды темірге деген қажеттілікті өтеуге көмектеседі. Сонымен қатар ол фолий қышқылына өте бай. Фолий қышқылы бөпеңіздің омыртқасы мен жүйке жүйесінің дамуы үшін аса маңызды. Бөпеңіздің сүйектері қалыптасқан кезде қажет болатын кальций де бананда жеткілікті мөлшерде бар. Сондықтан оны әсіресе бөпеңіздің сүйектері сау дамуы үшін тұтынған жөн. Банан — B6 дәруменінің де жақсы көзі. B6 дәрумені жүйке жүйеңізде нейромедиатор қызметін атқарады. Сондай-ақ ол ағзаңызда эритроциттердің түзілуіне ықпал етеді. C дәруменіне бай банан — жақсы антиоксидант. Сондықтан ол жасушалардың қартаюын баяулатып, иммундық жүйеңізді нығайтады. Бананның құрамында ішекке пайдалы талшықтар бар. Алайда жүктілік кезінде ас қорыту жүйесі баяулайтынын ескерсек, бананды шамадан тыс тұтыну іш қатуға әкелуі мүмкін. Сондықтан күнделікті тамақтану жоспарыңызға 2 кішкентай банан қосу жеткілікті.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ентігуді азайту үшін отырғанда арқаңызды міндетті түрде тік ұстаңыз. Аяқтағы ауырлық пен ісінуді азайту үшін оларды үнемі жоғары көтеріп демалдырыңыз. Осы күндері перзентхана сөмкеңіздің ішіндегілерді асықпай тексеріп, бәрінің дайын екеніне көз жеткізіңіз. Қыжыл ұйқыңызға кедергі келтірмеуі үшін кешкі асты жеңіл әрі аз мөлшерде ішуге тырысыңыз.') WHERE id = 'e948b641-0b79-4f83-9869-a66d090c81f1';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ми бағаны өз орнын алып, ұйқы, сергектік және тіпті түс көру сияқты үдерістерді басқара бастады. Мидың төменгі бөлігінде орналасқан бұл шағын аймақ өте маңызды. Өйткені ми мен дене арасындағы барлық жүйке байланыстары дәл осы жер арқылы өтеді. Ми бағаны тыныс алу, жұтыну және жүрек соғысы сияқты өмірлік маңызды қызметтерді реттейді. Сондай-ақ осы кезеңде бөпеңіздің циркадтық ырғағы, яғни биологиялық сағаты қалыптасады. Бұл ырғақ ағзаның 24 сағат ішінде қалай жұмыс істейтінін автоматты түрде реттейді. Мысалы, түнде ұйқы шақыратын мелатонин гормонының бөлінуі немесе таңертең қан қысымының жоғарылауы осы биологиялық сағаттың арқасында жүзеге асады.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен салат жапырағы'), body_changes_kk = COALESCE(body_changes_kk, 'Теріңіздегі өзгерістер жүктілік кезінде гормондық тепе-теңдіктің өзгеруінен туындайды. Босанғаннан кейін көп ұзамай тері түсінің өзгеруін қоса алғанда, әртүрлі тері мәселелері біртіндеп түзеле бастайды. Терідегі түс өзгерістері көбіне бетте, үстіңгі еріннің үстінде, мұрын мен иек тұсында және маңдайда байқалады. Олар ашық немесе қою қоңыр дақтар түрінде пайда болады. «Жүктілік маскасы» деп аталатын бұл дақтар әдетте босанғаннан кейін жоғалады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бүгін демалуға көбірек уақыт бөліңіз. Жамбас тұсындағы ауырсынуды азайту үшін арқаңызды тіреп тұратын жастықтарды міндетті түрде қолданыңыз. Егер әлі жасамаған болсаңыз, перзентханаға апаратын құжаттарыңыздың түгел екеніне көз жеткізіңіз. Ертеңнен бастап 37-аптаға — босану кез келген сәтте басталуы мүмкін «дайындық» кезеңіне кіреміз!') WHERE id = 'e930fbe3-29bc-4413-bfef-dc68f6603a0e';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің тестостерон өндіруі жалғасуда. Бұл үдеріс ұл бөпелерде де, қыз бөпелерде де жүреді. Тестостерон — андрогендер тобына жататын стероидты, яғни құрылымында майы бар гормон. Ұл бөпелерде тестостерон гормоны негізінен аталық бездерде және бүйректің үстінде орналасқан бүйрекүсті бездерінде өндіріледі. Ал қыз бөпелерде тестостерон өндіруге аналық бездер жауап береді. Екі жыныста да бұл гормонның бөлінуін мидың гипоталамус аймағы басқарады.;;;
Тестостерон гормоны қыз бөпелерде де бөлінгенімен, оның мөлшері ұл бөпелермен салыстырғанда әлдеқайда аз. Жасөспірімдік кезеңде көп мөлшерде бөліне бастайтын тестостерон гормонының ағзадағы деңгейі 20 жаста ең жоғары шегіне жетіп, 30 жастан бастап біртіндеп төмендейді. Тестостерон бөпеңіздің жатырішілік даму кезеңінде жыныс мүшелерінің қалыптасуында маңызды рөл атқарады. Ұл бөпелердің жыныс мүшесі мен аталық бездері дұрыс дамуы үшін тестостеронның жеткілікті мөлшерде болуы маңызды. Ер адамдарда ол дауыстың жуандауы, түктердің өсуі, жыныс мүшелерінің өсіп, өз қызметін атқара бастауы сияқты үдерістерге жауап береді. Ал қыз бөпелерде эстроген рецепторларын белсендіруге, шеміршек тінінің сүйектенуін ынталандыруға және әсіресе жатырішілік кезеңде овуляцияны қоздыратын LH гормонының механизміне қатысады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен 99% дайынмын! ✅ Егер мен бүгін дүниеге келсем, ешқандай күрделі мәселесіз тірі қалу ықтималдығым өте жоғары (мүмкін, қысқа уақытқа арнайы күтім қажет болар). Өкпем толықтай дерлік дайын. Бірақ анамның құрсағында қала тұру маған көбірек салмақ жинап, күш-қуат береді. Асықпайық!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен салат жапырағы'), body_changes_kk = COALESCE(body_changes_kk, 'Дәрігеріңіз осы аптадан бастап апта сайын КТГ-дан өтуді ұсынуы мүмкін. КТГ жүргізілген кезде бөпенің ұйықтап жатуы немесе жүктілік мерзімі сияқты факторлар нәтижеге әсер етеді. Сондықтан мерзімінен бұрын босану қаупі болмаса, жүктіліктің 28 аптасына дейін КТГ жасалмайды. КТГ нәтижесі барынша дәл болуы үшін тексеруді тамақтанғаннан кейін 2 сағаттан соң бастаған жөн. Процедура кезінде ішіңізге екі датчик бекітіледі. Бір датчик толғақтарды бақыласа, екіншісі бөпеңіздің жүрек соғысы мен қимылдарын қадағалайды.;;;
КТГ — әсіресе жүктіліктің соңғы кезеңдерінде жатырдағы бөпеңіздің жағдайын бағалау үшін қолданылатын әдістердің бірі. Атап айтқанда, қант диабеті, созылмалы бүйрек ауруы, жүктілік кезінде пайда болған жоғары қан қысымы, бөпе қимылының азаюы, дамудың тежелуі, қағанақ суының азаюы немесе жүктілік мерзімінің 40 аптадан асып кетуі сияқты жағдайларда бөпенің жағдайы КТГ арқылы бақыланады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бел мен жамбас ауыруын азайту үшін отырғанда арқаңызды тіреп тұратын жастықтарды міндетті түрде пайдаланыңыз. Аяғыңыз қатты ісінсе, кешке 15-20 минут бойы аяғыңызды қабырғаға тіреп, жоғары көтеріп ұстаңыз. Суды молынан ішуді жалғастырыңыз: бұл бүйректеріңіздің жұмысы үшін де, қағанақ суының жаңаруы үшін де маңызды. Бүгін өзіңізді қатты шаршатпай, дене белсенділігін барынша азайтыңыз.') WHERE id = 'ded751f7-f2a6-42dd-a319-bc879f101abf';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ми қатпарлары дүниеге келген кездегі қалпына толықтай дерлік жетті. Мидың қатпарсыз күйдегі өлшемі орта есеппен  см болады. Дене өлшеміне сай болуы үшін мида қатпарлардың пайда болуы қажет. Қысқаша айтқанда, ми қатпарлары — ми бетінің ауданын үлкейтетін құрылымдық ерекшелік.'), baby_message_kk = COALESCE(baby_message_kk, 'Даусыңызға жауап беремін! 🎤 Сіз сөйлегенде, мен қимылдаймын. Сіз күлгенде, мен де секіріп-қозғаламын. Ал әкемнің даусы маған ертегідей естіледі. Менімен сөйлесе беріңіздер, мен тыңдап жатырмын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен салат жапырағы'), body_changes_kk = COALESCE(body_changes_kk, 'Қасаға сүйектерінің қосылған жеріндегі ауырсыну (симфизит) жүруді қиындатуы мүмкін. Төсекте бір қырыңыздан екінші қырыңызға аунау нағыз азапқа айналуы ықтимал. Бұл — жамбастың босануға дайындалып, кеңею үдерісі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Босануға арналған сөмкеңіздің толық жиналғанына және құжаттарыңыздың қолжетімді жерде тұрғанына көз жеткізіңіз. Бүгін біраз демалып, бөпеңізбен сөйлесіңіз. Ол Сіздің мейірімге толы дауыс ырғағыңызды жақсы таниды.') WHERE id = '0307b519-8b14-459a-84c3-9d370f50a4be';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің жүйке жүйесінің дамуы аяқталуға жақын. Бұл кезеңде жүйке жүйесі автономды жүйке жүйесі және шеткі жүйке жүйесі болып екіге бөлінеді. Автономды жүйке жүйесі — мидың еріксіз қозғалыстар мен ағза мүшелерінің қызметін басқаратын бөлігі. Жүрек соғу жиілігі, астың қорытылуы, оттегі мен көмірқышқыл газының алмасуына қажетті тыныс алу қимылдары, сілекейдің бөлінуі, терлеу және зәр шығару сияқты үдерістерді автономды жүйке жүйесі адамның еркінен тыс басқарады.'), baby_message_kk = COALESCE(baby_message_kk, 'Қолдарымда май қабаты жиналды! 💪 Қолдарым мен аяқтарым енді шыбықтай емес, кәдімгідей "бүктесін-бүктесін" болып қалды. Шынтақтарым мен тізелерімде сондай сүйкімді шұңқырлар пайда болып жатыр. Терім тегіс. Мен құшақтау үшін жаратылғанмын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен салат жапырағы'), body_changes_kk = COALESCE(body_changes_kk, 'В тобының стрептокогына (GBS) талдау тапсыратын уақыт келді. 35-37-ші апталар аралығында жасалатын бұл тексеру В тобының стрептококк бактерияларын анықтауға арналған. Дәрігеріңіз қынаптан жағынды алып, бұл бактерияның бар-жоғын тексереді. Бұл бактерия Сізге зиян келтірмейді, бірақ босану кезінде бөпеге жұғуы мүмкін. Егер бактерия анықталса, босану кезінде антибиотик егіледі. Табиғи жолмен босануды жоспарласаңыз, бұл талдауды міндетті түрде тапсыруыңыз керек.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Төсекте аунаған кезде тізелеріңізді бір-біріне тигізіп ұстаңыз (су перісі сияқты). Бұл жамбас сүйектеріндегі ауырсыну мен кернеуді азайтады.') WHERE id = 'f9ddf067-2beb-491f-a9d9-5cef8bbb118b';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің иммундық жүйесі плацента арқылы Сізден оған берілетін антиденелердің арқасында қалыптасады. Антиденелер — құрамында қанттар мен аминқышқылдары бар органикалық молекулалардан түзілген гликопротеиндер. Ағзаға енген бөгде заттарға қарсы ағзаның өзі түзетін қорғаныш заттар антиденелер деп аталады. Бөпеңіздің ағзасы өз антиденелерін босанғаннан кейін белгілі бір уақыт өткен соң өндіре бастайды. Өз иммундық жүйесі толық қалыптасқанға дейін бөпеңіз антигендер деп аталатын зиянды микроорганизмдерден Сіздің ағзаңыздан берілген антиденелердің көмегімен қорғанады. Антиденелер қандағы жасушаларға әлі енбеген зиянды микроорганизмдерді, вирустарды және басқа бөгде бөлшектерді жояды. Қанға қандай да бір бактерия түскенде, лимфоциттер мен макрофагтар сияқты иммундық жүйе жасушалары бактерия қабырғасындағы өзгеше молекулалық құрылымды танып, антиденелер өндіре бастайды. Ағзада әр антигенге тән лимфоцит қалыптасады. Лимфоциттер де өздеріне тән антиденелерді синтездейді. Қан тобының сәйкессіздігі антигендер мен антиденелердің өзара әрекеттесуі нәтижесінде пайда болады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен қазір әжептәуір үлкейіп қалдым. Жатырдағы бос кеңістіктің барлығын дерлік алып жатырмын. Енді тек салмақ қосып жатырмын — аптасына шамамен 200-250 грамм қосамын. Бетім, қолдарым мен аяқтарым томпақ болып келеді.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қауын'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің соңына жақындаған осы күндері ісіну мен домбығуға қатысты шағымдарыңыз айтарлықтай күшеюі мүмкін. Ісіну негізінен қан айналымының бұзылуы салдарынан пайда болады. Әсіресе соңғы триместрде қатты ұлғайған жатыр жамбас пен аяқтарыңыздағы қан тамырларына қысым түсіреді. Бұл қысым қан айналымын баяулатады. Қан айналымының баяулауы салдарынан ісіну пайда болады. Сұйықтықтың жиналуынан туындайтын бұл ісінулер жүктілік кезінде қосылған салмақтың шамамен 25%-ын құрауы мүмкін. Жүктілік кезінде ісінуден толық арылу мүмкін емес. Алайда кейбір шаралардың көмегімен оны аздап азайтуға болады. Күн сайын жүйелі түрде жаттығу жасау, ұзақ уақыт отырудан немесе тік тұрудан аулақ болу, күні бойы аяқтарды жоғары көтеріп, қан айналымына көмектесу және ұйықтағанда сол жақ қырыңызбен жату — осындай шаралардың кейбірі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Кегель жаттығуларын" жалғастырыңыз. Бұл босанғаннан кейін зәр ұстай алмаудың алдын алудың ең тиімді жолы. Күніне 3 рет 10 қайталаудан жасаңыз.') WHERE id = 'f7c92a09-eddb-4b29-936d-0133e3378e1e';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің иммундық жүйесінің туылғанға дейін дамымауының ең қарапайым себебі — оның Сіздің ағзаңыздың ішінде өмір сүруі. Бөпеңіз жатырда болған кезде оның иммундық жүйесі белсенділігін тежеуге мәжбүр. Осының арқасында бөпеңіздің қорғаныш жасушалары мен Сіздің ағзаңыздың қорғаныш жасушалары бір-біріне төзімділік таныта алады. Туылғаннан кейін дами бастайтын иммундық жүйе антиденелерден бөлек, гликопротеиндік құрылымы бар интерферон деп аталатын тағы бір қорғаныш ақуызын өндіре бастайды. Интерферон — вирустарға қарсы қорғаныш реакциясы ретінде ағза жасушалары өндіретін, ақуыз бен көмірсу бөліктерінен тұратын қорғаныш ақуызы. Вирустардың жасуша ішінде көбеюіне жол бермейтін интерферондар ағзада өте жылдам өндіріліп, вирустарға қарсы қуатты қорғанысты қамтамасыз етеді. Интерферондар жасушаларға вирус немесе басқа бөгде зат туралы белгі түскенде өндіріледі. Оның әсер ету қағидасы мынадай: жасуша вирус шабуылына ұшыраған кезде оның ДНҚ-сындағы интерферон өндірілуіне жауапты ген белсендіріледі. Бөлінген интерферондардан белгі алған айналадағы жасушалар ақуыз синтезі үдерісін өзгертіп, вирустың жасуша ішінде әрі қарай көбейе алмауына ықпал ететін ақуыздарды өндіреді. Осылайша вирустардың ағзаны зақымдауына жол берілмейді.'), baby_message_kk = COALESCE(baby_message_kk, 'Басым төмен қарап тұрған сияқты! ⬇️ Мен босануға арналған қалыпқа келіп қойдым. Басым Сіздің жамбас сүйектеріңіздің арасына кірді. Бұл маған сәл жайсыз, бірақ шығатын жерге апаратын ең жақын жол осы. Егер әлі бұрылмаған болсам, дәрігеріңіз Сізге кейбір жаттығуларды ұсынуы мүмкін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қауын'), body_changes_kk = COALESCE(body_changes_kk, 'Тыныс алуыңыз сәл жеңілдеуі мүмкін. Бөпе төмен түскендіктен, өкпе мен асқазанға түсетін қысым азаяды. Енді еркінірек тыныс алып, көбірек тамақтана аласыз. Бірақ оның орнына шап аймағы мен қуыққа түсетін қысым артады.;;;
Сонымен қатар тыныс алуыңыз сәл жеңілдеуі мүмкін. Бөпе төмен түскендіктен, өкпе мен асқазанға түсетін қысым азаяды. Енді еркінірек тыныс алып, көбірек тамақтана аласыз. Бірақ оның орнына шап аймағы мен қуыққа түсетін қысым артады.'), daily_tip_kk = COALESCE(daily_tip_kk, '35 апталық жолды сәтті өткергеніңіз үшін бүгін өзіңізді қуантып, демалыңыз. Беліңіздегі ауырсынуды азайту үшін арқаңызды тіреп тұратын жастықтарды міндетті түрде қолданыңыз. Егер бөпе төмен түсіп, жүрген кезде жамбас тұсыңыз ауырса, баяу әрі абайлап қимылдаңыз. Ертеңнен бастап 36-аптаға — босануға апаратын соңғы үлкен кезеңге қадам басамыз!') WHERE id = '3e398e58-41a7-4c07-9c59-78972adc37be';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ішегінде меконий жинала береді. Меконий — өте жабысқақ, қою, қошқыл жасыл немесе қара түсті, бөпеңіздің алғашқы нәжісі. %90-ы судан тұратын бұл заттың құрамында бөпеңіздің терісінен түскен лануго түктері, ішек эпителийінің жасушалары, шырыш пен өт сұйықтығы болады. Меконий құрамындағы билирубин мөлшерінің жоғары болуы жаңа туған нәрестелердегі сарғаюдың маңызды себептерінің бірі. Туылғаннан кейінгі алғашқы 48 сағат ішінде меконийін анус арқылы шығармаған бөпелерде сарғаю көрсеткіштері қалыпты деңгейден жоғары болуы мүмкін. Билирубин — ағзадағы эритроциттердің табиғи ыдырауы кезінде түзілетін сары түсті зат. Ол бауырда өңделіп, ас қорыту үдерісі кезінде ағзадан шығарылады. Ал бөпеңіздің анусы босанғанға дейін жабық күйде болады. Сондықтан билирубин тоқ ішекте меконийдің құрамында жиналады. Босанғаннан кейін белгілі бір уақыт ішінде меконий ағзадан шықпаса, ішек билирубинді қайта сіңіріп, қанға өткізеді. Қандағы билирубин мөлшерінің едәуір артуы сарғаюға әкеледі.'), baby_message_kk = COALESCE(baby_message_kk, 'Түстерім сондай айқын! Anacan, мен REM ұйқысында көп уақыт өткіземін. Миым сондай белсенді! Ал ояу кезімде айналамды көзіммен бақылаймын (қараңғы болса да). Жарық пен көлеңкені өте жақсы ажыратамын. Сіз мені көрмесеңіз де, мен Сізді сеземін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен жапырақты салат'), body_changes_kk = COALESCE(body_changes_kk, 'Ұйқысыздық Сізді ашуланшақ етуі мүмкін. Жайлы ұйықтай алмайсыз, денеңіздің әр жері ауырады. "Босану қалай өтеді?" деген ойлар маза бермейді. Бұл — табиғаттың Сізді түнде бөпеге қарау үшін оянуға дайындау тәсілі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Осы аптадан бастап дәрігердің тексеруіне апта сайын бару ұсынылады. Босануға арналған сөмкеңізді соңғы рет тексеріп, жетіспейтін ұсақ-түйекті толықтырыңыз. Жамбас тұсындағы ауырсынуды азайту үшін отырғанда аяқтарыңызды айқастырмаңыз және бір қалыпта тым ұзақ отырмаңыз. Сол жақ қырыңызбен жатып демалуды және күні бойы бөпеңіздің қимылдарын бақылауды жалғастырыңыз.') WHERE id = 'df4bd1af-d6a3-4228-b3e2-3e6d8392ce93';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің бауыры кейбір қалдық заттарды тазартып, ас қорыту үдерісіне қатыса бастады. Бұл өмірлік маңызды мүше бөпеңіздің ағзасында өзіндік "зертхана" қызметін атқарады:;;;
• Тазарту: Бауыр ағзадағы улы аммиакты зияны азырақ заттарға айналдырады және ескірген қан жасушаларын ыдыратып, ағзадан шығарады.;;;
• Энергия және ас қорыту: Тағамнан алынған заттарды өңдеп, басқа мүшелерге таратады. Майлар мен ақуыздарды қорытуға қажетті өт сұйықтығын өндіреді.;;;
• Қорғаныс жүйесі: Иммунитетті нығайтатын антиденелер түзеді және дене температурасын реттейді.;;;
• Маңызды ақуыздар: Қанның тамырлар ішінде сақталуын қамтамасыз ететін альбумин ақуызының өндірілуіне жауап береді.;;;
Қысқаша айтқанда, бөпеңіздің бауыры ағзаны тазартып қана қоймай, оны аурулардан қорғауға да дайындалады.'), baby_message_kk = COALESCE(baby_message_kk, 'Түктерімді жеп жүрмін! 😮 (Біртүрлі естілетінін білемін). Денемді жауып тұрған нәзік "Лануго" түктері мен "Верникс" қабаты түсіп жатыр. Мен оларды қағанақ суымен бірге жұтамын. Олар ішегімде жиналып, менің алғашқы нәжісіме (Меконий) айналады. Алғаш рет жөргегімді ауыстырғанда мұны көресіз!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Мангольд'), body_changes_kk = COALESCE(body_changes_kk, 'Тамақтану арқылы жеткілікті мөлшерде алынбайтын бұл заттардың орнын жүктілік кезінде дәрігеріңіз ұсынған қоспалармен толықтыруға болады. Оларға фолий қышқылы, темір, кальций, магний, мырыш, D дәрумені және омега май қышқылдары жатады. Жүктіліктің екінші триместрінен бастап жүкті әйелдердің барлығына дерлік тағайындалатын минералдардың бірі — темір. Темір Сіздің және бөпеңіздің қан түзу үдерісі үшін өте маңызды әрі анемия қаупінің алдын алады. Сонымен қатар темір тапшылығы бөпеңіздің салмағы орташа көрсеткіштен төмен болып туу қаупін арттырады. Бұған қоса, дәрумендер кешені де тағайындалуы мүмкін. Бұл қоспалар өте пайдалы болғанымен, оларды дәрігеріңіздің кеңесінсіз қабылдамауыңыз керек.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бөпе толық жетілгендіктен, босанудың белгілеріне мұқият болыңыз. Жамбас тұсындағы ауырсынуды азайту үшін жеңіл созылу жаттығуларын жүйелі түрде жасап, ауыр заттарды көтермеңіз. Босануға арналған сөмкеңізді есіктің жанына қойып, дәрігеріңізбен соңғы рет бәрін келісіп алыңыз. Бүгін өзіңізді қатты шаршатпай, күшіңізді маңызды күнге сақтаңыз.') WHERE id = 'cc423b6f-434a-47b7-97ce-c5b407e5861b';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ағзасындағы барлық қызметтер, соның ішінде сезім мүшелері де қазір толық жұмыс істеп тұр. Әсіресе сезімдерді басқаратын ми аймағының дамығаны сонша, бөпеңіз Сіздің даусыңызға жауап бере алатындай сезімтал болды. Бөпеңіздің миы екі жартышардан — сол және оң жартышардан тұрады. Бұл жартышарлар өзара тұрақты байланыста болу үшін күрделі жүйке талшықтары арқылы жалғасқан. Мидың негізгі міндеті — ішкі мүшелердің жұмысын реттеу арқылы ағзаның саулығын сақтап, тіршілікті қамтамасыз ету. Сонымен қатар ол сезім мүшелері арқылы қоршаған ортадан келетін барлық сигналды өңдеп, түсіндіреді және қажет деп тапқандарын жадында сақтайды. Есту қабілетінің арқасында бөпеңіз оң жақ ми жартышарын белсенді пайдалана бастады. Оның Сіздің даусыңызды айналадағы басқа дыбыстардан ажырата алуы дәл осы дамыған миы мен жүйке жүйесінің арқасында мүмкін болып отыр.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен төмен түсіп келемін! 📉 Сезіп тұрсыз ба? Басым Сіздің жамбас қуысыңызға толық орнықты. Маған бұл жерде сәл тар, бірақ шығатын жолға ең жақын орын осы. Сіз енді жеңілірек тыныстайтын шығарсыз, бірақ дәретханаға жиірек барасыз.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Мангольд'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде теңгерімді әрі жүйелі тамақтануыңыз бөпеңіздің дені сау болып дамуы үшін өте маңызды. Бөпеңіздің дамуына көмектесетін ең маңызды тағамдардың бірі — қуырылмаған жаңғақтар мен дәндер. Олардың құрамында қанықпаған май қышқылдары, селен, түрлі дәрумендер мен минералдар мол. Грек жаңғағы бөпеңіздің миының дамуына белсенді ықпал етеді. Антиоксиданттық қасиеті бар бұл тағам талшық пен ақуыздың да жақсы көзі саналады. Пісте — жүктілік кезінде ағзаңызға қажетті май қышқылдарын толықтыру үшін тұтынуға болатын дән. Орман жаңғағы құрамындағы кальцийдің арқасында бөпеңіздің сүйектерінің дамуына зор қолдау көрсетеді. Сондай-ақ ол — жақсы энергия көзі. Бадам дәрумендер мен минералдарға өте бай, әсіресе құрамындағы мырыштың мол болуы босанғаннан кейін ана сүтінің сапалы болуына көмектеседі. Кешью құрамындағы мыс минералының арқасында ағзаның күнделікті мысқа деген қажеттілігін өтеуге көмектеседі. Кептірілген інжір мырышқа, темірге, калий мен кальцийге өте бай. Кептірілген інжір жеу арқылы бөпеңізге даму кезеңінде қажет минералдарды алуға болады. Жаңғақтар мен дәндер өте пайдалы болғанымен, олардың тағамдық құндылығы мен майлылығы жоғары. Сондықтан күніне бір уыстан артық тұтынбаған жөн.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Босану кез келген сәтте басталуы мүмкін кезеңде болғандықтан, күшіңізді сақтаңыз. Аяқтағы ісінуді азайту үшін тұзды аз тұтынып, мол су ішіңіз. Бракстон-Хикс толғақтары жүйелі болмаса, бұл ағзаңыздың жаттығуы ғана, алаңдамаңыз. Бүгін өзіңізге біраз уақыт бөліп, бөпеңіз үшін дайындаған бөлмеге немесе киімдерге қарап, көңіліңізді тыныштандырыңыз.') WHERE id = 'cd1a59da-8207-4de3-b297-f013b1d7c429';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің қаңқа жүйесі қазір негізінен шеміршектен тұрса да, сүйектену үдерісі жылдам жалғасуда. Осы кезеңде бөпе Сіз қабылдаған кальцийдің барлығына жуығын сіңіреді. Егер тағамыңызда кальций жеткіліксіз болса, ол бұл қажеттілігін Сіздің сүйектеріңіздегі кальций қорынан өтейді.;;;
Шеміршек тінінің бір қызық ерекшелігі бар: онда қан тамырлары мен жүйкелер болмайды. Бөпенің шеміршек жасушалары қажетті оттегі мен қоректік заттарды айналасындағы тіндерден диффузия арқылы алады, ал қалдықтарды дәл сол жолмен шығарады. Бөпенің қаңқасын қалыптастыратын бұл тін талшықты шеміршек деп аталады. Ол қысым мен қозғалысқа өте төзімді, өйткені құрамында коллаген талшықтары мол. Коллаген талшықтары ақуыздан тұрады және тіндердің серпімділігі мен беріктігін қамтамасыз етеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Мені күтіп жүрсіз бе? ⏳ Шыдамсызданып жүргеніңізді білемін. "Қашан келесің?" деп сұрайсыз. Бірақ мен әлі толық дайын емеспін. Миым әлі де дамып жатыр, өкпем соңғы дайындықтан өтуде. Ана құрсағында өткізген әр күнім мені күшейте түседі. Сабыр сақтаңыз, Anacan.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Мангольд'), body_changes_kk = COALESCE(body_changes_kk, 'Босанудың басталуына нақты не түрткі болатыны толық анықталмағанымен, жүктіліктің соңғы кезеңінде жатыр өндіретін простагландин гормонының босану кезінде айтарлықтай көбейетіні белгілі. Құрамында май қышқылдары бар бұл гормон ауырсыну рецепторларының механикалық және химиялық тітіркендіргіштерге сезімталдығын арттыратын химиялық қосылыс қызметін атқарады. Жүктіліктен тыс уақытта ол етеккір кезіндегі ауырсынуға себеп болса, босану кезінде жатыр бұлшықеттерінің жиырылуын қамтамасыз етеді.;;;
Сонымен қатар жүктіліктің соңғы күндерінде ішек жиірек босай бастайды. Бұл іш тұсының ауырсынуына әкелуі мүмкін. Босану алдында пайда болатын іш өту ағзаның босануға дайындығы ретінде қарастырылады: ол ішекті тазартып, жатыр бұлшықеттерінің еркінірек жұмыс істеуіне мүмкіндік береді.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Осы кезеңдегі ұйқысыздықпен күресу үшін күндіз 15-20 минутқа көз шырымын алыңыз. Ісінуді азайту үшін аяқтарыңызды жүйелі түрде биікке көтеріп қойыңыз. Егер әлі жасамаған болсаңыз, ауруханадан үйге қайтқанда бөпені тасымалдауға арналған автокреслоны көлікке орнатып, тексеріп қойыңыз. Бүгін өзіңізді шаршатпаңыз, әр қимылыңызды асықпай жасаңыз.') WHERE id = 'ff965161-e8f2-4262-b993-4dbf99f22a66';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің рефлекстері күн сайын күшейіп келеді. Ол әлі сөйлей алмаса да, осы еріксіз қимылдар арқылы айналасын танып, өзін қорғайды және Сізбен байланыс орнатады. Бағдарлау рефлексінің арқасында бөпеңіз жарыққа сезімтал болады және жарықты көрген бойда басын сол жаққа бұрып, айналасын зерттеуге тырысады. Ең маңызды рефлекстердің бірі — іздеу және ему рефлекстері бөпеңіздің қоректенуін қамтамасыз етеді: аузының шетіне қол тигізгенде, ол бірден басын сол жаққа бұрып, сүт іздей бастайды. Бұл әрекет шамамен 3-4 айдан кейін саналы қимылға айналады. Ал көзді жыпылықтату рефлексі — бөпеңіздің өзін-өзі қорғау механизмі: қатты әрі жарқын жарықты көргенде, ол көзін жыпылықтатып, өзін жайсыздықтан қорғайды. Осы рефлекстердің барлығы бөпеңіздің дені сау дамып келе жатқанының және жүйке жүйесінің дұрыс жұмыс істейтінінің негізгі көрсеткіштері болып саналады.'), baby_message_kk = COALESCE(baby_message_kk, 'Қимылдарым өзгеріп жатыр! 🛑 Орным тым тар болғандықтан, бұрынғыдай қатты тебе алмаймын. Оның орнына Сіз менің "сырғығанымды", "айналғанымды" сезесіз. Қимылдарымның сипаты өзгерсе де, жиілігі азаймауы керек. Мен күн сайын белсенді болуым керек.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Мангольд'), body_changes_kk = COALESCE(body_changes_kk, 'Жақындап қалған босануға байланысты денеңізде кейбір белгілер пайда болуы мүмкін. Босанар алдындағы дене өзгерістері босануға бірнеше сағат қалғанда да, бір ай бұрын да басталуы ықтимал. Осындай белгілердің бірі, әсіресе соңғы айда байқалатын, халық арасында "іштің төмен түсуі" деп аталатын жағдай. Әсіресе бұл алғашқы жүктілігіңіз болса, бөпеңіз әдетте босану басталғанға дейінгі бір ай ішінде жамбас сүйегіне қарай төмендей бастайды. Бөпеңіздің босану жолына орналасуын білдіретін бұл жағдайда қынап пен тік ішек аймағында қысым сезілуі мүмкін. Бұған бөпеңіздің жамбас сүйектеріңізге қысым түсіруі себеп болады.;;;
Босану жақындаған сайын әйелдердің жартысына жуығы салмақ қосудың тоқтағанын, тіпті 1-2 килограмм салмақ жоғалтқанын байқайды. Мұның нақты себебі белгісіз болғанымен, бұл ішектің белсенді жұмыс істеуімен және бөпенің салмақ қосу қарқынының баяулауымен байланысты болуы мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бұл кезеңде ұйқысыздық қалыпты жағдай, сондықтан күндіз қысқа уақыт мызғып алу Сізге күш береді. Бүгін кешке өзіңізге біраз уақыт бөліп, бөпеңізбен сөйлесіңіз: ол Сіздің мейірімге толы даусыңызды қазірдің өзінде өте жақсы таниды.') WHERE id = '152b266a-9f3e-44b6-ad2a-c45afaa30675';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Құттықтаймыз! Жүктілігіңіздің 8 айын артқа тастап, соңғы айына қадам басып келесіз. Енді бөпеңіз кез келген сәтте дүниеге келуге дайын. Бұл кезеңде бөпеңіздің бауыры мен бүйректері толыққанды жұмыс істейді, ал қан айналымы мен иммундық жүйелері қалыпты қызмет атқарады. Ол өздігінен тыныс алуға және өмірге бейімделуге үздіксіз жаттығып жатыр. Бөпеңіздің бүкіл денесі "верникс казеоза" деп аталатын ақ түсті майлы қабатпен жабылған. Бұл ерекше қабат жаңа туған және иммунитеті әлі толық қалыптаспаған бөпені микробтардан қорғайтын табиғи қалқан қызметін атқарады. Сонымен қатар бұл майлы қабат ана құрсағы мен сыртқы орта арасындағы температура айырмашылығына бейімделуді жеңілдетіп, бөпенің температуралық шок алуына жол бермейді. Бір сөзбен айтқанда, бөпеңіз осы табиғи қорғаныш кремінің арқасында сыртқы ортаның жағымсыз әсерлерінен қорғалып, дүниеге келуге дайындалып жатыр.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен жылауды жаттықтырып жүрмін бе? 😢 Кейбір ғалымдардың айтуынша, мен ана құрсағында үнсіз "жылау" қимылдарын жасаймын — иегімді дірілдетіп, тыныс алуымды өзгертемін. Бұл туғаннан кейін Сізге белгі беруім үшін маңызды. Менің жалғыз қарым-қатынас құралым жылау болады.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Мангольд'), body_changes_kk = COALESCE(body_changes_kk, 'Теріңіз өте сезімтал болуы мүмкін. Ішіңіздің терісі қатты керілгендіктен, жылтырап тұрады. Қышу мазаласа, салқын компресс қойыңыз. Сұйықтықты мол ішу теріні іштен ылғалдандырады.;;;
Қолдарыңыз бен аяқтарыңыздағы ісіну таңертең де сақталуы мүмкін. Сақина тақпаңыз. Сондай-ақ түнде қолдарыңыздың ұюы ұйқыңызды бұзуы ықтимал. Қан қысымыңызды бақылау өте маңызды.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Жамбас ауыруын азайту үшін ұйықтағанда міндетті түрде тізелеріңіздің арасына жастық қойып, сол жақ қырыңызбен жатыңыз. Ісінуді азайту үшін суды мол ішуді жалғастырыңыз, өйткені су ағзадағы артық сұйықтықтың шығарылуына көмектеседі. Осы күндері босанудың алғашқы белгілері туралы ақпаратты тағы бір рет қарап шығыңыз. Сабырлы әрі көңіліңіз тыныш болуға тырысыңыз, маңызды күнге аз қалды!') WHERE id = '225c7f32-cf83-462a-bfe6-21c45812a3e6';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіз күніне шамамен 15-20 грамм май жинап, салмақ қосуды жалғастырып жатыр. Бұл май жасушалары жеңіл болғанымен, көп орын алады және бөпеңіз үшін энергияның ең бай көзі болып саналады. Ағзада жиналған бұл майлар тек энергия беріп қана қоймайды, сонымен қатар басқа жасушалардың қорғаныш қабырғаларын қалыптастыруда, A, D, E және K дәрумендерін қанға жеткізуде және өсу үшін маңызды гормондарды өндіруде үлкен рөл атқарады. Бұл май тінінің ең маңызды міндеті — бөпеңізді суықтан және температура өзгерістерінен қорғау үшін тері астында қорғаныш қабат қалыптастыру. Сонымен бірге ішкі ағзаларды қоршаған бұл майлар бөпеңізге кез келген сәтте қажет болуы мүмкін энергия қорын қамтамасыз етеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Антиденелер жинап жатырмын! 🛡️ Сіздің қаныңыз арқылы маған берілетін иммундық жасушалардың мөлшері ең жоғары деңгейге жетті. Мен дүниеге келгенде айналадағы микробтардан мүлде қорғансыз болмаймын. Сіз ауырған және жазылып шыққан әрбір ауруға қарсы қорғаныс маған қалқан секілді беріледі.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қысқы қауын'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің соңғы кезеңдерінде жатыр мойнының жұқарып, ашыла бастауы оны жауып тұрған шырышты тығынның ағзадан шығуына әкеледі. Бұл шырышты тығын халық арасында "босану белгісі" деп аталады және оның шығуы шынайы толғақтың басталуына аз уақыт қалғанын білдіреді. Босану белгісінің түсі ашық қызыл, қызғылт, қоңыр немесе сарғыш болуы мүмкін. Оның түсіне әсер ететін бірнеше фактор бар.;;;
Шырышты тығын босануға бірнеше сағат қалғанда да, бір апта бұрын да шығуы мүмкін. Оның шығуы бірден ауруханаға бару керек дегенді білдірмейді. Алайда бұл туралы дәрігеріңізге хабарлау маңызды.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Теріңізге күтім жасаңыз. Табиғи майлармен (бадам, какао) массаж жасау терінің керілуін азайтады. Синтетикалық киім кимеңіз, мақта матадан тігілген киім ең қолайлы.') WHERE id = '58a80f20-6823-4c80-8b83-b7ba46702490';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы аптада бөпеңіздің салмағы орта есеппен 2400-2800 грамм, ал бойы 46-52 см аралығында болады; қызыл иегі қатайып, терісі барған сайын тегіс әрі жұмсақ бола түседі. Бұл кезеңде бөпеңіздің қармау рефлексі жақсы дамыған, бұл — оның жүйке жүйесінің дұрыс жұмыс істеп тұрғанының негізгі көрсеткіштерінің бірі. Қармау рефлексі әсіресе қолдары мен аяқтарында байқалады және тітіркендіргіштерге берілетін еріксіз жауап болып саналады. Құрсақта жатқанда-ақ қалыптасатын бұл қимыл туғаннан кейінгі алғашқы екі айда белсенді болады, содан кейін біртіндеп әлсіреп, орнын саналы түрде ұстау қимылына береді. Бір қызығы, аяқтардағы қармау рефлексі қолдарға қарағанда ұзағырақ сақталады және оның ерікті қимылға айналуы 6-шы айға дейін жалғасуы мүмкін.'), baby_message_kk = COALESCE(baby_message_kk, '37 АПТА! 🎉 Құттықтаймын, Anacan! Бүгін — ерекше күн. Мен енді "Шала туған" болып саналмаймын! Мен ресми түрде "Ерте мерзім" кезеңіндемін. Яғни қазір дүниеге келсем, толық жетілген бөпе болып саналамын. Салмағым 3 кг-ға жуық. Енді кез келген сәтте келе аламын! Сөмкеңіз дайын ба?'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қысқы қауын'), body_changes_kk = COALESCE(body_changes_kk, 'Маңызды кезең: Ерте мерзім! Енді босану кез келген сәтте басталуы мүмкін және бөпеңіз "мерзімінде туған" болып саналады. Дәрігеріңіз жатыр мойнының жағдайын (ашылуын, жұмсаруын) тексеруі мүмкін. Босануға дайындалу үшін жатыр мойны алға қарай жылжып, жұмсарады.'), daily_tip_kk = COALESCE(daily_tip_kk, '37 апталық осы ғажап жолдан сәтті өткеніңіз үшін өзіңізді мақтан тұтыңыз! Бүгін күшіңізді сақтау үшін барынша көбірек демалыңыз. Босануға арналған сөмкеңізді есіктің жанына қойып, барлық құжаттың түгел екеніне көз жеткізіңіз. Егер ішіңіз жүйелі түрде ауырып, ауырсыну күшейе түссе немесе қағанақ суы кетсе, дереу дәрігеріңізге хабарласыңыз. Сабырлы болыңыз, ғажайыпқа аз ғана уақыт қалды!') WHERE id = 'cca07f51-052d-4eba-bb6f-e780658e5cc2';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы аптада бөпеңіздің салмағы орта есеппен 2500-2900 грамм, ал бойы 48-52 см аралығында болады. Өкпеде тыныс алуды қамтамасыз ететін арнайы зат — сурфактанттың түзілуі аяқталғандықтан, бөпеңіз туған сәттен бастап еш көмексіз өздігінен тыныс ала алатын деңгейге жетті.;;;
Бөпеңіз өскен сайын жатырдағы орын тарылатындықтан, оның қимылдары алдыңғы апталармен салыстырғанда азаюы мүмкін, алайда олар күштірек сезіледі. Бұл жағдай 37-ші аптадан бастап қалыпты саналғанымен, ұзақ уақыт бойы қимылын сезбесеңіз, дәрігеріңізбен кеңескен жөн. Сонымен қатар бөпе өскен сайын жатырдағы қағанақ суының мөлшері де аздап төмендейді. Бұл әдетте қалыпты, бірақ су мөлшері бөпеге қауіп төндіретін деңгейге дейін азайса, дәрігеріңіз бақылау үшін Сізді ауруханаға жатқызуы мүмкін.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен жаттығып жатырмын! 🏋️‍♂️ Босану үдерісі тек Сіз үшін емес, мен үшін де үлкен еңбек. Тар босану жолынан өту үшін денемді жиырып, басымды бұрып, алға итерілуім керек. Қазір осы қимылдарды жаттықтырып жатырмын. Біз бір команда болып әрекет етеміз, Anacan. Сіз маған жол ашасыз, ал мен дүниеге келемін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қысқы қауын'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде айналысқан пилатес Сізді босануға жақсы дайындап, бұл үдерістің жеңілірек өтуіне көмектеседі. Жүктілік барысында жатырдың үлкейіп, орны өзгеруіне байланысты денеңіздің тепе-теңдік нүктесі үнемі ауысып отырады. Пилатес осы өзгерістерден туындайтын дене қалпының бұзылуын түзетіп, сымбатыңызды дұрыс ұстауға көмектеседі. Соның арқасында арқа мен белдегі ауырсыну да жеңілдейді.;;;
Сонымен қатар орындалатын пилатес жаттығулары жүктілікке сай болуы және міндетті түрде осы саладағы маманның көмегімен жасалуы керек. Кәсіби бақылаусыз қате орындалған қимылдар бөпеңізге де, өзіңізге де зиян келтіруі мүмкін екенін ұмытпаңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Босану кез келген сәтте басталуы мүмкін, сондықтан күшіңізді сақтау үшін көбірек демалыңыз. Үйден шығарда телефоныңыздың қуаты толық екеніне және ауруханаға арналған сөмкеңіздің көлікте тұрғанына көз жеткізіңіз. Егер шырышты тығын түссе немесе қағанақ суы кетсе, дереу дәрігеріңізге хабарлаңыз.') WHERE id = '9bb1bfbd-4fc9-4fdd-8462-715ca0719a8a';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы аптада бөпеңіз қынап арқылы босануға ең қолайлы қалыпқа келіп, басын төмен қаратып босану жолына түсуі мүмкін. Әсіресе бұл алғашқы жүктілігіңіз болса, оны жамбас аймағындағы ауырлықтан және жүрудің қиындауынан байқай аласыз. Бөпенің төмен түсуі Сізге біршама жеңілдік те әкеледі: кеуде қуысы мен асқазанға түсетін қысым азайып, тынысыңыз кеңиді және қыжыл сирейді.;;;
Бір қызығы, алғашқы жүктілікте бөпелер бұл қалыпқа босанудан бір ай бұрын келсе, кейінгі жүктіліктерде бұл үдеріс босануға небәрі бірнеше сағат қалғанда болуы мүмкін. Сондай-ақ осы аптада бөпеңіздің денесін жауып тұрған нәзік лануго түктері толығымен түсіп қалады. Бұл бөпеңіздің май жасушаларының арқасында дене қызуын еш көмексіз сақтай алатындай дамығанын және дүниеге келуге толық дайын екенін білдіреді.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің көлемім асқабақтай. Мен енді үлкен бөпемін. Мұнда орынның тар болғаны сонша, тебудің орнына тек керіле аламын. Сіз менің өкшемді ішіңіздің сыртынан көре аласыз. Маған қолыңызды тигізіңіз!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Асқабақ'), body_changes_kk = COALESCE(body_changes_kk, 'Ұйқы жоқтың қасы. Түнде сағат сайын ояну, дәретханаға бару, жайлы жата алмау... Осылайша денеңіз Сізді бөпеңіздің түнде оянуына дайындап жатыр. Күндіз ұйықтауға тырысыңыз. Күшіңізді сақтаңыз, ол босану кезінде қажет болады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ұйықтар алдында медитация немесе "Гипнобосану" (Hypnobirthing) аудиоларын тыңдау Сізді тыныштандырып, ұйықтап кетуге көмектесуі мүмкін. Қорқыныш денені ширықтырады, ал сабырлылық босануды жеңілдетеді.') WHERE id = '01bba5ce-c513-4ffc-af67-bbc602f0ece1';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің қаңқа жүйесі әлі толық сүйектенбеген, сондықтан өте жұмсақ әрі икемді. Осы икемділіктің арқасында босану жолынан өткен кезде бөпенің денесі оңай иіліп, еш асқынусыз дүниеге келе алады. Сонымен қатар бөпенің терісін қаптап тұратын қою «верникс казеоза» қабаты толық қалыңдады; бұл қабат бөпенің терісін қағанақ суының әсерінен қорғап, бүрісуіне жол бермейді.;;;
Бөпеңіздің денесі түгелге жуық көзге көрінбейтін түктермен және сол түктердің түбіндегі бездер бөлетін «себум» деп аталатын маймен қапталған. Себум құрамындағы кератин ақуызы тері бетінде су өткізбейтін қабат түзеді. Соның арқасында тері суда ұзақ уақыт жатса да жұмсақ күйінде қалып, бүріспейді. Алайда саусақ ұштарында, алақандар мен табандарда түк пен қалың кератин қабаты болмағандықтан, бұл аймақтар суды өткізеді; сондықтан бөпе дүниеге келген кезде дәл осы жерлерде бүрісу байқалады.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің көз жасым жоқ! 💧 Мен дүниеге келгенде қатты жылаймын («Іңгәә!»), бірақ көзімнен жас шықпайды. Көз жасы өзектерім әлі толық ашылған жоқ. Нағыз көз жасым туғаннан кейін бірнеше аптадан соң пайда болады. Ал дауыс байламдарым ше? Олар толық жұмыс істеп тұр, даусымды естисіз!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Асқабақ'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің соңғы апталарында қайта пайда болатын жүрек айну, құсу және тәбеттің төмендеуі салдарынан қыжыл мазалауы мүмкін. Асқазаныңыз жатырдың қысымында болғандықтан, аз-аздан әрі жиі тамақтану, порцияларды кішірейту және тамақпен бірге сұйықтық ішпеу бұл мәселені жеңілдетеді. Сонымен қатар тамақтанғаннан кейін бірден жатпаңыз, ұйықтамаңыз және қимылсыз қалмауға тырысыңыз. Астың қорытылуына көмектесу үшін қысқа әрі баяу серуендеуге болады. Әсіресе жүктіліктің соңғы кезеңінде артық салмақ қосу да қыжылға себеп болатын факторлардың бірі. Сондықтан бір рет тамақтанғанда калориясы тым жоғары тағамдарды көп тұтынбауға тырысыңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, '«Шырышты тығын» түскен кезде қорықпаңыз. Бұл — қалыпты үдеріс. Алайда қан кету етеккір кезіндегідей көп әрі түсі ашық қызыл болса, дереу ауруханаға барыңыз.') WHERE id = '9cfe44a2-80b6-4626-b317-1135744027c8';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, '40 аптаның аяқталуына әлі уақыт бар деп ойлауыңыз мүмкін, алайда жүктіліктердің шамамен 80%-ы 39-аптаға дейін аяқталатынын ұмытпаңыз. Дені сау әрі қалыпты жүктілік кезінде бөпе толық жетілгендіктен, босану 37-апта мен 42-апта аралығында кез келген уақытта басталуы мүмкін. Бөпеңіз толығымен жетілді, енді онымен қауышуыңызға санаулы уақыт қалды.;;;
Алғашқы апталарда бөпенің салмағы небәрі 1-2 грамм қосылса, соңғы кезеңде май жасушаларының түзілуіне байланысты бұл көрсеткіш аптасына орта есеппен жарты килограмға дейін артады. Босануға осыншама аз уақыт қалғанда бөпенің тез салмақ қосуы оның сыртқы ортаға бейімделуі және дене температурасын өздігінен сақтай алуы үшін маңызды. Дегенмен әр бөпенің салмақ қосу жылдамдығы жынысына, генетикасына және қоршаған орта факторларына байланысты әртүрлі болуы мүмкін екенін де ескеру қажет.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен төмен қарап жатырмын! ⬇️ Басым жамбас сүйектерінің арасына толық орнықты. Мен «старт» қалпындамын. Бұл қалып маған сәл жайсыз, бірақ босану жолына кіру үшін ең қолайлы бұрыш осы. Мен Сізбен кездесуге дайынмын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Асқабақ'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде жоғарылайтын прогестерон мен эстроген гормондарының деңгейі жүктіліктің соңғы айларында айтарлықтай артады. Соның салдарынан мұрныңыз бітелуі мүмкін.;;;
Мұрын бітелуіне байланысты ауыздың құрғауы, жөтелгіңіз келу, бас ауруы және ұйқысыздық пайда болуы мүмкін. Сонымен қатар мұрынмен тыныс алу қиындағанда, мұрынның шырышты қабығы зиянды микроорганизмдерді ұстап қала алмайды, сол себепті ағзаңыздың ауруларға қарсы тұру қабілеті төмендеуі ықтимал.;;;
Толғақ басталған кезде оны жеңілдету үшін дұрыс тыныс алу өте маңызды. Бас ауруы, жөтел және ұйқысыздық дұрыс тыныс алуға кедергі келтіріп, бұл үдерісті қиындатуы мүмкін. Сондықтан тыныс алу жаттығуларын жүйелі түрде жасап, таза ауада қысқа серуендеп, сол қырыңызбен жатқан пайдалы.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Дәретханаға бару үшін түнде сирек ояну мақсатында ұйықтар алдында сұйықтықты аз ішіңіз. Жатын бөлменің қараңғы әрі салқын болуына мән беріңіз.') WHERE id = 'f767f4b5-3cd7-4998-b9f7-8ee66f29236d';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы аптадан бастап бөпеңіздің лимфа жүйесі айтарлықтай дамыған деңгейге жетті. Бөпеңіздің лимфа жүйесі лимфа тамырлары мен лимфа түйіндерінен тұрады. Лимфа жүйесінің мүшелеріне лимфа түйіндері, бадамша бездер, шырышты қабық ішіндегі түйіншектер және көкбауыр жатады. Лимфа жүйесінің негізгі қызметі — лимфа сұйықтығының бүкіл денеде айналуын қамтамасыз ету. Лимфа — құрамында ақ қан жасушалары (лейкоциттер) көп болатын және бүкіл ағзада инфекциялармен күресуге көмектесетін аса маңызды сұйықтық.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен кішкентай қарбызбын! Мұндағы орынның тар болғаны сонша, қозғалу үшін шынтағыммен Сізден жол ашып аламын. Кейде Сізге ауыр тиетінін білемін, бірақ мен де мұнда қысылып жатырмын!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Кішкентай қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің осы кезеңінде тәбетіңіз едәуір артуы мүмкін. Сондықтан соңғы кезеңде салмақтың тез өсуіне назар аударып, оны белгілі бір деңгейде ұстауыңыз қажет. Жүктіліктің соңғы апталарында аптасына 250-500 грамм салмақ қосу қалыпты саналады. Егер теңгерімді әрі жүйелі тамақтануды жалғастырсаңыз, салмақ қосу үдерісі де қалыпты өтеді. Сонымен қатар бөпеңіздің дамуы және орташа көрсеткіштен ірі болуы да салмағыңыздың артуына ықпал етуі мүмкін. Жүктілік кезінде қосылған салмақтың барлығы Сіздің нақты дене салмағыңызды білдірмейді. Қосылған салмақтың шамамен 3000-3500 грамы бөпеге, 800 грамы плацентаға, 700 грамы қағанақ суына, 800 грамы жатырдың ұлғаюына тиесілі, ал шамамен 5000 грамы ағзаңызда жиналған май мен ісінуден тұрады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бұл кезеңде босану кез келген сәтте басталуы мүмкін, сондықтан күшіңізді үнемдеңіз. Егер беліңізден ішіңізге қарай таралып, біртіндеп күшейетін ауырсынуды сезсеңіз, уақытын белгілей бастаңыз. Аяқтарыңыздағы ісінуді азайту үшін суды молынан ішуді жалғастырып, аяқтарыңызды жоғары көтеріп демалыңыз. Бүгін өзіңізді қатты шаршатпаңыз, тек жаныңызға тыныштық сыйлайтын істермен айналысыңыз.') WHERE id = '5ba8c0c5-91c9-4151-91cf-d3f16e08e88d';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің қан айналымы жүйесіндегі тромбоциттер мен лейкоциттер саны оңтайлы деңгейге жетті. Тромбоциттер қанның ұюын қамтамасыз етуде маңызды рөл атқарады. Олардың орташа өмір сүру ұзақтығы 10 күн, ал қызметін аяқтағаннан кейін көкбауырда немесе бауырда ыдырап, ағзадан шығарылады. Тромбоциттер қанның ұюын қамтамасыз ететіндіктен, қан жоғалған жағдайда тиімді ұю үдерісін қалыптастыру үшін олардың саны артады. Ал бөпеңіздің қан айналымы жүйесіндегі лейкоциттер антиденелер түзіп, ағзаны қорғауға белсенді қатысады. Бөліну қабілеті болмағандықтан өздігінен жаңармайтын лейкоциттер бөпеңіздің сүйек кемігі мен лимфа түйіндерінде түзіледі.;;;
Инфекция кезінде олардың саны едәуір артады, ал бөпеңіздің иммундық жүйесі дамыған сайын бұл көрсеткіш бүкіл өміріндегі ең жоғары деңгейге жетеді. Иммундық жүйенің зиянды микроағзаларға реакциясына қарай олардың өмір сүру ұзақтығы бірнеше сағат немесе бірнеше күн болуы мүмкін. Қызметін аяқтағаннан кейін олар бөпеңіздің көкбауыры мен бауырында ыдырайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен ықылық атып жатырмын! 🤭 Қазір менің ықылығым күшейе түсті. Сіз бүкіл ішіңіздің бүлкілдегенін сезесіз. Бұл менің көкетті бұлшықетімнің әлі де жаттығып жатқанын білдіреді. Мен тыныс алуға дайындалып жатырмын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Кішкентай қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік бойы сапалы ұйқы Сіз үшін де, бөпеңіз үшін де өте маңызды. Жеткілікті ұйықтау өзіңізді сергек сезінуге көмектесіп қана қоймай, босану кезінде де пайдасын тигізеді.;;;
Ұйқысыздыққа әсер ететін себептердің бірі — түнде қандағы қант деңгейінің төмендеуі. Бұл жағдай қатты бас ауыруы мен дененің терлеуіне әкелуі мүмкін. Ұйықтар алдында ішкен жылы сүт бұл мәселені жеңілдетуге көмектеседі. Көбіне түнде пайда болатын қыжыл да ұйқысыздықты қоздыратын себептердің бірі. Оның ең басты себебі — тамақтанғаннан кейін бірден жату. Әсіресе кешкі астан кейін кемінде 2 сағат бойы тік қалыпта болып, жатпау және ұйықтамау керек.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қан қысымыңызды таңертең және кешке өлшеңіз. Егер ол 140/90-нан жоғары болса, дәрігеріңізге хабарлаңыз. Ісінуді азайту үшін тұзды тағамдардан толықтай бас тартыңыз.') WHERE id = 'c2434362-3321-422e-8c43-c14fba4ebb39';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бұл кезеңде бөпеңіздің бас шеңбері 32 см мен 37 см аралығында болады. Бас шеңберінің осы аралықта болуы миының қалыпты дамып жатқанын көрсетеді. Бас шеңберінің өсуі бөпеңіздің миының дамуы үшін өте маңызды. Бұл көрсеткіштің қалыпты деңгейден төмен немесе орташа мәннен жоғары болуы мидың дамуына кері әсер етуі мүмкін. Сондықтан ай сайынғы тексерулер кезінде бас шеңберін өлшеп, көрсеткіштерін бақылау қажет. Алғашқы алты айда жоспарлы тексерулермен бірге бас шеңберін ай сайын міндетті түрде өлшеген жөн. Бөпеңіздің салмағы мен бойын өлшеу жалпы денсаулығы туралы ақпарат берсе, бас шеңбері ми қызметін бағалауға мүмкіндік беретіндіктен өте маңызды. Өйткені ми қызметі бұзылған жағдайда бас шеңберінің өлшемі қалыпты көрсеткіштерден ауытқуы мүмкін.;;;
Қарқынды дамып келе жатқан бөпеңіздің миы туғаннан кейінгі алғашқы жыл ішінде 88% өседі, ал үйренген дағдыларының арқасында ми жасушалары арасында қалыптасатын жаңа байланыстар үздіксіз көбейе береді.'), baby_message_kk = COALESCE(baby_message_kk, 'Дәрігерлер 38-42 апта аралығы босанудың қалыпты мерзімі екенін айтады. Демек, мен кез келген сәтте дүниеге келуім мүмкін. Маған қандай ат қоятыныңызды ойладыңыз ба, Anacan? Мен келе жатырмын ғой!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Кішкентай қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Осы аптадағы дәрігер тексеруінде кесарь тілігін қажет ететін мәселе болмаса, жамбасыңыз тексеріледі. Жамбас тексеруі жамбас сүйектеріңіздің табиғи босануға сай келетінін анықтау үшін жүргізіледі.;;;
Бұл тексеру босану басталғанға дейін, 36-38-ші апталар аралығында жүргізіліп, табиғи жолмен босану мүмкіндігі нақтыланады. Егер босану кесарь тілігі арқылы өтетін болса, жамбасты тексерудің қажеті жоқ. Плацента босану жолын жауып тұрған жағдайда, преэклампсия кезінде және егіз немесе үшем секілді көпұрықты жүктілікте жамбастың сәйкестігін тексеру қажет болмайды.;;;
Бұл процедура ең алдымен босану тәсілін анықтау, бөпеңіздің босану жолына түскен-түспегенін және оның орналасуын бағалау, қынапта инфекцияның бар-жоғын тексеру, сондай-ақ жатыр мойнының ашылу және жұмсару дәрежесін анықтау мақсатында жүргізіледі.;;;
Егер дәрігер жамбасыңыздың тар екенін анықтаса, оның тарылу дәрежесі мен бөпеңіздің салмағына қарай кесарь тілігін жасайтын күнді белгілейді. Жамбастың тар болуы бөпеңіз өтетін босану жолының жеткіліксіз кең болуына байланысты оның өте алмауына және босану кезінде кейбір асқынулардың туындауына әкелуі мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Толғақ басталғанда "5-1-1" қағидасын есте сақтаңыз: толғақ әр 5 минут сайын басталып, 1 минутқа созылса және бұл жағдай 1 сағат бойы жалғасса, ауруханаға барыңыз.') WHERE id = '4a0b4b38-f357-4956-99dd-b078f66f4393';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің денсаулығын қорғайтын ең маңызды қалқан — оның иммундық жүйесі. Бұл жүйе зиянды микроағзаларға қарсы үш кезеңнен тұратын мінсіз қорғаныс шебін құрады:;;;
Бірінші қорғаныс шебі (Шекаралық бақылау): Микробтардың ағзаға енуіне жол бермейтін физикалық тосқауылдар. Оларға тері, мұрын мен ауыздың шырышты қабықтары, сондай-ақ көз жасы мен сілекей құрамындағы арнайы ферменттер жатады.;;;
Екінші қорғаныс шебі (Жылдам әрекет): Егер микроб ағзаға еніп кетсе, дене бірден микробтарға қарсы ақуыздар түзіп, дене қызуын көтереді немесе қабыну реакциясын туғызып, бөгде қоздырғышты жоюға тырысады.;;;
Үшінші қорғаныс шебі (Арнайы жасақ): Алғашқы екі шептен өткен микробтарға қарсы ағза арнайы "қарулар" — лимфоциттер мен антиденелер түзеді. Бұл кезеңде иммундық жүйе жауды танып, дәл сол түрге қарсы күреседі.;;;
Алғашқы екі қорғаныс шебі барлық бөгде заттарға бірдей жауап берсе, үшінші шеп әр ауру түріне өзіндік тәсілмен қарсы әрекет етеді. Осы жүйенің арқасында бөпеңіздің ағзасы кез келген қауіпке қарсы тұруға дайын болады.'), baby_message_kk = COALESCE(baby_message_kk, 'Ішім пысты! 🏠 Мұнда өте тар. Қозғалғым келеді, бірақ орын жоқ. Сіз менің қимылдарым азайды деп ойлауыңыз мүмкін, алайда мұқият болыңыз: қимылдың сипаты өзгергенімен (тебудің орнына сырғу), саны азаймауы керек. Мен күн сайын сергек болып, қимылдауым керек.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Кішкентай қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Сіз жүктіліктің соңғы триместрінің соңғы күндерін өткеріп жатырсыз. Артта қалған қиын 9 айдан жиналған шаршаудың салдарынан өзіңізді өте әлсіз сезінуіңіз мүмкін.;;;
Жүктілік кезінде ағзаңыздағы гормондар деңгейі айтарлықтай өзгереді. Денеңіз бөпеңізге оңтайлы жағдай жасау үшін 50% көбірек қан өндіреді, жүрек соғысыңыз жиілейді, қандағы қант деңгейі төмендейді және зат алмасуыңыз көбірек энергия жұмсайды. Осы себептер әсіресе соңғы кезеңде қатты әлсіреуіңізге әкеледі. Сонымен қатар босанудың жақындауына байланысты қорқыныш психологиялық күйіңізге әсер етуі мүмкін. Сұйықтықты жеткілікті мөлшерде ішпеу әлсіздікті одан әрі күшейтеді. Сондықтан күніне кемінде 2 литр су ішіп, ұзақ уақыт сусыз қалмауға тырысыңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Күні бойы бөпеңіздің қимылдарын санауды жалғастырыңыз. Қимылын сезбесеңіз, тәтті нәрсе жеп, сол жақ қырыңызбен жатыңыз. Ешқандай реакция болмаса, дереу дәрігерге барыңыз.') WHERE id = 'f9044cd4-84b9-4a00-86de-1671dcaabd83';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Жүктіліктің басында салмағы шамамен 60 qram, көлемі теннис добындай болған жатырыңыз осы кезеңде 1500 qram-ға дейін ұлғайып, футбол добындай көлемге жетті. Әйел ағзасындағы ең күшті мүше саналатын жатыр әртүрлі бағытта созылатын көптеген бұлшықет тіндерінен тұрады. Ол сыртқы бетінен ішкі бетіне қарай қабықты қабаттан, бұлшықет қабатынан және бөпеңіз дамитын ішкі қабаттан тұратын үш қабатты құрылым. Жатыр тініндегі қалың бұлшықет қабаты бөпеңіздің өсуіне мүмкіндік беру үшін босаңсып, созылу арқылы ішкі көлемін ұлғайтады. Жатырдың осылай өсуін қолдау үшін ағзаңыздың жұмыс істеу механизмі толығымен өзгеріп, бұл өзгеріс барлық мүшелеріңізге әсер етеді. Осы кезеңде күшті жатыр бұлшықеттері мен жатырдың жалпы салмағы 1500 qram-ға жетіп, оның ішкі көлемі 5 kilodan астам жүкті көтере алатындай ұлғаяды. Осы аптада жатырыңыздың өз салмағы 1500 qram, бөпеңіздің салмағы орта есеппен 3500 qram, плацентаның салмағы 1000 qram және амнион сұйықтығының салмағы 1200 qram болады, яғни ағзаңыз орта есеппен 7 kilodan астам жүкті көтеріп жүр.'), baby_message_kk = COALESCE(baby_message_kk, 'Жүрегім Сізбен байланысты! ❤️ Менің қан айналымым әлі де Сіздің плацентаңыз арқылы реттеледі. Дүниеге келгенде кіндік кесілген сәттен бастап жүрек-қантамыр жүйем өздігінен жұмыс істей бастайды. Жүрегімдегі кейбір саңылаулар жабылып, қан өкпеме барады. Бұл — таңғажайып өзгеріс.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Кішкентай қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің әсерінен бөпеңіз жатқан жатыр ұлғайып, денеңіздің ауырлық орталығын өзгертетіндіктен, қынап, бел және іштің төменгі бөлігінде ауырсыну пайда болуы мүмкін.;;;
Сонымен қатар босануға бірнеше күн қалғанда жатыр мойнының ашыла бастауы да қынап аймағында ауырсыну туғызуы мүмкін. Ашылуға байланысты бұл ауырсыну кейде өте қатты болып, толғақ тәрізді сезілуі ықтимал.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Босану кезінде қолданатын тыныс алу тәсілдерін жаттықтырыңыз. Терең тыныс алу — толғақ кезіндегі ауырсынуды басқарудың ең тиімді жолы.') WHERE id = '5df96ea7-65a1-4678-8453-5c3a6e6b2deb';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Жатырдағы орынның едәуір тарылуына байланысты бөпеңіздің өсу қарқыны біршама баяулады. Осы кезеңде бөпеңіз күніне орта есеппен 15 qram салмақ қосады. Бөпеңіз босану кезінде жатыр мойнынан өтіп, дүниеге келеді. Сондықтан осы аймақтағы бұлшықеттерді нығайту босанудың жеңілірек өтуіне және босану кезінде қандай да бір асқынудың пайда болу қаупін азайтуға көмектеседі. Жамбас түбінің бұлшықеттері — жатырды, қынапты, қуықты және ішектің соңғы бөлігі болып саналатын тік ішекті толық қоршап, ұстап тұратын бұлшықеттер тобы.;;;
Жүктілік кезінде жамбас бұлшықеттерінің мықты болуы өте маңызды. Бөпеңіз өсіп, дамитын құрылым дәл осы жамбас бұлшықеттері тобының ішінде орналасқан. Сондай-ақ бөпеңіз дүниеге келерде осы жерден өтеді.;;;
Босану кезінде жамбас бұлшықеттері бөпеңізді төмен қарай жылжыту үшін барынша күшеніп, итеру әрекетін жасайды. Жатырдың әрбір жиырылуы орта есеппен 25 kilo қысым тудырады. Бұл қысым бөпеңізді босану кезінде сыртқа итеру үшін қанша күш жұмсалатынын көрсетеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен бәрін естимін! 👂 Қазір құлағымның есту қабілеті соншалықты жақсы дамыған, тіпті Сіздің жүрек соғысыңызды, асқазаныңыздың дыбысын және сырттағы әңгімелерді де естимін. Дүниеге келгенде ауруханадағы дыбыстар маған бейтаныс болып көрінеді, сондықтан мені құшағыңызға алып, сөйлессеңіз, тынышталамын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Кішкентай қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Гормондар қынап микрофлорасының өзгеруіне себеп болатындықтан, бактериялардың бақылаусыз көбеюіне қолайлы жағдай туындауы мүмкін. Іштің үлкеюіне байланысты жеке гигиенаны толық сақтаудың қиындауы да бұған әсер етеді. Қынап арқылы ағзаға еніп, инфекция туғызатын бактериялар несеп ағуы бөгеліп, жиналып қалған жерлерде өте жылдам көбейеді. Емделуі айтарлықтай жеңіл болғанымен, бұл инфекцияларға салғырт қараса, босану кезінде кейбір мәселелер туындауы мүмкін. Сондықтан оларды елеусіз қалдырмау керек.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Серіктесіңізден беліңізге массаж жасап беруін өтініңіз. Бел аймағын теннис добымен уқалау толғақ кезінде айтарлықтай жеңілдік береді.') WHERE id = '7cd91bfd-2c65-4ec8-b473-970178378a3f';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Иммундық жүйенің бейспецификалық бөлігі қалыптасып қойғанымен, бөпеңіз өз антиденелерін әлі өндіре алмайтындықтан, иммунитеттің спецификалық бөлігі әлі толық дамымаған.;;;
Иммундық жүйенің бейспецификалық бөлігі — ағзаға енген зиянды заттарды ажыратпай, оларға қарсы әрекет ететін бөлік. Ол инфекция туғызуы мүмкін заттардың ағзаға ауыз, мұрын, көз және тері арқылы енуіне осы мүшелер мен олар бөлетін секрециялардың кедергі жасауынан қалыптасады.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Дәрігер жүргізетін жамбас тексеруі жатыр мойнын қоздыратындықтан, босанудың басталуына түрткі болуы мүмкін. Сондықтан бұл тексеруді 36-шы аптадан кейін жүргізген дұрыс.;;;
Жамбас тексеруі екі түрлі әдіспен — қолмен немесе айна деп аталатын арнайы құралмен жүргізілуі мүмкін. Бұл тексеру кезінде жамбас сүйектеріңіздің жағдайы бағаланады. Жамбас тексеруінің мақсаты — бөпеңіздің басы мен ол өтетін босану жолының бір-біріне сәйкестігін анықтау.;;;
Жамбасты қолмен тексеру кезінде Сізден гинекологиялық креслоға отыру сұралады, содан кейін дәрігер екі саусағымен жатыр мойнының ашылу деңгейі мен сүйектеріңіздің жағдайын тексереді.;;;
Айнамен тексеру кезінде бұл құрал қынапқа енгізіліп, оның қабырғаларын ашуға мүмкіндік береді. Айна енгізілгеннен кейін дәрігер жатыр мойны мен жамбастың сәйкестігін бағалап, босану тәсілін анықтайды.;;;
Егер осы тексерудің нәтижесінде жамбас сүйектеріңіздің ені жеткілікті деп бағаланса, табиғи жолмен босануға кедергі болмайды. Ал жамбас сүйектерінің тарлығы анықталса, оның дәрежесіне қарай дәрігеріңіз Сізбен бірге босану тәсілін таңдайды.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Үйде жалғыз қалмауға тырысыңыз. Босану басталған жағдайда жаныңызда көмектесетін және ауруханаға апаратын адамның болуы маңызды. Сабыр сақтаңыз, көптен күткен кездесуге аз ғана уақыт қалды!') WHERE id = 'e4196ad3-1e48-4295-82c8-6c810ea2f084';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің барлық тіндері, ағзалары мен жүйелері функционалдық тұрғыдан дамып болғанымен, өкпесі дүниеге келетін күнге дейін жетілуін жалғастырады. Жүктіліктің 24-аптасынан бастап өкпе тыныс алуды қолдайтын құрылғылардың көмегімен жұмыс істей алатындай деңгейде дамиды. Алайда сурфактант жеткілікті мөлшерде толық өндірілмейтін жүктіліктің 38-аптасына дейін тыныс алуда кейбір қиындықтар туындауы мүмкін. Жалпы, тыныс алу жүйесі толық жетілді деу үшін бөпе 2 жасқа толуы керек, өйткені өкпе осы уақытқа дейін дамуын жалғастырады.;;;
Бөпеңіздің дүниеге келген сәтте алатын алғашқы демі — оның өміріндегі ең қиын дем. Плацента арқылы оттегі келуінің тоқтауы және терінің оттегімен жанасуы жүйке жүйесі арқылы тыныс алу жүйесін іске қосады. Бөпеңіз жұтқан алғашқы ауа альвеолаларға енбес бұрын, өкпедегі сұйықтық тыныс жолдарынан шығарылуы керек. Сондықтан бөпеңіз алғаш дем алғанда өкпесіндегі ауа қапшықтары бірден толықтай ауаға толмайды. Екінші рет дем алған кезде өкпе тыныс алу қызметін атқара бастайды. Кейінгі тыныс алу барысында өкпесі кеңейіп, альвеолалардың бетіне сурфактант таралады. Бұл зат альвеолалардың бетін тыныс алуға қажетті күйге келтіріп, қапшықтардың бір-біріне жабысып қалуына жол бермейді. Осылайша бөпеңіздің өкпесі толық жұмыс істей бастайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Шыдамдылығыңыз үшін рақмет! 🙏 Қатты шаршағаныңызды білемін. Бүкіл денеңіз ауырып, ұйықтай алмай жүрсіз. Бірақ осы соңғы күндер мен үшін өте маңызды. Миым мен жүйке жүйем соңғы рет қалыптасып, реттеліп жатыр. Сіз маған әлемдегі ең қауіпсіз үйді сыйладыңыз. Енді сыртқа шығатын уақыт келді.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, '🍉 Менің көлемім үлкен қарбыздай! Дәрігерлер 39-апта босану үшін ең қолайлы уақыт дейді. Миым, өкпем, бауырым — бәрі толық дайын. Енді сылтауым жоқ, есіктің ашылуын ғана күтіп отырмын!'), daily_tip_kk = COALESCE(daily_tip_kk, 'Сабырлы болыңыз. «Қашан босанасыз?» деген сұрақтарға жауап беру шаршатуы мүмкін. Телефоныңызды дыбыссыз режимге қойып, тек өзіңізге және бөпеңізге көңіл бөліңіз.') WHERE id = '37c59540-1af3-42e8-95c8-2c53b72f2a9f';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы аптада бөпеңіз жатырыңыздағы бүкіл кеңістікті толық алып жатыр. Соның салдарынан оның қимылдарының азайғанын сезінуіңіз қалыпты жағдай. Тар кеңістікте жатқан бөпеңіз жатыр ішінде өзіне барынша орын босату үшін аяқтарын айқастырып, денесіне қарай тартып, қолдарын кеудесіне жинайды. Жатырда қозғалатын орын қалмағандықтан, осы кезеңде оның ең кішкентай қимылының өзі Сізге ауырсыну сезімін тудыруы мүмкін. Босануға дайындалып жатқан бөпеңіз басын босану жолына орналастырған. Егер бұл алғашқы жүктілігіңіз болмаса, бөпеңіздің басы босануға қажетті қалыпқа әлі түспеген болуы мүмкін. Бөпеңіз босану қалпына келіп, босану жолына түскенде жатырдың асқазан мен диафрагмаға түсіретін қысымы азаяды. Қысымның төмендеуіне байланысты қыжыл мен тыныс алу қиындығы едәуір жеңілдейді. Алайда қуыққа түсетін қысым бұрынғыдан да күшейгендіктен, дәретханаға жиі барғыңыз келуі мүмкін.'), baby_message_kk = COALESCE(baby_message_kk, 'Беттерім томпайып келеді! 🐹 Қазір бетім бұрынғыдан да толық әрі домалақ. Ему бұлшықеттерімнің күшті болғаны сонша, беттерімде май жастықшалары пайда болды. Олар маған Сіздің сүтіңізді емуге көмектеседі. Мені көргенде сол томпақ беттерімді қысып көргіңіз келеді!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің соңғы кезеңінде гормондық өзгерістерге байланысты көңіл күйіңіз кенет құбылуы мүмкін. Ал босанудан қорқу сияқты себептерден депрессиялық күй туындауы ықтимал.;;;
Осындай қиындықтар кезінде ағзаңыз бөлетін кортизол мен адреналин гормондары қан арқылы плацентадан тікелей бөпеңізге өтеді. Осы гормондардың жоғары мөлшерінің әсеріне ұшыраған бөпеде кейінгі өмірінде зейіннің шашырауы, тілдік дағдылардың әлсіздігі, жаңа жағдайларға бейімделе алмау және депрессиялық бұзылыстар сияқты қиындықтар пайда болуы мүмкін.;;;
Сонымен қатар жүктілік кезіндегі күйзеліс психологиялық әсерлермен бірге физиологиялық салдарға да әкелуі мүмкін. Ұйқысыздықтың күшеюі, ширығу және босанғаннан кейін сүттің шықпауы гормондарыңызбен тікелей байланысты.;;;
Егер шамадан тыс күйзеліске ұшырадым деп ойласаңыз, маманның көмегіне жүгінгеніңіз жөн.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Осы күндері ұйқысыздықтың болуы қалыпты, сондықтан мүмкіндік болған сайын күндіз демалыңыз. «Тығынның» (шырышты тығынның) түсуі немесе қағанақ суының ағуы сияқты белгілерге назар аударыңыз. Күш-қуатыңызды сақтау үшін жеңіл әрі тез қорытылатын тағамдарды таңдаңыз. Перзентханаға арналған сөмкеңіздің толық жиналып, қолжетімді жерде тұрғанына соңғы рет көз жеткізіңіз. Сабыр сақтаңыз, бәрі жоспар бойынша өтіп жатыр!') WHERE id = '89f0050d-f633-47d8-92b8-7c424334510d';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіз үлкен кездесуге соңғы дайындығын аяқтап жатыр. Осы кезеңде ол басын төмен қаратып, жамбас қуысына толық қысым түсіре бастайды. Бұл қысым жай ғана физикалық салмақ емес, босанудың басталуына қажетті табиғи қозғаушы күш.;;;
Бөпе басының төмен қарай қысым түсіруі жатыр мойнына механикалық әсер етіп, оның жұмсаруына және біртіндеп ашылуына көмектеседі. Бұл үдеріс ағзаңызда окситоцин гормонының бөлінуін ынталандырып, жатырды толғаққа дайындайды. Бөпеңіз әбден өсіп, жатыр ішіндегі орын тарылғандықтан, оның «акробатикалық» қимылдары шектеледі. Алайда қимылдарының сипаты өзгерсе де (мысалы, қатты тебудің орнына үйкелу немесе керілу жиірек сезіледі), олар міндетті түрде тұрақты сезіліп тұруы керек екенін ұмытпаңыз. Бөпенің қимылдауы — оның жағдайы жақсы әрі жеткілікті оттегі алып жатқанының ең қарапайым көрсеткіші. Егер қимылдары кенет азайса немесе ұзақ уақыт бойы мүлде сезілмесе, дереу дәрігеріңізбен кеңесу маңызды.'), baby_message_kk = COALESCE(baby_message_kk, 'Қағанақ суым кетуі мүмкін! 💧 Мен қимылдағанда немесе басыммен қысым түсіргенде қағанақ қабы жарылуы мүмкін. Кейде су «сарқырап» ағады, ал кейде жай ғана «тамшылап» шығады. Егер суыңыз кетсе, кездесуімізге санаулы сағат қалды деген сөз! Қорықпаңыз, бұл ауыртпайды.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Босану толғағы бел мен шап аймағында сезіліп, бастапқыда етеккір кезіндегі ауырсынуға ұқсайды. Бракстон Хикс деп аталатын жалған толғақпен салыстырғанда, нағыз толғақ біршама тұрақты болады. Демалғанда басылмайды, біртіндеп үдейді, жиілігі мен күші артып, ұзағырақ созыла бастайды.;;;
Халық арасында «іштің төмен түсуі» деп аталатын белгі бөпеңіздің жамбас қуысына түскенін білдіреді. Әсіресе алғаш рет жүкті болған әйелдер босануға бірнеше апта қалғанда жеңілдеп, еркін тыныстай бастағанын сезеді. Бөпеңіздің басы босану жолына түскенде тыныс алуыңыз жеңілдеп, қабырғаларыңызға түсетін қысымның азайғанын байқайсыз.;;;
Бөпеңіз жатқан қағанақ қабы жарылып, суыңыз кеткен жағдайда толғақты күтпей-ақ дәрігеріңізге хабарласуыңыз керек. Мұндай кезде бөпеңіз инфекциялардан қорғансыз қалатындықтан, Сіз дәрігерлердің бақылауында болуыңыз қажет.;;;
Қағанақ суының кетуі — босанудың басталғанын білдіретін нақты белгі. Мұны байқамай қалу мүмкін емес дерлік. Бұл — үздіксіз немесе қысқа аралықпен қайталанып, аяғыңызды сулайтындай мөлшерде еріксіз ағатын мол сұйықтық. Әдетте бірнеше сағат ішінде толғақ та басталады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Жүктіліктің 39 апталық ұзақ жолынан сәтті өткенііңіз үшін бүгін кешке өзіңізге тыныш жағдай жасаңыз. Босанудың негізгі 3 белгісін есте сақтаңыз: тұрақты әрі күшейе түсетін толғақ, қағанақ суының кетуі немесе шырышты тығынның түсуі. Осылардың кез келгені байқалса, дәрігеріңізге хабарласыңыз. Күш-қуатыңызды сақтап, бәрі ойдағыдай өтетініне сеніңіз.-') WHERE id = '46262d69-53e1-4e37-8004-ee9b3e95fbbb';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіз дүниеге келуге толық дайын «кішкентай қаһарманға» айналды. Оның сүйектерінің басым бөлігі (бас сүйектерінен басқа) толықтай қатайып, нығайды.;;;
Ал бас сүйектерінің әлі де жұмсақ әрі қозғалмалы болуы — табиғаттың бір кереметі; мұндай икемділік бөпеңіздің босану жолынан жеңіл әрі қауіпсіз өтуіне көмектеседі. Бөпеңіздің тырнақтары саусақ ұшынан асып кететіндей өсті, тіпті кейбір бөпелер айтарлықтай ұзын әрі қалың шашпен дүниеге келеді.;;;
Ең бастысы, бөпеңіздің ішкі «сағаты» — гормондық жүйесі «босану белгісін» беруге толық дайын. Бөпенің миы мен бүйрекүсті бездері арнайы гормондар бөліп, денеңізге босанатын уақыттың келгенін хабарлайды. Осы гормондық диалог жатыр бұлшықеттерін іске қосып, Сіз бен бөпеңіздің көптен күткен кездесуін бастайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен ресми түрде дайынмын. Осы апта — менің дүниеге келетін уақытым. Бәлкім бүгін, бәлкім ертең... Бірақ көп күттірмеймін деп уәде беремін. Мен де сені көргім келеді!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде дұрыс тамақтану бөпеңіздің зияткерлік дамуын қолдап, оның бойындағы даму әлеуетін толық жүзеге асыруына жағдай жасайды. Жүктілік бойы көкөністер мен жемістерден алынатын дәрумендерді, жануар текті өнімдердегі ақуыздарды, пайдалы майларды, сүт пен сүт өнімдерін, дәнді дақылдарды және басқа да тағам түрлерін жеткілікті мөлшерде әрі жүйелі түрде тұтынуыңыз қажет.;;;
Бөпеңіз бен өз денсаулығыңыз үшін ақуызға бай тағамдарды тұтыну маңызды. Мәзіріңізге көмірсуларға бай көкөністер мен жемістерді, ал темірге деген қажеттілікті өтеу үшін жұмыртқа, ет және қою жасыл жапырақты көкөністерді қосыңыз. Сонымен қатар A, C және D дәрумендері бар тағамдарды тұтынып, жеткілікті су ішу жүктілікті дені сау әрі теңгерімді өткізуге көмектеседі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Осы күндері мазасыздықты басқару үшін тыныс алу жаттығуларын жасаңыз. Босанудың басталуын жылдамдату үшін (дәрігеріңіз қарсы болмаса) үй ішінде баяу жүріп серуендеңіз. Бөпелердің тек 5%-ы дәл белгіленген күні дүниеге келетінін ұмытпаңыз, сондықтан босану бірнеше күнге кешіксе, алаңдамаңыз. Телефоныңыз бен сөмкеңіз кез келген сәтке дайын екеніне көз жеткізіңіз.') WHERE id = 'c09d4d91-1d82-48b0-8145-2433217890b4';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ішегі дүниеге келген сәтке дейін толықтай стерильді болады. Осы кезеңде ішек флорасы өзіне тән 500-ден астам бактерия түрін қабылдауға дайындалады. Бөпеңіздің аш және тоқ ішегінде орналасатын бұл орта микрофлора деп аталады, иммундық жүйе жасушаларының шамамен %70-і дәл осы жерде орналасады.;;;
Босанғанға дейін стерильді болатын ішектегі флораның дамуы бөпеңіздің дүниеге келу жолына, генетикалық ерекшеліктеріне, қоршаған ортамен байланысына және тамақтану тәсіліне қарай қалыптасады. Бөпеңіз табиғи жолмен дүниеге келсе, 4-ші күні, ал кесарь тілігі арқылы дүниеге келсе, 7-ші күні ішегінде тағамды қорытуға көмектесетін кейбір бактериялар пайда бола бастайды.;;;
Ішек флорасындағы бұл микроағзалардың кейбірі пайдалы, ал кейбірі зиянды бактериялар болып саналады. Бұл ішек флорасының тепе-теңдігін сақтау үшін қажет. Бактериялардың екі түрі де бір-бірінің шамадан тыс көбеюіне немесе санының азаюына жол бермей, ас қорыту жүйесінде тепе-теңдік қалыптастырады. Флорадағы бактериялардың шамадан тыс көп болуы іш өтуге және сұйықтықтың көп жоғалуына әкелсе, тым аз болуы іш қатуға жағдай жасайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен толғақпен келе жатырмын! ⚡ Егер ішің белгілі бір аралықпен қатайып, қайта босаңсып, бұл сезім біртіндеп күшейіп жатса, демек мен есікті қағып тұрмын. Толғақ мені төменге, шығатын жолға қарай итереді. Әр толғақ кезінде маған оттегі сәл аз жетеді, бірақ мен төзімдімін. Маған көмектесу үшін терең тыныс ал.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Босанудың кешігуінен туындаған күйзеліс Сізді шаршатуы мүмкін. Айналаңыздағылардың бәрі «Әлі босанбадыңыз ба?» деп сұрайды. Бұл психологиялық қысым тудырады. Ал денеңізде жамбас сүйектеріне түсетін қысым ең жоғары деңгейге жетті. Ұйқысыздық пен мазасыздық жалғасады. Денеңіз босануға толық дайын. Жамбас байламдары барынша босаңсыған.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Егер Брэкстон-Хикс жиырылулары жүйелі бола бастаса, міндетті түрде жатып демалыңыз және көбірек су ішіңіз. Егер жатқан кезде де жиырылулар басылмай, әр 10 минут сайын қайталанса, бұл босанудың басталғанын білдіруі мүмкін. Бүгін өзіңізді қатты шаршатпаңыз, баяу әуен тыңдап, бөпеңізбен бірге өткізетін осы соңғы біртұтас сәттерден ләззат алыңыз.') WHERE id = '7bc0ef79-b157-4b4f-94b8-a06d51f2d8d7';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің миының даму қарқыны басының өсуімен қатар жүреді. Дүниеге келгенде орта есеппен 33-35 см болатын бас шеңбері алғашқы алты айда жылдам өседі. Кейін өсу қарқыны баяулағанымен, өсу жалғаса береді. Бөпеңіздің дүниеге келгеннен кейінгі миының дамуы, яғни басының өсуі жасына сай белгіленген стандартты өсу қисықтары бойынша бағаланады:;;;
Микроцефалия: Егер бөпенің бас шеңбері жасына сәйкес болуы тиіс мәндер ауқымының %3-інен төмен болса, бұл жағдай микроцефалия деп аталады. Мұндайда мидың дамуына кедергі келтіретін факторлар (генетикалық факторлар немесе жүктілік кезінде болған ауыр инфекциялар) тексеріледі.;;;
Макроцефалия: Бас шеңбері қалыпты мәндердің %90-ынан жоғары болған жағдайда макроцефалия диагнозы қойылады. Мұндайда ми мен оны ұстап тұратын құрылымдардың қалыптан тыс ұлғаюына және қысымға ұшырауына себеп болатын факторлар зерттеледі.;;;
Бөпеңіздің миы өте жылдам дамиды; дүниеге келгеннен кейінгі алғашқы жыл ішінде ми көлемі шамамен %88-ге ұлғаяды.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен әлі осындамын ба? 🏠 Егер әлі дүниеге келмесем, мұңайма. Кейде мерзімді есептеуде қате болуы мүмкін немесе маған тағы бірнеше күн қажет шығар. Ана құрсағында өткізген әр күнім мен үшін пайдалы (егер плацента жақсы жұмыс істесе). Мен өз уақытымды білемін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Егер жүктілігіңіз әсіресе жаз айларына сәйкес келсе, маусымдық жазғы жемістерді жеу өте пайдалы. Дәрумендер мен минералдарға бай жазғы жемістердің антиоксиданттық қасиеттері бар әрі тағамдық құндылығы жоғары.;;;
Олардың арасынан құлпынай сияқты талшыққа бай жемістерді жесеңіз, ұзақ уақыт тоқтық сезімін сақтап, жүктілік бойы салмағыңызды оңай бақылай аласыз.;;;
Құлпынай құрамындағы фолий қышқылы бөпеңіздің жүйке жүйесінің дамуына көмектеседі, ал магний сүйектерінің дамуына және сүйектену үдерісінің дұрыс жүруіне ықпал етеді.;;;
Ал авокадо — қанықпаған май қышқылдары ең көп кездесетін жемістердің бірі. Құрамында пайдалы майлармен қатар фолат пен калий де көп. Калий жүктіліктің соңғы кезеңінде аяқтағы құрысуды жеңілдетуге көмектеседі.;;;
Бұл жемістердің құрамында пайдалы көмірсулар, C дәрумені мен тағамдық талшықтар бар. Әсіресе ағзаңызға темірдің сіңуі үшін қажет C дәрумені өте көп. C дәрумені теріңіздің саулығы мен иммундық жүйеңіздің жұмысы үшін де маңызды.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Егер өзіңізді қатты ауыр сезінсеңіз, арқаңызды тіреп, жылы душ қабылдаңыз. Бұл бұлшықеттерді босаңсытып қана қоймай, Брэкстон-Хикс жиырылуларын да азайтады. Бөпеңіздің қимылдарын әлі де сезінуіңіз маңызды; егер қимылдары кенет азайса, дереу дәрігеріңізге хабарлаңыз. Осы соңғы күндері ұйықтау қиындауы мүмкін, сондықтан сол жақ қырыңызбен жатып, аяқтарыңыздың арасына жастық қойыңыз.') WHERE id = 'fd795c4a-8409-4cb2-89fc-4a9fbcef21a6';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің сезім мүшелері арқылы сыртқы тітіркендіргіштерді қабылдауы, оларды өзінше түсіндіруі, рефлекстік қимылдары, ұйқы режимі — бір сөзбен айтқанда, осы күрделі үдерістердің барлығы ағза жүйелерінің тиімді жұмысының нәтижесінде жүзеге асады. Бөпеңіздің ағзасындағы жүйелердің ретімен, өзара үйлесімді әрі кедергісіз жұмыс істеуін жоғары деңгейде дамыған бақылаушы және реттеуші жүйе қамтамасыз етеді.;;;
Бөпеңіздің тіндері мен ағзаларының қызметін реттеу үшін тек жүйке жүйесі жеткіліксіз. Бұл үдеріс жүйке жүйесі мен ішкі секреция бездерінің бірлескен жұмысы арқылы жүзеге асады. Ішкі секреция бездері бөпеңіздің миынан келетін сигналдардың әсерінен гормондар деп аталатын арнайы заттарды бөліп шығарып, реттеуші қызмет атқарады.'), baby_message_kk = COALESCE(baby_message_kk, 'Гормондарым іске кірісіп жатыр! 🧪 Менің ағзам бен Сіздің плацентаңыз босану үдерісін жеделдету үшін арнайы гормондар бөледі. Сіз өзіңізді өте сезімтал, тіпті жылауық сезінуіңіз мүмкін. Бұл — біздің химиялық байланысымыз.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде қоршаған ортаның кейбір факторларынан туындауы мүмкін жайсыздықтармен қатар, гормондық өзгерістерге байланысты ағзаңызда әртүрлі қолайсыздықтар пайда болуы ықтимал. Жүктіліктің соңғы кезеңінде кездесетін преэклампсия, яғни жүктілік кезіндегі уыттану, қан қысымының жоғарылауы және зәрде ақуыздың анықталуы арқылы белгіленеді. Жүктілік ұлғайған сайын плацентаға қажетті қан мен қоректік заттардың мөлшері айтарлықтай артады. Сондықтан плацентаны қоректендіретін қан тамырлары кеңейеді. Алайда жүктілік кезіндегі уыттану пайда болғанда, бұл тамырлардың құрылымы тарылып, плацентаға қажетті қан мен қоректік заттар жеткілікті мөлшерде бармайды. Мұндай жағдайдың туындау ықтималдығы өте төмен болғанымен, ол пайда болса, Сіздің де, бөпеңіздің де өміріне қауіп төнетіндіктен, шұғыл медициналық көмек қажет.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Күш-қуатыңызды сақтаңыз. Ауыр тағамдар жемеңіз. Босану кез келген сәтте басталуы мүмкін болғандықтан, асқазаныңызды шамадан тыс толтырмаңыз (құсу рефлексі болуы мүмкін).') WHERE id = '938fd655-5567-4125-a9f7-ead570f3ba8c';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ағзасында барлық ішкі секреция бездері қалыптасқандықтан, ол ересек адамдікімен бірдей арақатынаста барлық гормондарды синтездей алады. Олардың ішінде бөпеңіздің өсуін қамтамасыз ететін және әсіресе ұйқы кезінде бөлінетін ең маңызды гормон — өсу гормоны.;;;
Өсу гормоны — мида орналасқан гипофиздің алдыңғы бөлігінде синтезделетін және шамамен 200 түрлі аминқышқылынан тұратын ақуыз. Бұл гормон бөпеңіздің өсуі мен зат алмасу жылдамдығын қоса алғанда, көптеген күрделі физиологиялық үдерістерге қатысады. Басқа гормондардан айырмашылығы, оның нысанасы белгілі бір ағза емес, бүкіл дене жасушалары. Ол өсу кезінде жасушалардағы ақуыз синтезін жеделдетіп, көмірсулар мен майлардың алмасуын реттейді.;;;
Өсу гормонының синтезделуі мен бөлінуі кешкі уақытта басталып, күн шыққанда аяқталады. Ол 23:00 - 05:00 аралығында ең белсенді бөлінеді. Әсіресе сағат 03:00 шамасында ағзадағы ең жоғары деңгейіне жетеді. Түнде қандағы мөлшері артатын бұл гормон жасушалардың митоздық бөлінуін жеделдетіп, тіндер мен ағзалардың, әсіресе қаңқа бұлшықеттерінің, сүйектер мен шеміршектердің өсуін қамтамасыз етеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің түсім өзгерді! 🎨 Енді қызыл емеспін. Тері астындағы май қабатының арқасында түсім қызғылт немесе ашық түсті болды. Верникс қабаты түгелге жуық жоғалды. Терім аздап құрғақ болуы мүмкін. Мен дүниеге келуге толық дайын адаммын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Кейбір жүкті әйелдерде мұрыннан қан кету ара-тұра байқалса, басқаларында мұндай жағдай күн сайын дерлік қайталануы мүмкін. Екі жағдай да жүктілік кезінде қалыпты саналады және Сізге де, бөпеңізге де зиянсыз. Бөпеңіздің артып келе жатқан қажеттіліктерін қамтамасыз ету және өз денсаулығыңызды сақтау үшін жүктілік кезінде ағзаңыз көбірек қан өндіреді. Соның нәтижесінде қанайналым жүйесінде айналатын қан көлемі айтарлықтай артады. Қан көлемі көбейген сайын мұрынның шырышты қабығындағы жіңішке әрі беткей орналасқан қан тамырларына түсетін қысым да жоғарылайды. Қысымның артуынан осы нәзік тамырлардың қабырғасы жарылып, қан кетуі мүмкін. Мұрыннан қан кете бастаса, мұрын сүйегінің үстінен қысып, шамамен 10 минут күту жеткілікті.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Массаж жасаңыз немесе аяққа арналған ванна қабылдаңыз. Серіктесіңіздің қолдауы өте маңызды. Онымен босану жоспарын тағы бір рет қарап шығыңыз.') WHERE id = '4e4de332-7546-4ae2-8266-e548c84af11c';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Сіз сөйлегенде бөпеңіздің даусыңызға жауап беруі оның сезім мүшелерінің жақсы дамығанын және осы тітіркендіргіштерді түсіндіріп, оларға жауап беруге мүмкіндік беретін жүйке жүйесі бар екенін көрсетеді. Сіз сөйлеген кезде бөпеңіздің толқуына әсер ететін зат — адреналин гормоны. Эпинефрин деп те аталатын адреналин — бөпеңіздің миы мен ағзасында қызмет ететін аса маңызды гормон әрі нейромедиатор. Адреналин ағзада бүйрекүсті бездерінен, ал мида ми бағанының айналасында орналасқан кейбір арнайы жүйке жасушаларынан бөлінеді.;;;
Қандағы қант деңгейінің жоғарылауы бөпеңіздің дене жасушаларына қоректік заттардың көбірек жетуін қамтамасыз етеді. Ал жүрек соғуының жиілеуі ағзаның оттегіге деген қажеттілігін жоғары деңгейде өтеуге көмектеседі.;;;
Осы дайындықтардың нәтижесінде адреналин бөпеңіздің бұлшықеттері жиырылып, олардың энергия жұмсауына қажетті жағдай жасайды. Осылайша, ол Сіздің даусыңызға қимылмен жауап береді.'), baby_message_kk = COALESCE(baby_message_kk, 'Ертең ерекше күн бе? 📅 Ертең — менің ресми "босану күнім". Бірақ мен бүгін де келе аламын. Мен Сіздің даусыңызды естіп тұрмын, Сіз "Енді келші" дейсіз. Мен де келгім келеді, Anacan. Жол ұзақ, бірақ соңында жарық бар.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Әсіресе жүктіліктің соңғы кезеңдерінде жиі кездесетін мәселелердің бірі — ұйқысыздық. Ағзаңызда магний жетіспесе, ұйқысыздық күшеюі мүмкін. Ұйқының сапасын жақсартатын жүйке жүйесі гормондарының, яғни нейромедиаторлардың қандағы мөлшері қажетті деңгейде сақталуы үшін ағзада магний жеткілікті болуы керек. Магнийге ең бай көкөністердің қатарына саумалдық, жасыл үрмебұршақ, брокколи және қырыққабат жатады.;;;
Сонымен қатар асқабақ дәні, күнбағыс дәні, жержаңғақ, бадам, кешью, банан, авокадо, дәнді дақылдар, сүт және йогурт та магнийге бай.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бүгін Сіз үшін "соңғы тыныштық" күні болсын. Күш-қуатыңызды тазалыққа немесе шаршататын жұмыстарға мүлде жұмсамаңыз. Босану кез келген сәтте басталуы мүмкін, сондықтан ауыр тағамдар жемей, жеңіл әрі қуат беретін тіскебасарларға басымдық беріңіз. Егер қағанақ суы кетсе (тіпті толғақ болмаса да) немесе толғақ әр 5-7 минут сайын жүйелі түрде қайталанса, ауруханаға баратын уақыт келді. Өзіңізге сеніңіз, Сіз бұған дайынсыз!') WHERE id = '7abac408-c74e-44ce-86ac-a1a2470ea25a';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Жүктіліктің 40-аптасы аяқталғанда бөпеңіз дүниеге келер кездегі салмағы мен бойына жетті. Бөпеңіздің жалпы дене салмағының шамамен %20-і ақ және қоңыр май жасушаларынан тұрады, олар терісіне қызғылт реңк пен жұмсақтық береді. Ағза жүйелері толық жетілген, ал өкпесіндегі сурфактанттың түзілуі аяқталған бөпеңіз сыртқы әлемдегі өмірге толығымен дайын.;;;
Егер 40-апта аяқталса да, босану әлі басталмай, жүктілігіңіз жалғасып жатса, босану белгілерін мұқият бақылауыңыз керек:;;;
Қынаптық бөлінді: Айтарлықтай үлкейген жатырдың қысымынан бөлінді сұйығырақ болуы мүмкін. Сондай-ақ оның түсі қоңыр немесе сары болуы ықтимал.;;;
Инфекция туралы ескерту: Сыздықтап ағатын мұндай бөліндіден жағымсыз иістің шығуы инфекция белгісі болып саналады.;;;
Қағанақ суын анықтау: Аққан сұйықтықтың кәдімгі бөлінді немесе бөпені қоршап тұрған қағанақ суы екенін ажырата алмасаңыз, медициналық мекемеде pH деңгейін өлшейтін қарапайым тестілердің (нитразин тесті) көмегімен нақтылай аласыз.'), baby_message_kk = COALESCE(baby_message_kk, 'Құттықтаймын, Anacan! Біз 40 апталық марафонды аяқтадық. Бүгін — менің ресми туған күнім! 🎂 Егер бүгін құшағыңызға келсем — Сәлем, әлем! Ал әлі келмесем, уайымдамаңыз: мен кешіккен жоқпын, жай ғана "трендке" сай өзімді күттіріп жатырмын. Ең көбі 1-2 аптадан кейін міндетті түрде кездесеміз. Сізді жақсы көремін!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Бүгін жүктілігіңіздің 40 аптасы аяқталды. Мерзіміңіз жеткеніне қарамастан босану әлі басталмаса, алаңдамаңыз. Сіз айлар бойы күттіңіз және бөпеңізді мүмкіндігінше тезірек құшағыңызға алғыңыз келетін шығар. Босанудың неліктен кешігіп жатқаны туралы сұрақтар туындауы мүмкін. 40 аптаның соңында босанудың басталмауы соңғы етеккір күнінің қате есептелуіне немесе ұрықтанудың кеш жүруіне байланысты болуы ықтимал. Кейде мерзім дұрыс есептелсе де, босану ешбір себепсіз кешігуі мүмкін. Абыржымай, әлі 2 апта уақытыңыз бар екенін ұмытпаңыз. Тек осы кезеңде туындауы ықтимал кейбір асқынуларға мұқият болып, дәрігерге жиірек қаралып, қажетті талдаулардан өтуіңіз керек. Жүктілік мерзімі аяқталғаннан кейін де бөпеңіз сол қарқынмен салмақ қоса беретіндіктен, табиғи босану қиындауы мүмкін. Дүниежүзілік денсаулық сақтау ұйымының (ДДСҰ) мәліметі бойынша, салмағы 4500 грамм бөпелер табиғи босануға кедергі келтірмейді.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бүгін күнтізбе бойынша соңғы күн болса да, көңіліңізді тыныш ұстаңыз. Толғақ басталмаса, жеңіл серуендеңіз немесе жылы душ қабылдаңыз. Босануға арналған сөмкеңіз бен құжаттарыңызды есік алдында соңғы рет тексеріңіз. Толғақ әр 5 минут сайын қайталанса немесе қағанақ суы кетсе, дереу ауруханаға барыңыз. Ұмытпаңыз: Сіз таңғажайып істі атқардыңыз, енді ең үлкен сыйыңызды алғалы тұрсыз!') WHERE id = '08e8895d-cc10-4825-8aac-fb6a2a6d3d95';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің жүйке жүйесі мен миы құрсақта жатқан кездің өзінде өте белсенді дамиды әрі тоқтаусыз, ерекше жылдамдықпен өседі. Әсіресе үйрену үдерісі біртіндеп басталатын жүктіліктің соңғы триместрінде (соңғы үш айында) Сіз сезінген әрбір эмоция гормондар арқылы бөпеңізге тікелей әсер етеді:;;;
Кортизолдың әсері: Қатты уайымдап, күйзеліске түсіп немесе қорқыныш сезінгенде, ағзаңыздағы кортизол деңгейі жоғарылайды. Бұл гормон бөпеңіздің бүкіл жүйке жүйесіне әсер етеді.;;;
Химиялық реакция: Осындай ауыр эмоциялардан бөлінетін кортизол бөпеңіздің ағзасына өтіп, оның ми қызметіне әсер ететін кейбір химиялық заттардың бөлінуіне себеп болады.;;;
Жүктіліктің соңғы күндерінде эмоцияларыңызды мүмкіндігінше бақылауда ұстау бөпеңіздің жүйке жүйесінің саулығы үшін өте маңызды.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен әлі осындамын! 👋 Сәлем, Anacan! Күнтізбедегі күн өтіп кетті, бірақ мен әлі де Сіздің жылы құрсағыңыздамын. Уайымдамаңыз, статистика бойынша бөпелердің небәрі 5%-ы дәл белгіленген күні дүниеге келеді. Маған мұнда жайлы болғаны сонша, шығуға асығар емеспін. Біздің өзімізге арналған ерекше уақытымыз бар.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің 40 аптасынан кейін де босануы басталмаған әйелдер кейбір жағдайларға ерекше мұқият болуы керек. Соның ең маңыздысы — бөпеңіздің қимылдау жиілігі. Бөпеңіздің қимылдары баяуласа, бұл кейде Сізді алаңдатуы мүмкін. Бұған бөпенің салмағына байланысты жатыр ішінде қозғалуға жеткілікті орын қалмауы себеп болады. Дегенмен бөпеңіздің қимылы айтарлықтай азайғанын сезсеңіз, дәрігеріңізбен кеңесуіңіз керек. Босану уақыты жақындағандықтан, Брэкстон-Хикс деп аталатын жалған толғақ ауырсынумен өтуі мүмкін. Жалған толғақты бақылап, оның қаншалықты жиі қайталанатынын тексеру оны шынайы босану толғағымен шатастырмауға көмектеседі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бұл күнді атап өтіңіз! Өзіңізге торт сатып алып, "Әлі босанған жоқпын" деген селфи жасаңыз. Бұл күндер енді қайтып келмейді. Өміріңіздегі ең үлкен шытырман оқиға басталғалы тұр!') WHERE id = '2d2b31a8-8f73-4858-b9b0-2f01ec75aada';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бұл кезеңде бөпеңіз ағзасына қажетті оттегіні, көмірсуларды, майларды, ақуыздарды, дәрумендер мен минералдарды плацента арқылы тікелей Сіздің ағзаңыздан алады. Дегенмен дүниеге келген сәттен бастап сүтті құрамдас бөліктерге ыдыратып, оларды өсуіне пайдалану үшін бөпеңіздің бүкіл ас қорыту жүйесі жұмыс істеуге жеткілікті деңгейде жетілген. Бөпеңіз құрсақта өткізген әр күні бірнеше литр қағанақ суын жұтып, ас қорыту жүйесін жаттықтырады. Бұл "жаттығу" дүниеге келгеннен кейін ас қорыту үдерісінің бірқалыпты жүруі үшін өте маңызды.'), baby_message_kk = COALESCE(baby_message_kk, 'Туыстарды тыңдамаңыз! 🙉 Білемін, бәрі қоңырау шалып, "Әлі босанбадың ба?" деп сұрап жатыр. Бұл Сізді шаршатады, солай ма? Оларға менің "VIP қонақ" екенімді және сахнаға шығатын ең қолайлы сәтті күтіп жатқанымды айтыңыз. Сіз жай ғана демалып, бұл сұрақтарға мән бермеңіз.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде салмағыңызды бақылауда ұстау және арта түскен тәбетіңізді тежеу кейде қиын болуы мүмкін. Алайда салмақ қосудан қорқып, жеткілікті мөлшерде тамақтанбау да денсаулыққа өте зиян. Бөпеңіздің дамуы үшін тұтынатын тағамдарыңыздың өмірлік маңызы бар екенін ұмытпаңыз. Бөпеңізге қажетті дәрумендер мен минералдарды қамтамасыз ету әрі салмағыңызды бақылауда ұстау үшін бұл кезеңде көмірсуы мол тағамдарды азайтып, ақуызға бай тағамдарға басымдық бергеніңіз жөн.;;;
Бөпеңіздің дені сау болып дамуы үшін жүктілік кезінде 10-12 килограмм салмақ қосу жеткілікті. Бұл — орташа көрсеткіштер, дене салмағы индексіңізге қарай ол 6 килограмға дейін төмен немесе 16 килограмға дейін жоғары болуы мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Осы күндері айналаңыздағы адамдардың "Әлі босанбадыңыз ба?" деген сұрақтары Сізді шаршатуы мүмкін. Жай ғана жымиып, бөпенің өзі үшін ең қолайлы уақытты өзі таңдайтынын еске салыңыз. Ішкі тыныштығыңызды сақтаңыз.') WHERE id = '912237d6-e1bb-4ef4-b942-ca1a90b3bc59';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіз қабылдаған қоректік заттардың ішекте сіңуіне көмектесетін және оның ағзасына қажетті кейбір бактерияларды түзетін ішек микрофлорасы тек босанғаннан кейін ана сүтін емуі және қоршаған ортамен байланысқа түсуі нәтижесінде қалыптасады. Бұл кезеңде бөпеңіз жатырдағы амнион сұйықтығын ғана жұтады, ал дүниеге келгеннен кейін алғаш рет қоректенгенде ас қорыту жүйесі дамуының алғашқы кезеңі аяқталады. Ана құрсағында толық стерильді ортада жатқан бөпеңіздің ас қорыту жүйесі тек босанғаннан кейін толық жетіледі. Бөпеңіздің асқазаны дүниеге келген сәттен бастап жылдам өзгереді:;;;
Алғашқы 24 сағатта: шиедей (шамамен 5-7 ml).;;;
3-ші күні: грек жаңғағындай (шамамен 22-27 ml).;;;
30 күннің соңында: орташа көлемді жұмыртқадай болады (шамамен 60-150 ml).;;;
Бөпеңіздің ас қорыту жүйесі ересек адамның ас қорыту жүйесіне 6-шы айдан бастап, қосымша тағамға көшу кезеңінде ұқсай бастайды, ал 2 жастан бастап ересек адамның ас қорыту жүйесіндей дерлік жетіледі.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен тағы да біраз салмақ қостым! ⚖️ Anacan, мен әлі де салмақ қосып жатырмын. Осы қосымша күндерде бетім одан сайын томпайып, қолдарым одан сайын бүп-бүдір болып келеді. Дүниеге келгенімде мені құшақтау тіпті сүйкімді болады. Күш жинаңыз, өйткені маған Сіз өте қажет боласыз.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде тағам арқылы әрбір дәрумен мен минералдың ағзаңызға тұрақты түрде түсіп отыруы маңызды. Осындай дәрумендердің бірі — К дәрумені. Ол ағзаңыздың жұмысы үшін де, бөпеңіздің денсаулығы үшін де өте маңызды. К дәрумені кальцийдің қаңқа сүйектерінің құрылымына жиналуына көмектесіп, сүйек саулығын қолдайды. Сондай-ақ кальцийдің қан тамырлары мен бүйректе жиналуына жол бермейді. Бір сөзбен айтқанда, ағзадағы кальций мөлшерін теңестіреді. Оның тағы бір қызметі — жүрек саулығын сақтауда белсенді рөл атқаратын ақуыздарды іске қосу. Ағзадағы артық К дәрумені бауырда жиналады. К дәрумені майда еритін дәрумендерге жатады. Жүктілік кезінде Сізге күніне кемінде 90 mkq К дәрумені қажет. Сондықтан жасыл жапырақты көкөністерді, жұмыртқа, ет және сүт өнімдерін тұтыну керек.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Босану кез келген сәтте басталуы мүмкін, сондықтан бүгін өзіңізге ерекше мейіріммен қараңыз. Күйзелістен аулақ болу үшін сүйікті фильміңізді көріңіз немесе терезеден табиғатты тамашалап, терең тыныс алыңыз.') WHERE id = 'ab9a202d-7f8e-48d6-9bd2-ce62eab926ef';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің көмірсу алмасуын реттейтін, инсулиннің көмегімен қандағы глюкозаны гликогенге айналдырып сақтайтын бауыры босануға толық дайын. Бауырдың осылай дайындалуы босану кезінде және Сіз емізгенге дейін бөпеңіздің қанындағы қант деңгейінің төмендеп кетпеуін әрі жасушаларының қорексіз қалмауын қамтамасыз етеді. Сүт жолдарыңыз дүниеге келген алғашқы күні асқазаны шиедей ғана болатын бөпеңізге қажетті мөлшерде сүт бөледі. Бауырда жиналған гликогеннің арқасында алғашқы күндері сүтіңіз аз болса да, бұл бөпеңізге қауіп төндірмейді. Босану жақындаған сайын бөпеңіз жұтатын амнион сұйықтығы несеппен шығаратын сұйықтықтан көбірек болады. Бөпеңіздің ағзасында сақталған осы артық сұйықтық тіндердің арасына жиналып, босанғаннан кейін жасушалар тарапынан пайдаланылады.;;;
Бөпеңіздің ағзасында сақталған осы артық сұйықтық босанғаннан кейін пайдаланылып, несеп арқылы шығарылатындықтан, алғашқы күндері оның туған кездегі салмағы 10%-ға дейін азаюы мүмкін. Мұндай салмақ жоғалту қалыпты деп есептеледі. Бөпеңіз орта есеппен 7-10 күн ішінде ағзадан шығарылған судың орнына май жинап, туған кездегі салмағына қайта оралады.'), baby_message_kk = COALESCE(baby_message_kk, 'Маникюр жасайтын уақыт келді ме? 💅 Білесіз бе, менің тырнақтарым әжептәуір өсіп қалды. Тіпті кейде өзіме қол тигізгенде терімді тырнап аламын. Дүниеге келген бойда жасайтын алғашқы ісіміз тырнақтарымды алу болуы мүмкін. Шашым да (егер бар болса) өсуін жалғастырып жатыр. Сәнденіп келе жатырмын!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Босану кез келген сәтте басталуы мүмкін екенін ұмытпай, оған әрдайым дайын болуыңыз керек. Босанатын уақыт келгенде толғақ бастапқыда жеңіл сезіледі. Алғашқы кезеңде толғақ сирек болғанымен, біркелкі аралықпен сезілетін ауырсыну біртіндеп жиілеп, ұзарып әрі күшейе түседі. Әр жүктілік әртүрлі өтеді. Сондықтан әр босану үдерісінің де өзіндік ерекшелігі болатынын ескеру қажет, дегенмен мұндай ауырсыну әдетте етеккір кезіндегі қатты түйілуге ұқсайды. Егер толғақ 10-15 минут аралықпен қайталана бастаса, босанудың жақындағанын білдіруі мүмкін. Дегенмен нақты жағдайды дәрігеріңіз бағалайтындықтан, көп күтпей, ауруханаға баруыңыз керек.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Денеңіздің белгісіне құлақ асыңыз. Егер ішіңізден бір мазасыздық сезсеңіз, дереу жатып, бөпеңізбен сөйлесіңіз. Сіздің сабырлылығыңыз — оның дүниеге келер жолындағы ең үлкен қолдау.') WHERE id = '2c4fb6e2-626f-4582-b7ad-da6ef85b1258';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіз дүниеге келгеннен кейін жиі кездесетін жағдайлардың бірі — жаңа туған нәрестелердің сарғаюы. Бұл жағдай мерзімінде туған бөпелердің шамамен %60%-інде, ал шала туғандардың %80%-інде байқалуы мүмкін. Халық арасында оны көбіне жеткілікті қоректенбеумен байланыстырады, бірақ бұл — қате түсінік. Негізінде бұл толықтай физиологиялық үдеріс және ағзаның сыртқы ортаға бейімделу реакциясы.;;;
Жүктілік кезінде бөпеңіз өзіне қажетті оттегіні плацента арқылы Сіздің қаныңыздан алады. Алайда ана құрсағындағы оттегі деңгейі сыртқы ортадағыдан әлдеқайда төмен. Бөпеңіздің ағзасы осы аз мөлшердегі оттегіні барлық жасушаларға таратып, тепе-теңдікті сақтау үшін сүйек кемігінің жұмысын күшейтеді. Сүйек кемігінің осындай қарқынды жұмысының нәтижесінде ағзада көптеген эритроцит түзіледі. Бұл жасушалар бөпеңіздің әрбір жасушасына оңай жетіп, оттегі тапшылығының алдын алады.;;;
Ал босанғаннан кейін бөпеңіз оттегі мол ортамен бетпе-бет келеді. Енді оның ағзасына соншалық көп эритроцит қажет болмайды да, артық жасушалар бауырда ыдырай бастайды. Осы ыдырау кезінде түзілетін билирубин бөпеңіздің терісі мен көзінің ағының физиологиялық тұрғыда сарғаюына себеп болады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мұнда орын тым тар болып кетті! 🏠 Anacan, бұл жер енді «студиялық пәтерден» де кішкентай. Қозғалу өте қиын, сондықтан қимылдарым азаюы мүмкін. Бірақ Сіз мені күн сайын сезуіңіз керек. Егер тым тыныш жатқанымды байқасаңыз, тәтті бір нәрсе жеңіз, мен бірден жауап беремін!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Бөпеңіз едәуір өскендіктен, осы кезеңде кейбір физиологиялық жайсыздықтарыңыз айтарлықтай күшеюі мүмкін. Әсіресе асқазаныңызға қысым түсуіне байланысты қыжыл қатты мазалауы ықтимал. Жүктілік кезіндегі қыжыл гормондық өзгерістерден және жатырдың ұлғаюына байланысты асқазанға түсетін қысымнан туындайды.;;;
Жүктілік кезіндегі қыжылды басуға көмектесетін сусындардың бірі — жылы сүт. Ұйықтар алдында ішілген бір стақан жылы сүт асқазаныңызды тыныштандырып, қышқылдан туындайтын ашыту сезімін жеңілдетеді.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бүгін барлық істі бір шетке қойыңыз. Демалысқа шыққандай еркін тынығыңыз. Есіңізде болсын: Сіз нағыз ғажайып жасап жатырсыз, ал денеңіз әлемдегі ең қиын әрі ең әдемі іске дайындалуда.') WHERE id = 'd01cbe86-cb64-4e22-98cc-8f8bd1c8a6d5';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ішегінде туғаннан кейінгі 3-күннен бастап қалыптаса бастайтын ішек флорасының құрамындағы микробиота деп аталатын бактериялар жылдам көбейе бастайды. Бөпеңіздің ішек микробиотасы ішектің ішкі қабырғасын қаптайтын жасушалардың көбеюін қамтамасыз ететін күрделі үдерістерге қатысады. Микробиота деп аталатын осы бактериялар қауымдастығының салмағы бөпеңіздің өсуіне қарай артып, ересек жасқа жеткенде шамамен 2 килограмм болады. Бұл бактериялар бөпеңіздің ағзасына ауру тудыратын зиянды микроорганизмдердің енуіне жол бермейтін қорғаныс тосқауылы қызметін атқарады. Олар бөпеңіз қорыта алмайтын кейбір тағамдардың қорытылуына көмектесіп, иммундық жүйенің қызметін реттейді. Бөпеңіздің ішек флорасындағы осы микробиота қауымдастығы, әсіресе, майда еритін витаминдер мен ағзаға қажетті кейбір заттардың түзілуіне қатысады. Құрамындағы миллиондаған бактериялар мен жүйке жүйесіндегіден 9 есе көп нейромедиаторлық заттардың арқасында ішек флорасы соңғы жылдары жеке мүше ретінде қарастырыла бастады.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің плацентам әлі де жұмыс істеп тұр! 🔋 Дәрігерлер менің қағанақ суым мен плацентамды тексеріп жатқан шығар. Бәрі жақсы. Мен әлі де Сіз арқылы тыныс алып, Сізден қоректенемін. Біз бір командамыз және соңына дейін біргеміз. Қорықпаңыз, мен белгіні күтіп жүрмін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілігіңіздің айтарлықтай ілгерілеген кезеңіндесіз. Сондықтан тамақтануыңызға көңіл бөлу бұрынғыдан да маңызды. Жеткілікті өскен бөпеңіз жатқан жатыр ішкі ағзаларыңызға қысым түсіретіндіктен, ас қорыту жүйесіне қатысты кейбір мәселелер туындауы мүмкін.;;;
Әсіресе кешкі ас кезінде қуырылған, ащы дәмдеуіштері көп және өте майлы тағамдарды тұтынбай, асқазаныңызға жайсыздық тудырмайтын жеңіл ас жеуіңіз керек. Кешкі асқа көкөністен жасалған тағамдар өте пайдалы, бірақ көкөністердің жақсы піскеніне көз жеткізіңіз. Шала піскен көкөністер қыжылды күшейтуі мүмкін. Газдалған және кофеині бар сусындарды, сондай-ақ асқазан қышқылдығын арттыратын грейпфрут пен апельсин сияқты қышқылдығы жоғары жемістерді азайтуыңыз немесе олардан толық бас тартуыңыз керек. Сонымен қатар кофе немесе шай секілді сусындарды шамадан тыс ішпеуге тырысыңыз. Асықпай тамақтаныңыз және тамақтану кезінде сұйықтық ішпеу арқылы іштің кебуін барынша азайтыңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Шиеленісті азайту үшін жылы душ қабылдаңыз. Судың денеңізді босаңсытуына мүмкіндік беріңіз. Босанатын сәтті қорқынышпен емес, бөпеңізбен қауышатын алғашқы сәттің қуанышымен елестетуге тырысыңыз.') WHERE id = '1682ff26-3ced-4844-9a8e-8e67a40347cb';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Мерзімі өтіп кеткен жүктілікте кейбір асқынулар жиірек туындайтындықтан, ағзаңызда пайда болуы мүмкін белгілерге назар аудару өте маңызды. Плацентаның мерзімінен бұрын ажырауы және бөпеңіздің ішегінде жиналған меконийдің (алғашқы нәжістің) қағанақ суына бөлініп, тыныс жолдары арқылы өкпесіне түсуі сияқты мәселелер жүктіліктің 40-аптасынан бастап жиірек байқалуы мүмкін.;;;
«Плацентаның ажырауы» деп босанғанға дейін бөпеңізді қоректендіретін плацентаның босану басталмай тұрып жатыр қабырғасынан бөлінуін айтады. Бұл жағдай Сізге де, бөпеңізге де елеулі қауіп төндіруі мүмкін, сондықтан кез келген қан кету кезіндегідей дереу дәрігерге жүгінуіңіз қажет. Плацентаның мерзімінен бұрын ажырауы өте сирек кездескенімен, әрбір 200 жүктіліктің бірінде байқалады. Бұл жағдайдың ең жиі кездесетін белгілері — ауырсынумен қатар жүретін қою түсті, ұйымайтын қынаптық қан кету. Әсіресе плацента қатты ажыраған жағдайда ағзаңызда гипотония мен шок белгілері пайда болуы мүмкін. Ал бөпеңіздің жүрек соғысы нашарлауы ықтимал. Сондықтан қан кетсе, міндетті түрде дәрігерге жүгініңіз.'), baby_message_kk = COALESCE(baby_message_kk, 'Түс көріп жүрмін... 💤 Көбіне ұйықтаймын. Сіздің жүзіңіз қандай екен? Даусыңыз маған әбден таныс болып қалды. Әкемнің де даусы естіледі. Түсімде Сіздерді көріп жүрмін. Бұл түс жақында шындыққа айналады.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Дұрыс тыныс алу және тыныс алу жаттығуларын жиі орындау жүктілік кезінде кездесетін мәселелерді азайтып қана қоймай, жеңіл босануға көмектеседі.;;;
Әсіресе жүктіліктің осы кезеңінде ағзаңызға бұрынғыдан да көп оттегі қажет. Дұрыс әрі сапалы тыныс алу жүктілік кезінде де, босану сәтінде де табиғи ауырсынуды басатын құрал қызметін атқарып, дененің босаңсуына көмектеседі. Тыныс алу жаттығулары ағзаларыңызға көбірек оттегі жеткізетіндіктен, қыжыл, ас қорытудың бұзылуы, іш қату, іштің кебуі және жел жиналу сияқты шағымдарыңыз да біршама азаяды. Бұған қоса, терең, бақыланатын және баяу тыныс алу жаттығулары жүрек айну мен бас айналуға да оң әсер етеді.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Егер бүгін де күтіп жүрсек, бұл бөпеңіздің құрсағыңызда соңғы дайындықтарын жасап жатқанын білдіреді. Сабыр сақтап, денеңізге сеніңіз. Сіз өте мықты әйелсіз және бәрін керемет еңсересіз.') WHERE id = '5ae12c1c-33a8-4883-a677-24cfe3025ffd';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Жүктіліктің 38-аптасына дейін босанулардың шамамен %80-і болып қояды. Сондықтан 42-аптаға аяқ басқан осы күндері босану әлі басталмаса, өзіңізді қатты алаңдаулы сезінуіңіз мүмкін. Жақсы жаңалық — мерзімі өтіп кеткен жүктілік деп аталатын осы кезеңде босану 42-аптаға дейін өздігінен басталмаса, дәрігеріңіздің кеңесімен босануды дәрі-дәрмекпен қоздыру немесе кесар тілігі арқылы бөпеңізді құшағыңызға ала аласыз. Бөпеңіздің қимылдары кейде қатты ауыртқанымен, алдыңғы апталармен салыстырғанда олардың жиілігі азайғанын байқауыңыз мүмкін. Бөпеңіз бұрынғыдан да тар кеңістікте жатыр, сондықтан оның еркін қимылдайтын орны қалмаған. Күні бойы оның қимылдарын санап, әдеттегіден әлдеқайда азайғанын байқасаңыз, дәрігеріңізбен кеңесуіңіз керек. Осы апталарда қағанақ суының едәуір азаюы қалыпты жағдай болып саналады. Алайда оның мөлшері бөпеңізге күйзеліс туғызатындай азайса, дәрігеріңіз 42-апта аяқталмай тұрып босануды бастап, медициналық шара қолдануы мүмкін.'), baby_message_kk = COALESCE(baby_message_kk, '41-аптаға қош келдік! 🎈 Иә, біз ресми түрде «мерзімінен кешіккен» болып саналамыз (overdue). Бірақ мен мұны «қосымша құндылық қосу» дер едім. Верникс (ірімшік тәрізді қабат) толығымен дерлік жоғалды. Туғанда терім сәл құрғақ болуы мүмкін, бірақ Сіз оны майлап қоясыз, иә?'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Егер жүктілігіңіздің осы кезеңіне дейін босану басталмаса, босану белгілері болмаса және бөпеңіздің салмағы шекті мөлшерге жақындаса, дәрігеріңізбен кесар тілігі туралы сөйлесе аласыз.;;;
Кесар тілігі — табиғи жолмен босану мүмкін болмаған жағдайда, іштің шамамен 4 елі төменгі тұсына хирургиялық тілік жасап, бөпеңізді сол тілік арқылы шығару үдерісі. Кесар тілігі — операцияның бір түрі және табиғи босанумен салыстырғанда анестезия алу, қалпына келу кезеңінің ұзаруы сияқты кейбір кемшіліктері бар. Алайда кейбір кемшіліктеріне қарамастан, табиғи жолмен босану кезінде туындауы ықтимал асқынулар мен бөпеңізге төнетін қауіптерге байланысты кесар тілігі тиімдірек болатын жағдайлар да кездеседі. Бөпеңіздің босану жолына дұрыс орналаспауы, мерзіміңіз жетсе де толғақтың басталмауы немесе «преэклампсия» деп аталатын жүктілік кезіндегі ауыр асқыну болған жағдайда кесар тілігі жасалуы мүмкін.;;;
Босануыңыз табиғи жолмен өтсе де, кесар тілігі арқылы жасалса да, 9 айлық сапардың соңында бөпеңізбен қауышатыныңызды ешқашан ұмытпаңыз. 😊'), daily_tip_kk = COALESCE(daily_tip_kk, 'Стресс гормондары босануды баяулатуы мүмкін. Сондықтан бүгін тек жақсы жаңалықтар тыңдап, Сізге жағымсыз энергия беретін адамдар мен тақырыптардан аулақ болыңыз. Қазір Сіздің эмоциялық саулығыңыз бәрінен маңызды.') WHERE id = '7f952d08-70cf-40a7-af2e-4095f1619337';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Жүктілігіңіздің осы аптасында босануға қажетті мерзім толық аяқталғанымен, кейбір физиологиялық жағдайлар босанудың басталуына кедергі келтіріп, оның кешігуіне әкелуі мүмкін. Дегенмен осы уақыт ішінде бөпеңіз өсіп, дамуын жалғастыра береді. Жүктіліктің 42-аптасында дүниеге келген бөпеңіздің шашы мен тырнақтары едәуір ұзын екенін байқауыңыз мүмкін. Сондай-ақ құрдастарынан 2-3 апта кеш туғандықтан, олардың көзі көбіне ашық болады әрі сергек келеді. Ему рефлексін қоса алғанда, барлық рефлекстері басқа жаңа туған бөпелерге қарағанда жақсырақ дамығандықтан, олар белсендірек болады. Алайда жүктіліктің 42-аптасына тән қауіптерге байланысты дәрігер бөпеңізді мұқият бақылау үшін тексерілуге кемінде 2 күн сайын келуіңізді сұрауы мүмкін. Жүктіліктің 42-аптасындағы тексеру бөпеңіздің жағдайын ультрадыбыстық зерттеу, КТГ, қимыл санын есептеу және қағанақ суының мөлшері сияқты көрсеткіштер негізінде бағалау үшін жүргізіледі.'), baby_message_kk = COALESCE(baby_message_kk, 'Сізді сезіп жатырмын... ❤️ Шыдамыңыздың таусылуға жақын екенін білемін. Беліңіз ауырып, аяқтарыңыз ісіп жүр. Аз қалды, Anacan, уәде беремін. Мені құшағыңызға алғанда, осы қиындықтың бәрі ұмытылады. Сіз әлемдегі ең мықты әйелсіз!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Егер толғақ өздігінен басталмаса, Сізге немесе бөпеңізге байланысты кейбір мәселелер табиғи босану кезінде асқынуларға әкелуі мүмкін болғандықтан, дәрігер босануды кесарь тілігі арқылы өткізуі ықтимал.;;;
Жатыр жиырылған кезде оттегінің азаюына байланысты бөпеңіздің жүрек соғысының баяулауы, плацентаның жатыр мойнын жауып орналасуы, бөпеңіздің қалпы табиғи босануға сәйкес келмеуі, кіндік бауының бір бөлігінің жатыр мойнынан сыртқа салбырап шығуы немесе жатыр мойнында табиғи босануға кедергі келтіретін миома, гениталдық герпес, инфекция сияқты мәселелер болса, босану кесарь тілігі арқылы жүзеге асырылады.;;;
Сондай-ақ мұндай жағдайларда мидың алдыңғы бөлігінде орналасқан гипофиз безі бөліп шығаратын және толғақты бастайтын окситоцин гормонының синтетикалық түрін, яғни жасанды толғақты қолдануға болмайды.;;;
Егер Сізге кесарь тілігі жасалатын болса, алдымен анестезиолог жалпы немесе ішінара жансыздандыру жүргізеді. Тері, теріасты қабаты, фасция, құрсақтың алдыңғы қабырғасы, сыртқы ішперде, ішкі ішперде және жатырды құрайтын бұлшықеттер 7 кезеңмен кесілгеннен кейін бөпеңіз жатқан қағанақ қабына жетеді.;;;
Дәрігер бұл қапты ашып, бөпеңізді шығарады. Кіндік бауы кесіліп, бөпеңізді алып шыққаннан кейін плацента алынып, жатырыңыз тазартылады. Соңғы кезеңде ашылған 7 қабат дұрыс әрі эстетикалық түрде тігіліп, кесарь тілігі аяқталады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Өзіңізге «Мен дайынмын, денем дайын, бөпем дайын» деген сөздерді жиі қайталаңыз. Жағымды сенім сөздері ауырсыну шегін жоғарылатып, босану үдерісінің жақсырақ өтуіне көмектеседі.') WHERE id = '3c9f9854-9405-4f6e-90ed-de351c308dea';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Жүктіліктің 42-аптасында бөпеңіздің денесін жауып тұрған ашық сары түсті верникс казеоза қабаты теріге сіңе бастаған болуы ықтимал. Верникс казеоза — жүктіліктің үшінші триместрінде түзіле бастайтын, 80%-ы судан тұратын, құрамында липидтер мен ақуыздар мол қорғаныш әрі жұқа қабат. Верникстің тері бетіндегі таралуы жүктілік аптасына, босану түріне және дене салмағына байланысты өзгереді. Верникс казеозаның құрамында микробтарды жоятын лизоцим және өкпені зақымдап, қабынуға әкелетін бактериялардың бір түрінен қорғайтын жасушалар бар. Сондай-ақ бұл крем тәрізді қабат бөпеңіздің ағзасындағы табиғи иммунитетті қолдайтын 40-қа жуық әртүрлі ақуыздан тұрады.;;;
Алайда мерзімі өтіп кеткен жүктіліктің кері әсерінен бұл қабаттың едәуір бөлігі босану басталғанға дейін теріге сіңіп кетеді. Верникс казеоза қабаты сіңгендіктен, осы кезеңде бөпеңіздің терісі аздап құрғауы мүмкін. Қағанақ суы да азайғандықтан, құрғаған терінің кейбір тұстары түлеп, қабыршақтануы ықтимал.'), baby_message_kk = COALESCE(baby_message_kk, 'Үлкен белгіні күтіп жатырмын! 🚦 Денеңіз босану гормонының (окситоциннің) мөлшерін арттырып жатыр. Мен де басыммен төмен қарай қысым жасап жатырмын. Толғақ кез келген сәтте басталуы мүмкін. Сөмкеңіз есік алдында дайын тұр ма? Меніңше, ауруханаға баратын уақыт жақындап қалды.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Осы кезеңде кесарь тілігін қажет ететін қандай да бір мәселе болмаса, дәрігер жасанды толғақтың көмегімен босануды бастауды ұсынуы мүмкін. Жағдай қалыпты болса, жүктіліктің соңғы апталары жақындағанда миыңыздағы гипофиз безінен бөлінетін окситоцин гормоны жатыр бұлшықеттеріне белгі беріп, олардың жиырылуына ықпал етеді. Бұл жиырылулар жатыр мойнының біртіндеп ашылуына әкеледі. Жатыр мойны толық ашылғанда, босанудың негізгі кезеңі басталып, бөпеңіз босану жолымен өтеді. Алайда кейбір белгісіз себептерге байланысты миыңызда окситоцин гормоны бөлінбей, толғақ басталмауы мүмкін.;;;
Жасанды толғақ — белгілі бір себептермен босану өздігінен басталмаған жағдайда, табиғи босануды дәрі-дәрмектің көмегімен бастау әдісі. Жасанды толғақ кезінде қолданылатын дәрінің құрамында жатыр бұлшықеттерін жиырылтып, босануды бастайтын окситоцин гормоны болады. «Босану индукциясы» деп аталатын бұл емшара мерзімі жеткенімен, әлі ана құрсағындағы бөпелердің табиғи жолмен (қынап арқылы) дүниеге келуі үшін жасалады. Сондай-ақ толғақ болғанымен, жатыр мойны жеткілікті жылдам ашылмаса, дәрігер босануды жеделдету үшін осы әдісті қолдануы мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Енді жолдың соңына, қауышатын сәттің басына жеттік. Бүгін тек демалыңыз. Барлық дұғаңыз бен тілегіңіз бөпеңізбен бірге болсын. Өте аз қалды, сол ғажайып иісті сезінуіңізге санаулы сағаттар қалды.') WHERE id = '9ac98c98-32af-413c-ad09-92ec7b838b44';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Егер осы кезеңге дейін босанбаған болсаңыз, бүгіннен бастап бөпеңізбен қауышасыз. 😊 Босанудың нақты басталғанын көрсететін бірнеше белгі бар. Осы белгілердің бірін байқасаңыз, уақыт жоғалтпай дәрігеріңізге хабарласуыңыз керек. «Шырышты тығын» немесе «босану белгісі» деп аталатын бұл құрылым жүктілік бойы жатыр мойнын зиянды микроағзалардан қорғап, қағанақ суының стерильді күйде сақталуын қамтамасыз етеді. Ол ағзадан босануға бірнеше апта қалғанда да, бірнеше сағат қалғанда да шығуы мүмкін. Қан араласқан осы қою шырышты бөлінді жатыр мойнының босануға дайындалып жатқанының белгісі.;;;
Біртіндеп күшейіп, тұрақты түрде қайталанатын толғақ — босанудың басталғанын білдіретін ең айқын белгі. Бұл толғақтар жалған толғаққа қарағанда күштірек болады және жатыр мойнының жылдам ашылуына көмектеседі.;;;
Қағанақ суы кеткен жағдайда уақыт жоғалтпай дәрігерге баруыңыз керек. Су бірден көп мөлшерде ағуы да, аз-аздан сыздықтап шығуы да мүмкін. Қағанақ суының кетуі босануға санаулы сағат қалғанын білдіреді. 😊'), baby_message_kk = COALESCE(baby_message_kk, 'Соңғы 24 сағат па? ⏳ 42-аптаның аяқталуына өте аз қалды. Медициналық тұрғыдан енді міндетті түрде кездесуіміз керек. Мен де Сізді сағындым. Қараңғы әлемнен Сіздің жарық әлеміңізге өтуге асығып жүрмін. Дайындалыңыз, жақында кездесеміз!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, '42-апта аяқталған кезде босануыңыз жүзеге асқан болуы керек. 9 айға созылған ұзақ әрі шаршататын сапардан кейін бөпеңізбен қауыштыңыз. 😊 Anacan отбасы ретінде Сізді және жұбайыңызды құттықтаймыз, бөпеңізбен бірге ұзақ, дені сау әрі бақытты ғұмыр кешулеріңізге тілектеспіз. Осы уақыт ішінде бізге көрсеткен қолдауыңыз үшін рақмет. Қосымшамыздың «Ана» модулінде кездескенше!'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бүгін — ғажайып орындалатын күн. Бөпеңізді құшағыңызға алғанда, бүкіл шаршағаныңыз басылады. Енді терең тыныс алып, осы тарихи сәттен ләззат алыңыз. Сіздің қолыңыздан келді!') WHERE id = '67f8b3d3-cbfc-4995-af5b-fd9e49e105ef';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіз сыртқы әлемге бұрынғыдан да жақсы дайын. Оның барлық ағзалары мен жүйелері жетіліп, толыққанды жұмыс істеуге дайын болды. Жатырыңызда орналасқан және бөпеңіздің жолдасы деп те аталатын плацента оны инфекциялардан қорғау әрі дүниеге келгеннен кейін аурулармен күресуіне көмектесу үшін антиденелер өндіруді жалғастырады. Бөпеңіздің өз антиденелерін өндіре бастауы үшін туғаннан кейін де біраз уақыт қажет болады.;;;
Бұл кезеңде бөпеңіздің иммундық жүйесінің әлі толық қалыптаспауы және өз антиденелерін өндіре алмауы Сіздің ағзаңыздағы антигендер мен бөпеңіздің антигендері арасында үйлеспеушілік реакциясының туындамауы үшін өмірлік маңызға ие.;;;
Бөпеңіздің иммундық жүйесі дүниеге келген сәттен бастап емшек сүті арқылы қарқынды дами бастайды және бүкіл балалық шағында жетілуін жалғастырады.;;;
Сүт өзектеріңізде түзілетін емшек сүтінің құрамындағы бөпеңіздің иммундық жүйесінің негізін қалайтын секреторлық IgA және антиидиотиптік антиденелер, бактерицидтік компоненттер мен лактоферрин, сондай-ақ B және T лимфоциттері оның ағзасына өтеді.;;;
Иммундық жүйенің осы элементтерінің барлығы ас қорыту жолы арқылы ішек бүрлеріне сіңіп, қан мен лимфаға өтеді. Осылайша иммундық жүйе қарқынды қалыптаса бастайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен өте ақылдымын! 🧠 Осы соңғы күндері миым қарқынды дамып жатыр. Барлық сезім мүшелерім ояу. Жарықты, дыбысты, жанасуды сеземін. Сіздің толқып жүргеніңізді де сеземін. Сабыр сақтаңыз, Anacan. Бәрі жоспар бойынша өтіп жатыр (менің жоспарым бойынша 😉).'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Босану үшін жатыр мойны бөпеңіз өте алатындай толық ашылуы керек. Егер жүктіліктің осы кезеңіне дейін жатыр мойны ашыла бастамаса және КТГ тексеруінде жатырдың жиырылуы анықталмаса, алдыңызда екі таңдау бар: кесарь тілігі немесе босануды жасанды түрде ынталандыру. Босанудың басталуын қамтамасыз ететін, яғни жатыр бұлшықеттерін жиырылтатын гормон — окситоцин. Жатыр бұлшықеттерін жиырылтып, бөпеңізді төмен қарай итеретін күш дәл осы гормонның әсерінен пайда болады. Бөпеңіздің басы жатыр мойнына қысым түсірген сайын, оның ашылуы ұлғаяды. Жатыр мойны толық ашылғанда, бөпеңіз босану жолынан өтіп, дүниеге келеді. Ағзада окситоцин жеткілікті бөлінбеген жағдайда, жасанды толғақ туғызу үшін окситоцин ерітіндісі көктамыр арқылы енгізіледі. Қандағы окситоцин деңгейі жоғарылаған кезде жатыр бұлшықеттері жиырыла бастайды. Жатыр мойны толық ашылғанға дейін Сіз жүйелі толғақты сезінесіз. Жасанды толғақтың тағайындалуына бірнеше себеп бар. Олардың қатарына босану үдерісінің тым баяу жүруі, мерзімі өтіп кеткен жүктілікте босанудың өздігінен басталмауы, жатырішілік инфекциялар және қан қысымының жоғарылауы жатады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бүгін кешке әдеттегіден сәл ертерек жатуға тырысыңыз. Босануға күш жинау маңызды. Жастықтарыңызды денеңізге барынша жайлы болатындай етіп орналастырыңыз. Түсіңізде бөпеңіздің күлкісін көріңіз!') WHERE id = '4884c66b-3927-4354-8b35-abb2fd62f234';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің эндокриндік жүйесі ағзадағы барлық үдерісті реттеуге және 9 ай бойы қорғалған жатыр ортасында болғаннан кейін сыртқы әлемге бейімделуге көмектесуге дайын. Осындай гормондардың бірі — көмірсулар алмасуына белсенді қатысатын және ағзада белгілі бір деңгейде стресс реакциясын туғызатын кортизол. Кортизол — бөпеңіздің бүйрекүсті бездерінде түзіліп, қанға бөлінетін стероидты, яғни липидтік табиғаты бар гормон. Бұл гормонның өндірілуі бөпеңіздің ағзасына ширығу кезінде көмектеседі. Кортизол туғызатын стресс реакциясының әсерінен бөпеңіздің жүрегі, дене бұлшықеттері мен миы белгілі бір дәрежеде шынығады. Соның арқасында бөпеңіз дүниеге келгеннен кейін тіршілікке бейімделу үшін азырақ көмекке мұқтаж болады.;;;
Әсіресе босану кезінде бөлінетін кортизол стресс әсерінен түзілетін тағы бір гормон — адреналиннің бөлінуін ынталандырады. Адреналин бөпеңізге күш-қуат беріп, белсенділігін арттырады. Бұл қуат бөпеңіздің босану кезінде және сыртқы әлеммен танысқан алғашқы сағаттарда жаңа ортаға бейімделуіне жан-жақты көмектеседі.'), baby_message_kk = COALESCE(baby_message_kk, 'Шабаданым дайын! 🧳 Мен толықтай дайынмын. Өкпем алғашқы демді алуға, ал асқазаным ана сүтіне дайын. Тек "есіктің ашылуын" күтіп отырмын. Мүмкін, аздап серуендеп қайтарсыз? Бұл маған жолды табуға көмектесер еді.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Егер босану әлі басталмаса, өзіңізді қатты шаршағандай сезінуіңіз мүмкін. Күйзеліс пен алаңдаушылықтан бірнеше түн қатарынан ұйықтай алмау шаршауыңызды одан сайын күшейтуі ықтимал. Бұл кезеңде емізігіңізден сүт бөлінсе, бұл — омырауыңызды емізуге дайындайтын гормондардың әсерінен болатын қалыпты жағдай.;;;
Жүктіліктің 40 аптасы аяқталғанына қарамастан босану басталмаса, бөпеңізде меконий аспирациясы туындауы мүмкін. Әдетте туғаннан кейінгі алғашқы 24 сағат ішінде шығатын және бөпеңіздің ішегінде жиналған алғашқы нәжіс стресс пен оттегінің жетіспеуі салдарынан ол дүниеге келмей тұрып бөлінуі мүмкін. Бұл нәжіс тыныс алу жолдары арқылы бөпеңіздің өкпесіне түссе, қауіпті болады. Меконий жабысқақ әрі қою болғандықтан, өкпеге түскен кезде тыныс алу қызметін бұзуы мүмкін. Бұл жағдай меконий аспирациясы деп аталады. Бөпеңіз меконий бөлген кезде қағанақ суының түсі жасылға өзгереді. Сондықтан бөлінділеріңізді жиі бақылап, бөпеңіздің қимылы айтарлықтай азайғанын сезсеңіз, дереу жақын жердегі медициналық мекемеге жүгінуіңіз керек.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Жұбайыңыздан немесе жақын адамыңыздан иығыңызға жеңіл массаж жасап беруін сұраңыз. Жанасудан туындайтын тыныштық сезімі ағзаңыздағы окситоциннің (махаббат гормонының) деңгейін жоғарылатып, босануды жеңілдетеді.') WHERE id = 'acaaba70-7d7b-40eb-88be-941234cfb162';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Жүктілік мерзімінің өтіп кетуіне байланысты бөпеңіздің плацентасы қартая бастауы мүмкін. Егер бұл өзгеріс бөпеңізге оттегінің жеткілікті мөлшерде жетуіне және салмақ қосуына кедергі келтірмесе, алаңдауға негіз жоқ. Плацента — бүкіл жүктілік бойы бөпеңіз бен Сіздің ағзаңыз арасындағы зат алмасуды қамтамасыз ететін мүше. Ол ұрықтанудан кейінгі өте ерте кезеңде қалыптасып, дамиды, ал бөпеңіз туғаннан кейін көп ұзамай жатырдан бөлініп шығады. Босанғаннан кейін бөлінетін плацентаның салмағы шамамен 500 грамм, диаметрі 20-25 см, қалыңдығы 2-3 см болады және пішіні жалпақ келеді. Плацентаның қартаюы, әсіресе жүктіліктің 36-аптасынан кейін, қалыпты жағдай болып саналады. Шын мәнінде, плацентаның қартаюы деп аталатын жағдай — оның тіндерінде кальций минералдарының жиналуы.'), baby_message_kk = COALESCE(baby_message_kk, 'Мүмкін, көмек керек шығар? 🩺 Дәрігерлер босануды бастау (индукция) туралы айтып жатқан болар. Қорықпаңыз. Мен дүниеге келгім келеді, тек кейде табиғатқа кішкентай серпін қажет болады. Қалай дүниеге келетінім маңызды емес, ең бастысы — біз қауышамыз.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қарбыз'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің екінші триместрі басталғанда ентігу пайда болуы мүмкін. Ал үшінші триместрде ентігу айтарлықтай күшейеді. Көкет бұлшықеті жоғары қарай ығысқандықтан, өкпеңіз қысылады. Өкпеге ауа кіретін кеңістік тарылып, оның сыйымдылығы азаяды. Соның салдарынан тыныс алу едәуір қиындап, "ауа жетіспеу" сезімі туындауы мүмкін.;;;
Жүктілік кезінде әйелдердің барлығына дерлік тән тыныс алудың қиындауын тыныс алу жаттығулары арқылы көкетті нығайту жолымен айтарлықтай азайтуға болады. Сонымен қатар тыныс алу жаттығуларын жүйелі орындасаңыз, өкпеңіздің сыйымдылығы артып, бөпеңізге жеткізілетін оттегінің мөлшері көбейеді.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бүгін қандай да бір толғақ сезсеңіз, қорықпаңыз. Әрбір толғақ — Сізді бөпеңізге тағы бір қадам жақындататын "толқын". Осы толқынмен сенімді түрде жүзіп, қорқынышқа бой алдырмаңыз.') WHERE id = '39da3e28-3bb4-466f-a4b2-49f4aa6296da';

