UPDATE public.safety_items SET name_kk = COALESCE(name_kk, 'Күн сәулесінің әсері'), description_kk = COALESCE(description_kk, 'Күн сәулесінің қалыпты әсері әдетте қауіпсіз және D дәруменінің түзілуіне көмектеседі. Алайда күн астында ұзақ уақыт болу сусыздануға, ыстық өтуіне және күнге күюге әкелуі мүмкін, бұл жайсыздық тудырып, денсаулыққа зиян келтіруі ықтимал. Тікелей күн сәулесінің әсерін, әсіресе ең ыстық уақытта (таңғы 10-нан кешкі 4-ке дейін) шектеу, денені қорғайтын киім кию, күннен қорғайтын крем қолдану және сұйықтықты көбірек ішу ұсынылады.') WHERE id = '3982c1ae-13f7-4142-8726-4f0481aa7c58';
