UPDATE public.safety_items SET name_kk = COALESCE(name_kk, 'Ұшақпен ұшу'), description_kk = COALESCE(description_kk, 'Коммерциялық әуе компанияларының ұшақтарымен ұшу жүктілік кезінде жалпы қауіпсіз деп саналады. Дегенмен, әсіресе ұзақ сапар алдында, жүктілікке байланысты қандай да бір мәселе болмаса да, дәрігеріңізбен кеңескен жөн. Суды көп ішіңіз, қан ұйып қалмауы үшін қозғалып тұрыңыз және ұсынылса, компрессиялық шұлық киіңіз. Бұл ұсынымдар емізетін аналарға да қатысты, алайда ұзақ ұшу кезінде бөпені тамақтандыру және оның жайлылығы үшін қосымша дайындалған пайдалы.') WHERE id = 'b0855f6d-792e-4d72-a4d4-3509c5e9f5a1';
UPDATE public.safety_items SET name_kk = COALESCE(name_kk, 'Албырт (Семга)'), description_kk = COALESCE(description_kk, 'Омега-3 көзі. Аптасына 2 ретке дейін, толық пісірілген күйде тұтыну ұсынылады.') WHERE id = 'b0c7bfda-4110-4f88-8a68-a6303d1447c6';
UPDATE public.safety_items SET name_kk = COALESCE(name_kk, 'Ұшу'), description_kk = COALESCE(description_kk, 'Коммерциялық рейстер жүктілік кезінде жалпы қауіпсіз деп саналады. Әсіресе үшінші триместрде ұшу туралы дәрігеріңізбен кеңесіп, қан ұйып қалмауы үшін суды көп ішу және қозғалып тұру сияқты сақтық шараларын қолданған жөн. Бұл ұсынымдар емізетін аналарға да қатысты, алайда ұзақ ұшу кезінде бөпені тамақтандыру және оның жайлылығы үшін қосымша дайындалу қажет.') WHERE id = 'b1a7ab3d-fa21-4a98-ae31-159ea5e65822';
UPDATE public.safety_items SET name_kk = COALESCE(name_kk, 'Сужық'), description_kk = COALESCE(description_kk, 'Сужықты емізу кезеңінде мөлшермен тұтыну әдетте қауіпсіз, алайда оның құрамында натрий мен майдың көп екенін ескеру маңызды. Сондай-ақ ащы тағамдар кейде ана сүті арқылы бөпеге әсер етіп, мазасыздық немесе ас қорыту мәселелерін тудыруы мүмкін. Бөпеңіздің реакциясын бақылаңыз.') WHERE id = 'b4267eb3-6e6a-46f3-93ce-1dab05fea063';
