UPDATE public.teething_care_tips SET title_kk = COALESCE(title_kk, 'Қанттан бас тартыңыз'), content_kk = COALESCE(content_kk, 'Тістің ерте жастан бұзылуына жол бермеу үшін, әсіресе ұйықтар алдында қантты тағамдар мен сусындарды бермеңіз.') WHERE id = '5c0c2cd7-bbc3-4acf-aa29-a75ff9325110';
